-- Foto de la base entera.
--
-- Qué hace: arma desde cero todo el esquema —tablas, columnas, reglas de acceso, funciones,
-- disparadores, restricciones, índices, permisos y enumerados—, siembra las filas del catálogo
-- que el producto trae de fábrica y crea los depósitos de archivos con sus políticas.
--
-- Una carpeta de migraciones es la receta para armar la base desde cero. Esta foto es la única
-- hoja de esa receta hasta acá; lo que cambie de ahora en más va en migraciones nuevas, adelante.

CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA "extensions";
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA "extensions";
CREATE EXTENSION IF NOT EXISTS "btree_gist" WITH SCHEMA "extensions";

-- El rol del trabajo sin persona. PostgREST entra como `authenticator` y cambia al rol que dice
-- la credencial, así que `authenticator` tiene que poder asumirlo.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'trabajo_sin_persona') THEN
    CREATE ROLE trabajo_sin_persona NOLOGIN NOINHERIT;
  END IF;
END $$;
GRANT trabajo_sin_persona TO authenticator;

--
--



SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET transaction_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

--
-- Name: interno; Type: SCHEMA; Schema: -; Owner: -
--

CREATE SCHEMA interno;


--
-- Name: SCHEMA interno; Type: COMMENT; Schema: -; Owner: -
--

COMMENT ON SCHEMA interno IS 'Funciones internas de la base: las que usan las políticas de RLS. Está fuera de la lista de esquemas publicados de supabase/config.toml a propósito, para que no sean direcciones web. Acá no van tablas ni datos.';


--
-- Name: public; Type: SCHEMA; Schema: -; Owner: -
--



--
-- Name: SCHEMA public; Type: COMMENT; Schema: -; Owner: -
--

COMMENT ON SCHEMA public IS 'standard public schema';


