);


--
-- Name: moneda_iso; Type: DOMAIN; Schema: public; Owner: -
--

CREATE DOMAIN public.moneda_iso AS text
	CONSTRAINT moneda_iso_tres_letras CHECK ((VALUE ~ '^[A-Z]{3}$'::text));


