-- Name: DOMAIN moneda_iso; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON DOMAIN public.moneda_iso IS 'Código de moneda de tres letras mayúsculas (ISO 4217): ARS, BRL, UYU, USD. Regla 14 de CLAUDE.md §7.';


--
-- Name: alarmas_a_la_vista_del_coordinador(text); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.alarmas_a_la_vista_del_coordinador(p_tipo text) RETURNS uuid[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid := interno.current_tenant();
  v_llegaron uuid[];
  v_abiertas uuid[];
BEGIN
  IF v_prestadora IS NULL OR NOT interno.es_coordinador() THEN
    RETURN '{}';
  END IF;

  SELECT coalesce(array_agg(e.referencia_id), '{}') INTO v_llegaron
    FROM escalones_de_alarma_avisados e
   WHERE e.prestadora_id = v_prestadora
     AND e.tipo = p_tipo
     AND e.escalon = 'todos_los_coordinadores';

  IF p_tipo = 'alerta_temprana_guardia' THEN
    SELECT coalesce(array_agg(x.id), '{}') INTO v_abiertas FROM alertas_tempranas_guardia x
     WHERE x.id = ANY (v_llegaron) AND x.resuelto_at IS NULL;
  ELSIF p_tipo = 'incidente_relevo' THEN
    SELECT coalesce(array_agg(x.id), '{}') INTO v_abiertas FROM incidentes_relevo x
     WHERE x.id = ANY (v_llegaron) AND x.resuelto_at IS NULL;
  ELSIF p_tipo = 'incidente_turno_sin_cubrir' THEN
    SELECT coalesce(array_agg(x.id), '{}') INTO v_abiertas FROM incidentes_turno_sin_cubrir x
     WHERE x.id = ANY (v_llegaron) AND x.resuelto_at IS NULL;
  ELSIF p_tipo = 'emergencia_guardia' THEN
    SELECT coalesce(array_agg(x.id), '{}') INTO v_abiertas FROM emergencias_guardia x
     WHERE x.id = ANY (v_llegaron) AND x.atendida_at IS NULL;
  ELSIF p_tipo = 'guardia_sin_cerrar' THEN
    SELECT coalesce(array_agg(x.id), '{}') INTO v_abiertas FROM guardias x
     WHERE x.id = ANY (v_llegaron) AND x.estado = 'activa';
  ELSE
    v_abiertas := '{}';
  END IF;

  RETURN v_abiertas || interno.alarmas_que_tengo_tomadas(p_tipo);
END;
$$;


--
-- Name: alarmas_que_tengo_tomadas(text); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.alarmas_que_tengo_tomadas(p_tipo text) RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT coalesce(array_agg(a.referencia_id), '{}')
    FROM alarmas_tomadas a
   WHERE a.prestadora_id = interno.current_tenant()
     AND a.tipo = p_tipo
     AND a.tomada_por = auth.uid()
     AND a.soltada_at IS NULL
     AND a.vence_at > now();
$$;


--
-- Name: alcanza_la_informacion_de_salud(uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.alcanza_la_informacion_de_salud(p_paciente uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT p_paciente IS NOT NULL
     AND (NOT interno.rige_la_restriccion_de_hce(interno.current_tenant())
          OR interno.atiende_al_paciente(p_paciente)
          OR (interno.es_admin_prestadora()
              AND EXISTS (SELECT 1 FROM pacientes p
                           WHERE p.id = p_paciente
                             AND p.prestadora_id = interno.current_tenant())))
$$;


--
-- Name: anotar_cambio_de_fecha_de_ausencia(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.anotar_cambio_de_fecha_de_ausencia() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
BEGIN
  IF NEW.fecha_fin IS DISTINCT FROM OLD.fecha_fin THEN
    INSERT INTO public.ausencias_cambios_de_fecha (prestadora_id, ausencia_id, fecha_anterior, fecha_nueva)
    VALUES (NEW.prestadora_id, NEW.id, OLD.fecha_fin, NEW.fecha_fin);
    NEW.pregunta_vuelta_at := NULL;
    NEW.pregunta_vuelta_veces := 0;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: anotar_cambio_del_interruptor_de_salud(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.anotar_cambio_del_interruptor_de_salud() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  v_antes boolean := CASE WHEN TG_OP = 'UPDATE' THEN OLD.restriccion_de_hce ELSE true END;
BEGIN
  IF v_antes IS NOT DISTINCT FROM NEW.restriccion_de_hce OR auth.uid() IS NULL THEN
    RETURN NULL;
  END IF;

  INSERT INTO registro_actividad
    (prestadora_id, usuario_id, accion, tabla_afectada, registro_id, campos_cambiados, detalle)
  VALUES
    (NEW.prestadora_id, auth.uid(), 'cambio_de_permisos_de_la_prestadora',
     TG_TABLE_NAME, NEW.prestadora_id, ARRAY['restriccion_de_hce'],
     jsonb_build_object('alcance_anterior', v_antes, 'alcance_nuevo', NEW.restriccion_de_hce));

  RETURN NULL;
END;
$$;


--
-- Name: anotar_version_clinica(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.anotar_version_clinica() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  v_fila      jsonb;
  v_anterior  jsonb;
  v_operacion text;
  v_version   integer;
  v_prest     uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_fila := to_jsonb(OLD);
    v_operacion := 'baja';
  ELSIF TG_OP = 'INSERT' THEN
    v_fila := to_jsonb(NEW);
    v_operacion := 'alta';
  ELSE
    v_fila := to_jsonb(NEW);
    v_anterior := to_jsonb(OLD);
    -- Una escritura que no cambia ningún dato y no trae nota no es una versión nueva.
    IF (v_fila - 'updated_at' - 'nota_aclaratoria') = (v_anterior - 'updated_at' - 'nota_aclaratoria')
       AND (v_fila ->> 'nota_aclaratoria') IS NULL THEN
      RETURN NULL;
    END IF;
    v_operacion := 'modificacion';
  END IF;

  v_prest := (v_fila ->> 'prestadora_id')::uuid;
  IF v_prest IS NULL THEN
    RAISE EXCEPTION 'Un registro clínico sin Prestadora no se puede versionar';
  END IF;

  SELECT COALESCE(MAX(version), 0) + 1 INTO v_version
    FROM versiones_registro_clinico
   WHERE tabla = TG_TABLE_NAME AND registro_id = (v_fila ->> 'id')::uuid;

  INSERT INTO versiones_registro_clinico
    (prestadora_id, paciente_id, tabla, registro_id, version, operacion, datos,
     nota_aclaratoria, autor_id, credencial_rol)
  VALUES
    (v_prest, (v_fila ->> 'paciente_id')::uuid, TG_TABLE_NAME, (v_fila ->> 'id')::uuid, v_version,
     v_operacion, v_fila, CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE v_fila ->> 'nota_aclaratoria' END,
     auth.uid(), COALESCE(auth.jwt() ->> 'role', session_user::text));

  RETURN NULL;
END;
$$;


--
-- Name: asignar_numero_de_cliente(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.asignar_numero_de_cliente() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
BEGIN
  IF NEW.numero_cliente IS NOT NULL THEN
    RAISE EXCEPTION 'numero_de_cliente_no_se_elige';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('clientes:' || NEW.prestadora_id::text));

  SELECT COALESCE(max(numero_cliente), 0) + 1
    INTO NEW.numero_cliente
    FROM public.clientes
   WHERE prestadora_id = NEW.prestadora_id;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION asignar_numero_de_cliente(); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.asignar_numero_de_cliente() IS 'El numero de cliente, uno mas que el mayor de esa Prestadora. No se reasigna porque ningún Cliente se borra de la tabla.';


--
-- Name: asignar_numero_de_legajo(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.asignar_numero_de_legajo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
BEGIN
  IF NEW.numero_legajo IS NOT NULL THEN
    RAISE EXCEPTION 'numero_de_legajo_no_se_elige';
  END IF;

  -- El candado es por Prestadora y dura lo que dura la transacción. Sin él, dos altas a la vez
  -- leen el mismo máximo y las dos piden el mismo número: una falla y la otra no, pero la que
  -- falla es un alta perdida por una razón que quien la cargó no puede entender.
  PERFORM pg_advisory_xact_lock(hashtext('legajos:' || NEW.prestadora_id::text));

  SELECT COALESCE(max(numero_legajo), 0) + 1
    INTO NEW.numero_legajo
    FROM public.legajos
   WHERE prestadora_id = NEW.prestadora_id;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION asignar_numero_de_legajo(); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.asignar_numero_de_legajo() IS 'El numero de legajo, uno mas que el mayor de esa Prestadora. No se reasigna porque ningun Legajo se borra.';


--
-- Name: asistente_atiende_al_cliente(uuid, uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.asistente_atiende_al_cliente(p_asistente_id uuid, p_cliente_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM guardia_pacientes gp
    JOIN guardias g ON g.id = gp.guardia_id
    JOIN pacientes p ON p.id = gp.paciente_id
    WHERE g.asistente_id = p_asistente_id
      AND p.cliente_id = p_cliente_id
  )
$$;


--
-- Name: FUNCTION asistente_atiende_al_cliente(p_asistente_id uuid, p_cliente_id uuid); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.asistente_atiende_al_cliente(p_asistente_id uuid, p_cliente_id uuid) IS 'Si un Asistente tiene alguna guardia con algún Paciente de ese Cliente.';


--
-- Name: asistente_de_la_sesion(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.asistente_de_la_sesion() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT a.id
    FROM asistentes a
   WHERE a.usuario_id = auth.uid()
     AND a.prestadora_id = interno.current_tenant()
   LIMIT 1
$$;


--
-- Name: FUNCTION asistente_de_la_sesion(); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.asistente_de_la_sesion() IS 'La ficha de Asistente de quien inició sesión, en la Prestadora donde está parado. Nula si en esa Prestadora no es Asistente.';


--
-- Name: asistente_trabaja_en_modalidad(uuid, text); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.asistente_trabaja_en_modalidad(p_asistente_id uuid, p_modalidad text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(p_modalidad = ANY(a.canales), false)
    FROM public.asistentes a
   WHERE a.id = p_asistente_id;
$$;


--
-- Name: FUNCTION asistente_trabaja_en_modalidad(p_asistente_id uuid, p_modalidad text); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.asistente_trabaja_en_modalidad(p_asistente_id uuid, p_modalidad text) IS 'Si este Asistente trabaja en esa modalidad. La usan las tres puertas: asignar una guardia, armar una serie e invitar (regla 12).';


--
-- Name: atiende_al_paciente(uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.atiende_al_paciente(p_paciente uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  WITH yo AS (
    SELECT auth.uid()                       AS uid,
           interno.current_tenant()         AS tenant,
           interno.asistente_de_la_sesion() AS asistente
  ),
  pac AS (
    SELECT p.id, p.cliente_id
      FROM pacientes p, yo
     WHERE p.id = p_paciente
       AND p.prestadora_id = yo.tenant
  )
  SELECT EXISTS (
    SELECT 1
      FROM pac, yo
     WHERE yo.uid IS NOT NULL
       AND (
         -- Quien recibe el Servicio.
         pac.cliente_id = interno.cliente_id_de_usuario(yo.uid)

         -- Quien la Prestadora sumó al equipo.
         OR EXISTS (
           SELECT 1 FROM equipo_paciente e
            WHERE e.paciente_id = pac.id
              AND e.prestadora_id = yo.tenant
              AND e.situacion = 'sumada'
              AND (e.usuario_id = yo.uid
                   OR (yo.asistente IS NOT NULL AND e.asistente_id = yo.asistente))
         )

         -- Quien lo presta, guardia por guardia.
         OR EXISTS (
           SELECT 1
             FROM guardias g
             JOIN servicios s ON s.id = g.servicio_id
                             AND s.prestadora_id = g.prestadora_id
                             AND s.estado = 'vigente'
            WHERE g.prestadora_id = yo.tenant
              AND g.estado <> 'cancelada'
              AND (g.paciente_id = pac.id
                   OR EXISTS (SELECT 1 FROM guardia_pacientes gp
                               WHERE gp.guardia_id = g.id AND gp.paciente_id = pac.id))
              AND ((yo.asistente IS NOT NULL AND g.asistente_id = yo.asistente)
                   OR g.coordinador_id = yo.uid
                   OR (g.asistente_id IS NOT NULL
                       AND interno.coordinador_alcanza_asistente(g.asistente_id)))
         )

         -- Quien lo presta por una serie que sigue en pie.
         OR EXISTS (
           SELECT 1
             FROM series_guardias sg
             JOIN servicios s ON s.id = sg.servicio_id
                             AND s.prestadora_id = sg.prestadora_id
                             AND s.estado = 'vigente'
            WHERE sg.prestadora_id = yo.tenant
              AND sg.estado <> 'cancelada'
              AND (sg.paciente_id = pac.id
                   OR EXISTS (SELECT 1 FROM series_guardias_pacientes sp
                               WHERE sp.serie_id = sg.id AND sp.paciente_id = pac.id))
              AND ((yo.asistente IS NOT NULL AND sg.asistente_id = yo.asistente)
                   OR (sg.asistente_id IS NOT NULL
                       AND interno.coordinador_alcanza_asistente(sg.asistente_id)))
         )

         -- Quien tiene tomada una alarma de una de sus guardias, mientras la tenga.
         OR EXISTS (
           SELECT 1
             FROM guardias g
            WHERE g.prestadora_id = yo.tenant
              AND g.id = ANY (interno.guardias_a_la_vista_por_una_alarma(true))
              AND (g.paciente_id = pac.id
                   OR EXISTS (SELECT 1 FROM guardia_pacientes gp
                               WHERE gp.guardia_id = g.id AND gp.paciente_id = pac.id))
         )
       )
  )
$$;


--
-- Name: cerrar_vigencia_de_la_prestacion(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.cerrar_vigencia_de_la_prestacion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  recien_se_da_de_baja boolean;
  la_trae_escrita boolean;
BEGIN
  IF NEW.estado <> 'de_baja' THEN
    RETURN NEW;
  END IF;

  recien_se_da_de_baja := TG_OP = 'INSERT' OR OLD.estado <> 'de_baja';
  la_trae_escrita := CASE
    WHEN TG_OP = 'INSERT' THEN NEW.vigente_hasta IS NOT NULL
    ELSE NEW.vigente_hasta IS DISTINCT FROM OLD.vigente_hasta
  END;

  IF recien_se_da_de_baja AND NOT la_trae_escrita THEN
    -- `GREATEST` cubre la prestacion que se da de baja antes de arrancar: no
    -- puede terminar antes de empezar, y la restriccion de mas arriba lo exige.
    NEW.vigente_hasta := GREATEST(NEW.vigente_desde, CURRENT_DATE);
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: cliente_id_de_usuario(uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.cliente_id_de_usuario(p_usuario_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT COALESCE(
    (SELECT f.id FROM clientes f
      WHERE f.usuario_id = p_usuario_id
        AND f.prestadora_id = interno.current_tenant()
      LIMIT 1),
    (SELECT m.cliente_id FROM personas_autorizadas m
      WHERE m.usuario_id = p_usuario_id
      LIMIT 1)
  )
$$;


--
-- Name: conversacion_match_es_propia(uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.conversacion_match_es_propia(p_conversacion_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM conversaciones_match c
     WHERE c.id = p_conversacion_id
       -- Primero la Prestadora, que sale de la cuenta con la que se entró y de ningún otro lado.
       AND c.prestadora_id = interno.current_tenant()
       -- Y después una de las dos puntas. Quien no es ninguna de las dos no resuelve nada:
       -- comparar contra una ficha que no existe da desconocido, y desconocido no deja pasar.
       AND (
            c.cliente_id = interno.cliente_id_de_usuario(auth.uid())
         OR c.asistente_id = interno.asistente_de_la_sesion()
       )
  )
$$;


--
-- Name: FUNCTION conversacion_match_es_propia(p_conversacion_id uuid); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.conversacion_match_es_propia(p_conversacion_id uuid) IS 'Si el hilo de Match es de quien esta consultando: de su Prestadora, y con el como una de las dos puntas. Lo consultan las politicas de conversaciones_match y de mensajes_match, y es el unico lugar donde esa pregunta esta escrita.';


--
-- Name: coordinador_alcanza_asistente(uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.coordinador_alcanza_asistente(p_asistente_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT interno.coordinador_alcanza_asistente_de(auth.uid(), p_asistente_id);
$$;


--
-- Name: FUNCTION coordinador_alcanza_asistente(p_asistente_id uuid); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.coordinador_alcanza_asistente(p_asistente_id uuid) IS 'Si quien esta mirando coordina alguno de los lugares donde ese Asistente acepta trabajar.';


--
-- Name: coordinador_alcanza_asistente_de(uuid, uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.coordinador_alcanza_asistente_de(p_usuario uuid, p_asistente_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM usuarios u
    JOIN usuario_lugares ul ON ul.usuario_id = u.id
    JOIN asistente_lugares al ON al.lugar_id = ul.lugar_id
    WHERE u.id = p_usuario
      AND u.rol = 'coordinador'
      AND al.asistente_id = p_asistente_id
  )
  OR EXISTS (
    SELECT 1
    FROM usuarios u
    JOIN ausencias a ON a.coordinador_que_cubre_id = u.id
                    AND a.prestadora_id = u.prestadora_id
    JOIN usuario_lugares ul ON ul.usuario_id = a.usuario_id
                           AND ul.prestadora_id = a.prestadora_id
    JOIN asistente_lugares al ON al.lugar_id = ul.lugar_id
    WHERE u.id = p_usuario
      AND u.rol = 'coordinador'
      AND a.usuario_id IS NOT NULL
      AND a.fecha_inicio <= current_date
      AND (a.fecha_vuelta_real IS NULL OR a.fecha_vuelta_real > current_date)
      AND al.asistente_id = p_asistente_id
  );
$$;


--
-- Name: coordinador_alcanza_guardia(uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.coordinador_alcanza_guardia(p_asistente_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT p_asistente_id IS NULL
      OR interno.coordinador_alcanza_asistente(p_asistente_id);
$$;


--
-- Name: FUNCTION coordinador_alcanza_guardia(p_asistente_id uuid); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.coordinador_alcanza_guardia(p_asistente_id uuid) IS 'Si un Coordinador alcanza lo que pasa por ese Asistente: comparte zona con él, o no hay Asistente todavía. La usan las políticas de guardias y de series_guardias, y es el único lugar donde está escrita esa regla.';


--
-- Name: current_tenant(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.current_tenant() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT COALESCE(
    -- 1. La sesión de soporte técnico, mientras está viva. Tapa todo lo demás.
    (SELECT s.prestadora_id FROM permisos_de_acceso s
      WHERE s.admin_id = auth.uid()
        AND s.salida_at IS NULL
        AND s.expira_at > NOW()
        AND s.ultima_actividad_at > NOW() - INTERVAL '5 minutes'
      ORDER BY s.entrada_at DESC LIMIT 1),

    -- 2. La Prestadora de la cuenta con la que se entró. Es una sola: para trabajar en otra hay
    --    que salir de ésta y entrar allá, con la cuenta de allá.
    (SELECT prestadora_id FROM usuarios WHERE id = auth.uid()),

    -- 3. El trabajo sin persona: la Prestadora para la que el backend generó su credencial.
    (SELECT NULLIF(auth.jwt() ->> 'prestadora_id', '')::uuid
      WHERE auth.jwt() ->> 'role' = 'trabajo_sin_persona')
  )
$$;


--
-- Name: el_apoderado_es_una_persona(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.el_apoderado_es_una_persona() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  v_clase text;
BEGIN
  IF NEW.apoderado_legajo_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.apoderado_legajo_id = NEW.id THEN
    RAISE EXCEPTION 'el_apoderado_no_es_la_entidad_misma';
  END IF;

  -- La Prestadora va en la condición y no se da por sabida: la clave foránea ya lo exige, y acá se
  -- repite para que esta consulta no pueda mirar el Padrón de otra Organización.
  SELECT clase INTO v_clase
    FROM public.legajos
   WHERE id = NEW.apoderado_legajo_id
     AND prestadora_id = NEW.prestadora_id;

  IF v_clase IS NULL THEN
    RAISE EXCEPTION 'el_apoderado_no_esta_en_el_padron';
  END IF;

  IF v_clase <> 'fisica' THEN
    RAISE EXCEPTION 'el_apoderado_es_una_persona';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION el_apoderado_es_una_persona(); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.el_apoderado_es_una_persona() IS 'El Apoderado de una entidad tiene que ser un Legajo de clase fisica de la misma Prestadora, y no la entidad misma.';


--
-- Name: el_estado_se_resuelve_no_se_pisa(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.el_estado_se_resuelve_no_se_pisa() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  v_estado_resuelto text;
BEGIN
  -- La última resolución de esta misma fila. `created_at` no alcanza para desempatar dentro de una
  -- transacción, así que desempata la secuencia, igual que en `resoluciones_vigentes`.
  SELECT r.estado
    INTO v_estado_resuelto
    FROM public.resoluciones r
   WHERE r.prestadora_id = NEW.prestadora_id
     AND r.tabla = TG_TABLE_NAME
     AND r.fila_id = NEW.id::text
   ORDER BY r.created_at DESC, r.secuencia DESC
   LIMIT 1;

  IF v_estado_resuelto IS NULL OR v_estado_resuelto IS DISTINCT FROM NEW.estado THEN
    RAISE EXCEPTION 'el_estado_se_resuelve_no_se_pisa';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION el_estado_se_resuelve_no_se_pisa(); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.el_estado_se_resuelve_no_se_pisa() IS 'Impide escribir el estado a mano: solo queda el que diga la ultima resolucion de esa fila, que escribe public.resolver con el motivo y la firma de quien decidio.';


