CREATE FUNCTION interno.el_pais_exige_la_restriccion_de_hce(p_prestadora uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM prestadoras p
      JOIN requerimientos_legales_de_hce_por_pais e ON e.jurisdiccion = p.pais
     WHERE p.id = p_prestadora
       AND e.requerimiento = 'restriccion_de_hce'
  )
$$;


--
-- Name: el_registro_clinico_se_ve(text, uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.el_registro_clinico_se_ve(p_tabla text, p_registro_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'interno'
    AS $_$
DECLARE
  v_tabla regclass := to_regclass(format('public.%I', p_tabla));
  v_se_ve boolean;
BEGIN
  IF v_tabla IS NULL OR NOT EXISTS (
    SELECT 1 FROM pg_trigger
     WHERE tgrelid = v_tabla AND tgname = 'trg_versiones_del_registro_clinico'
  ) THEN
    RETURN false;
  END IF;
  EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s WHERE id = $1)', v_tabla)
     INTO v_se_ve USING p_registro_id;
  RETURN COALESCE(v_se_ve, false);
END;
$_$;


