-- Name: gestiona_la_facturacion(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.gestiona_la_facturacion() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT interno.es_personal_de_la_prestadora();
$$;


--
-- Name: FUNCTION gestiona_la_facturacion(); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.gestiona_la_facturacion() IS 'Único punto de verdad de quién puede ver y mover la facturación y los cobros de una Prestadora. El tenant se comprueba aparte, en cada política.';


--
-- Name: guardias_a_la_vista_por_una_alarma(boolean); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.guardias_a_la_vista_por_una_alarma(p_solo_las_tomadas boolean) RETURNS uuid[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  v_tipo text;
  v_guardias uuid[] := '{}';
  v_referencias uuid[];
BEGIN
  IF NOT interno.es_coordinador() THEN
    RETURN '{}';
  END IF;
  FOREACH v_tipo IN ARRAY ARRAY['alerta_temprana_guardia', 'incidente_relevo', 'guardia_sin_cerrar',
                                'incidente_turno_sin_cubrir', 'emergencia_guardia'] LOOP
    v_referencias := CASE WHEN p_solo_las_tomadas THEN interno.alarmas_que_tengo_tomadas(v_tipo)
                          ELSE interno.alarmas_a_la_vista_del_coordinador(v_tipo) END;
    IF cardinality(v_referencias) > 0 THEN
      v_guardias := v_guardias || ARRAY(SELECT interno.guardias_de_las_alarmas(v_tipo, v_referencias));
    END IF;
  END LOOP;
  RETURN v_guardias;
END;
$$;


--
-- Name: guardias_de_las_alarmas(text, uuid[]); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.guardias_de_las_alarmas(p_tipo text, p_referencias uuid[]) RETURNS SETOF uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
BEGIN
  IF p_tipo = 'alerta_temprana_guardia' THEN
    RETURN QUERY SELECT x.guardia_id FROM alertas_tempranas_guardia x WHERE x.id = ANY (p_referencias);
  ELSIF p_tipo = 'incidente_relevo' THEN
    RETURN QUERY SELECT x.guardia_entrante_id FROM incidentes_relevo x
                  WHERE x.id = ANY (p_referencias) AND x.guardia_entrante_id IS NOT NULL
                 UNION
                 SELECT x.guardia_saliente_id FROM incidentes_relevo x
                  WHERE x.id = ANY (p_referencias) AND x.guardia_saliente_id IS NOT NULL;
  ELSIF p_tipo = 'incidente_turno_sin_cubrir' THEN
    RETURN QUERY SELECT x.guardia_id FROM incidentes_turno_sin_cubrir x WHERE x.id = ANY (p_referencias);
  ELSIF p_tipo = 'emergencia_guardia' THEN
    RETURN QUERY SELECT x.guardia_id FROM emergencias_guardia x WHERE x.id = ANY (p_referencias);
  ELSIF p_tipo = 'guardia_sin_cerrar' THEN
    RETURN QUERY SELECT unnest(p_referencias);
  END IF;
END;
$$;


--
-- Name: guardias_del_paciente(uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.guardias_del_paciente(p_paciente_id uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT guardia_id FROM guardia_pacientes WHERE paciente_id = p_paciente_id
$$;


--
-- Name: FUNCTION guardias_del_paciente(p_paciente_id uuid); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.guardias_del_paciente(p_paciente_id uuid) IS 'En qué guardias aparece un Paciente. Punto único de verdad de las reglas de acceso.';


--
-- Name: i18n_completo(jsonb); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.i18n_completo(p_texto jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT p_texto IS NOT NULL
     AND jsonb_typeof(p_texto) = 'object'
     AND btrim(coalesce(p_texto ->> 'es-AR', '')) <> ''
     AND btrim(coalesce(p_texto ->> 'en', '')) <> ''
     AND btrim(coalesce(p_texto ->> 'pt-BR', '')) <> '';
$$;


--
-- Name: FUNCTION i18n_completo(p_texto jsonb); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.i18n_completo(p_texto jsonb) IS 'El texto esta en los tres idiomas. Es lo que se le exige a lo que escribe el producto.';


--
-- Name: i18n_minimo(jsonb); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.i18n_minimo(p_texto jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT p_texto IS NOT NULL
     AND jsonb_typeof(p_texto) = 'object'
     AND btrim(coalesce(p_texto ->> 'es-AR', '')) <> '';
$$;


--
-- Name: FUNCTION i18n_minimo(p_texto jsonb); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.i18n_minimo(p_texto jsonb) IS 'El texto esta en un idioma. Es lo que se le exige a lo que carga una Prestadora: queda como ella lo escribio.';


--
-- Name: la_alarma_la_resuelve_quien_la_tomo(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.la_alarma_la_resuelve_quien_la_tomo() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  v_tipo text;
  v_resuelve boolean;
  v_actor uuid := auth.uid();
  v_quien uuid;
  v_asistente uuid;
BEGIN
  IF TG_TABLE_NAME = 'alertas_tempranas_guardia' THEN
    v_tipo := 'alerta_temprana_guardia';
    v_resuelve := OLD.resuelto_at IS NULL AND NEW.resuelto_at IS NOT NULL;
  ELSIF TG_TABLE_NAME = 'incidentes_relevo' THEN
    v_tipo := 'incidente_relevo';
    v_resuelve := OLD.resuelto_at IS NULL AND NEW.resuelto_at IS NOT NULL;
  ELSIF TG_TABLE_NAME = 'incidentes_turno_sin_cubrir' THEN
    v_tipo := 'incidente_turno_sin_cubrir';
    v_resuelve := OLD.resuelto_at IS NULL AND NEW.resuelto_at IS NOT NULL;
  ELSIF TG_TABLE_NAME = 'emergencias_guardia' THEN
    v_tipo := 'emergencia_guardia';
    v_resuelve := OLD.atendida_at IS NULL AND NEW.atendida_at IS NOT NULL;
    v_actor := coalesce(v_actor, NEW.atendida_por);
  ELSIF TG_TABLE_NAME = 'guardias' THEN
    v_tipo := 'guardia_sin_cerrar';
    v_resuelve := OLD.estado = 'activa' AND NEW.estado IS DISTINCT FROM 'activa';
  END IF;

  IF NOT coalesce(v_resuelve, false) OR v_actor IS NULL OR NOT interno.es_usuario_del_panel(v_actor) THEN
    RETURN NEW;
  END IF;

  v_quien := interno.quien_tiene_la_alarma(NEW.prestadora_id, v_tipo, NEW.id);
  IF v_quien IS NOT NULL AND v_quien <> v_actor THEN
    RAISE EXCEPTION 'alarma_tomada_por_otra_persona' USING ERRCODE = '42501';
  END IF;

  -- La emergencia se atiende todavía con la llave maestra, así que la zona no la mira ninguna
  -- política: se mira acá. Fuera de su zona, el Coordinador la atiende sólo si la tomó.
  IF TG_TABLE_NAME = 'emergencias_guardia' AND v_quien IS NULL AND interno.es_coordinador_de(v_actor) THEN
    SELECT g.asistente_id INTO v_asistente FROM guardias g WHERE g.id = NEW.guardia_id;
    IF NOT interno.coordinador_alcanza_asistente_de(v_actor, v_asistente) THEN
      RAISE EXCEPTION 'alarma_fuera_de_la_zona' USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: la_direccion_de_la_prestadora_es_suya(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.la_direccion_de_la_prestadora_es_suya() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $_$
DECLARE nueva text;
BEGIN
  nueva := NULLIF(lower(btrim(COALESCE(NEW.dominio, ''))), '');

  IF TG_OP = 'UPDATE'
     AND OLD.dominio IS NOT NULL
     AND nueva IS DISTINCT FROM lower(btrim(OLD.dominio)) THEN
    RAISE EXCEPTION 'la_direccion_de_la_prestadora_no_cambia';
  END IF;

  NEW.dominio := nueva;

  IF nueva IS NULL THEN
    RETURN NEW;
  END IF;

  -- La forma de una dirección web: letras sin acento, números, guiones y puntos, y ni un guión ni
  -- un punto en los extremos.
  IF nueva !~ '^[a-z0-9]([a-z0-9.-]*[a-z0-9])?$' THEN
    RAISE EXCEPTION 'la_direccion_de_la_prestadora_no_tiene_forma';
  END IF;

  -- Lo reservado es un rótulo bajo el dominio del producto. Una Prestadora con dominio propio
  -- guarda la dirección entera, con puntos, y ahí no hay nada que reservar.
  IF position('.' in nueva) = 0
     AND EXISTS (SELECT 1 FROM public.direcciones_reservadas r WHERE r.direccion = nueva) THEN
    RAISE EXCEPTION 'la_direccion_de_la_prestadora_esta_reservada';
  END IF;

  RETURN NEW;
END;
$_$;


--
-- Name: FUNCTION la_direccion_de_la_prestadora_es_suya(); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.la_direccion_de_la_prestadora_es_suya() IS 'La direccion por la que entra una Prestadora: con forma de direccion web, nunca un nombre reservado del producto, y una vez puesta no cambia.';


--
-- Name: la_lista_propia_no_pisa_a_la_del_producto(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.la_lista_propia_no_pisa_a_la_del_producto() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
BEGIN
  IF NEW.prestadora_id IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM public.listas_de_opciones l
        WHERE l.prestadora_id IS NULL
          AND l.clave = NEW.clave
     ) THEN
    RAISE EXCEPTION 'La lista «%» ya viene con el producto.', NEW.clave
      USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION la_lista_propia_no_pisa_a_la_del_producto(); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.la_lista_propia_no_pisa_a_la_del_producto() IS 'Una lista propia no puede llamarse igual que una que trae el producto.';


--
-- Name: la_nota_aclaratoria_es_de_una_version(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.la_nota_aclaratoria_es_de_una_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
BEGIN
  IF (to_jsonb(NEW) ->> 'nota_aclaratoria') IS NOT DISTINCT FROM (to_jsonb(OLD) ->> 'nota_aclaratoria') THEN
    NEW := jsonb_populate_record(NEW, jsonb_build_object('nota_aclaratoria', NULL));
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: la_opcion_no_cruza_prestadoras(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.la_opcion_no_cruza_prestadoras() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  la_lista public.listas_de_opciones%ROWTYPE;
BEGIN
  SELECT * INTO la_lista FROM public.listas_de_opciones WHERE id = NEW.lista_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'La lista de opciones no existe o no es de esta Prestadora.'
      USING ERRCODE = 'P0001';
  END IF;

  -- 1. Una opción del producto cuelga de una lista del producto. Colgarla de la lista de una
  --    Prestadora la volvería visible para las demás sin que nadie lo hubiera decidido.
  IF NEW.prestadora_id IS NULL AND la_lista.prestadora_id IS NOT NULL THEN
    RAISE EXCEPTION 'Una opción del producto no puede colgar de la lista de una Prestadora.'
      USING ERRCODE = 'P0001';
  END IF;

  -- 2. Una opción de una Prestadora cuelga de una lista del producto o de la suya, nunca de la
  --    de otra.
  IF NEW.prestadora_id IS NOT NULL
     AND la_lista.prestadora_id IS NOT NULL
     AND la_lista.prestadora_id <> NEW.prestadora_id THEN
    RAISE EXCEPTION 'Esa lista es de otra Prestadora.'
      USING ERRCODE = 'P0001';
  END IF;

  -- 3. La marca. Una lista que no admite opciones propias es la que trae el producto y nada más.
  IF NEW.prestadora_id IS NOT NULL
     AND la_lista.prestadora_id IS NULL
     AND NOT la_lista.admite_opciones_propias THEN
    RAISE EXCEPTION 'La lista «%» no admite opciones propias de una Prestadora.', la_lista.clave
      USING ERRCODE = 'P0001';
  END IF;

  -- 4. Una Prestadora no puede repetir una clave que el producto ya trae: quedarían dos opciones
  --    distintas guardándose con el mismo valor, y lo elegido dejaría de querer decir una cosa
  --    sola.
  IF NEW.prestadora_id IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM public.opciones_de_lista o
        WHERE o.lista_id = NEW.lista_id
          AND o.prestadora_id IS NULL
          AND o.clave = NEW.clave
     ) THEN
    RAISE EXCEPTION 'La opción «%» ya viene con el producto en esa lista.', NEW.clave
      USING ERRCODE = 'P0001';
  END IF;

  -- Y el número de orden de una opción propia lo pone la base, no la pantalla: se cuenta desde el
  -- número que dice `interno.orden_desde_el_que_cuentan_las_opciones_propias()` mirando sólo las
  -- propias, así que lo nuevo cae detrás del catálogo general y detrás de lo que ella ya cargó.
  IF TG_OP = 'INSERT' AND NEW.prestadora_id IS NOT NULL AND NEW.orden = 0 THEN
    SELECT coalesce(max(o.orden), interno.orden_desde_el_que_cuentan_las_opciones_propias()) + 1
      INTO NEW.orden
      FROM public.opciones_de_lista o
     WHERE o.lista_id = NEW.lista_id
       AND o.prestadora_id = NEW.prestadora_id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION la_opcion_no_cruza_prestadoras(); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.la_opcion_no_cruza_prestadoras() IS 'Las cuatro cosas de una opcion que dependen de la fila de su lista, mas el numero de orden de una opcion propia.';


--
-- Name: la_resolucion_dice_quien_la_firmo(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.la_resolucion_dice_quien_la_firmo() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  v_pide_detalle boolean;
BEGIN
  -- Quién firma no viene en el pedido: sale de la sesión, y pisa lo que haya llegado.
  IF auth.uid() IS NOT NULL THEN
    NEW.resuelto_por := auth.uid();
  END IF;

  NEW.detalle := nullif(btrim(coalesce(NEW.detalle, '')), '');

  -- Y el detalle lo exige la base, no la pantalla. Acá y no adentro de `resolver`, para que valga
  -- también si alguien escribe la fila por su cuenta.
  SELECT m.pide_detalle INTO v_pide_detalle
    FROM motivos_resolucion m
   WHERE m.id = NEW.motivo_id;

  IF coalesce(v_pide_detalle, false) AND NEW.detalle IS NULL THEN
    RAISE EXCEPTION 'resolucion_sin_detalle';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: la_toma_la_suelta_quien_la_tomo(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.la_toma_la_suelta_quien_la_tomo() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
BEGIN
  IF auth.uid() IS NOT NULL AND auth.uid() IS DISTINCT FROM OLD.tomada_por THEN
    RAISE EXCEPTION 'alarma_tomada_por_otra_persona' USING ERRCODE = '42501';
  END IF;
  IF OLD.soltada_at IS NOT NULL THEN
    RAISE EXCEPTION 'toma_ya_soltada' USING ERRCODE = '23514';
  END IF;

  NEW.id := OLD.id;
  NEW.prestadora_id := OLD.prestadora_id;
  NEW.tipo := OLD.tipo;
  NEW.referencia_id := OLD.referencia_id;
  NEW.tomada_por := OLD.tomada_por;
  NEW.tomada_at := OLD.tomada_at;
  NEW.vence_at := OLD.vence_at;
  IF NEW.soltada_at IS NOT NULL THEN
    NEW.soltada_at := now();
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: las_modalidades_de_la_liquidacion(uuid, uuid, date, date); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.las_modalidades_de_la_liquidacion(p_prestadora uuid, p_asistente uuid, p_desde date, p_hasta date) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT coalesce(array_agg(DISTINCT g.canal_modalidad), ARRAY[]::text[])
    FROM public.guardias g
   WHERE g.prestadora_id = p_prestadora
     AND g.asistente_id = p_asistente
     AND g.fecha >= p_desde
     AND g.fecha <= p_hasta
     AND g.estado = 'completada';
$$;


--
-- Name: FUNCTION las_modalidades_de_la_liquidacion(p_prestadora uuid, p_asistente uuid, p_desde date, p_hasta date); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.las_modalidades_de_la_liquidacion(p_prestadora uuid, p_asistente uuid, p_desde date, p_hasta date) IS 'Las modalidades de trabajo de las guardias completadas que paga una liquidacion. Vacio quiere decir que no paga ninguna guardia.';


--
-- Name: le_corresponde(uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.le_corresponde(p_prestadora_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT COALESCE(
    auth.role() = 'service_role'
      OR (p_prestadora_id IS NOT NULL AND p_prestadora_id = interno.current_tenant()),
    false)
$$;


--
-- Name: lee_la_configuracion(uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.lee_la_configuracion(p_prestadora uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT p_prestadora IS NOT NULL
     AND interno.current_tenant() IS NOT NULL
     AND p_prestadora = interno.current_tenant();
$$;


--
-- Name: FUNCTION lee_la_configuracion(p_prestadora uuid); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.lee_la_configuracion(p_prestadora uuid) IS 'Lectura de catálogo y configuración: la fila es de la Prestadora en la que está parada la sesión. Niega si falta cualquiera de las dos.';


--
-- Name: los_datos_bancarios_son_del_mismo_asistente(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.los_datos_bancarios_son_del_mismo_asistente() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.asistentes a
     WHERE a.id = NEW.asistente_id
       AND a.prestadora_id = NEW.prestadora_id
  ) THEN
    RAISE EXCEPTION 'datos_bancarios_de_otra_prestadora'
      USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION los_datos_bancarios_son_del_mismo_asistente(); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.los_datos_bancarios_son_del_mismo_asistente() IS 'La Prestadora de la cuenta tiene que ser la del Asistente. El mensaje no nombra ningun dato de la cuenta.';


--
-- Name: marca_de_lo_tapado(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.marca_de_lo_tapado() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'interno', 'public'
    AS $$
  SELECT '•••'::text;
$$;


--
-- Name: FUNCTION marca_de_lo_tapado(); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.marca_de_lo_tapado() IS 'Lo que queda escrito en el lugar de lo que se tapo. Punto unico de verdad: no se escribe en ninguna otra parte.';


--
-- Name: minutos_que_dura_la_toma(uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.minutos_que_dura_la_toma(p_prestadora uuid) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $_$
DECLARE
  v_texto text;
  v_minutos integer;
BEGIN
  SELECT c.regla ->> 'minutos_que_dura_hacerse_cargo' INTO v_texto
    FROM configuracion_alarmas_tomadas c WHERE c.prestadora_id = p_prestadora;
  IF v_texto IS NULL OR v_texto !~ '^\d{1,4}$' THEN
    RETURN 60;
  END IF;
  v_minutos := v_texto::integer;
  IF v_minutos < 5 OR v_minutos > 1440 THEN
    RETURN 60;
  END IF;
  RETURN v_minutos;
END;
$_$;


--
-- Name: modalidades_habilitadas_de_prestadora(uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.modalidades_habilitadas_de_prestadora(p_prestadora_id uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    NULLIF(
      ARRAY(
        SELECT pm.modalidad
          FROM public.prestadora_modalidades pm
         WHERE pm.prestadora_id = p_prestadora_id
           AND pm.activa
           AND pm.modalidad IN ('directa', 'match')
         ORDER BY pm.modalidad
      ),
      ARRAY[]::text[]
    ),
    ARRAY['directa']::text[]
  );
$$;


--
-- Name: FUNCTION modalidades_habilitadas_de_prestadora(p_prestadora_id uuid); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.modalidades_habilitadas_de_prestadora(p_prestadora_id uuid) IS 'Las modalidades de trabajo que una Prestadora puede darle a un Asistente, sacadas de las que tiene activas. Punto único de verdad (regla 12).';


--
-- Name: moneda_de_prestadora(uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.moneda_de_prestadora(p_prestadora_id uuid) RETURNS public.moneda_iso
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.moneda FROM public.prestadoras p WHERE p.id = p_prestadora_id;
$$;


--
-- Name: FUNCTION moneda_de_prestadora(p_prestadora_id uuid); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.moneda_de_prestadora(p_prestadora_id uuid) IS 'La moneda con la que trabaja una Prestadora. La llaman los disparadores que completan la moneda de cada importe. Vive en `interno` porque recibe el identificador de una Prestadora: publicada sería una dirección web que contesta sobre cualquiera.';


--
-- Name: motivo_bloqueo_matricula(uuid, date); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.motivo_bloqueo_matricula(p_asistente_id uuid, p_dia date DEFAULT CURRENT_DATE) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_prestadora_id  uuid;
  v_requiere       boolean;
  v_tipo_matricula text;
  v_modo           text;
  v_tiene_alguna   boolean;
  v_vigente        public.matriculas_asistente%ROWTYPE;
BEGIN
  IF p_asistente_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT a.prestadora_id, t.requiere_matricula, t.tipo_matricula
    INTO v_prestadora_id, v_requiere, v_tipo_matricula
    FROM public.asistentes a
    LEFT JOIN public.tipos_asistente t ON t.id = a.tipo_asistente_id
   WHERE a.id = p_asistente_id;

  -- No existe, no tiene tipo cargado, o su tipo no exige matrícula: la regla no
  -- lo alcanza. Ver el encabezado sobre por qué la falta de tipo no bloquea.
  IF v_requiere IS NOT TRUE THEN
    RETURN NULL;
  END IF;

  SELECT p.modo_control_matricula INTO v_modo
    FROM public.prestadoras p
   WHERE p.id = v_prestadora_id;
  v_modo := COALESCE(v_modo, 'estricto');

  -- ¿Tiene alguna matrícula del tipo que su tipo de Asistente exige? Se
  -- pregunta por separado de "¿tiene una vigente?" porque los dos casos se
  -- resuelven distinto: uno hay que pedirlo, el otro hay que renovarlo.
  SELECT EXISTS (
    SELECT 1 FROM public.matriculas_asistente m
     WHERE m.asistente_id = p_asistente_id
       AND m.tipo = v_tipo_matricula
  ) INTO v_tiene_alguna;

  IF NOT v_tiene_alguna THEN
    RETURN 'sin_matricula';
  END IF;

  -- La que está vigente ese día. Si hubiera varias —pasa cuando se carga la
  -- renovación antes de que caiga la anterior— manda la que vence más tarde, y
  -- la que no vence nunca gana siempre.
  SELECT m.* INTO v_vigente
    FROM public.matriculas_asistente m
   WHERE m.asistente_id = p_asistente_id
     AND m.tipo = v_tipo_matricula
     AND (m.vigente_desde IS NULL OR m.vigente_desde <= p_dia)
     AND (m.vigente_hasta IS NULL OR m.vigente_hasta >= p_dia)
   ORDER BY (m.vigente_hasta IS NULL) DESC, m.vigente_hasta DESC
   LIMIT 1;

  IF NOT FOUND THEN
    RETURN 'vencida';
  END IF;

  -- ACÁ ESTÁ EL CAMBIO. Antes decía solamente `v_modo = 'estricto'`. Ahora la
  -- verificación también se exige cuando la matrícula la subió el propio
  -- Asistente, porque en modo flexible cargarla sería habilitarse solo.
  IF (v_modo = 'estricto' OR v_vigente.cargada_por_el_asistente)
     AND v_vigente.verificada_at IS NULL THEN
    RETURN 'sin_verificar';
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: FUNCTION motivo_bloqueo_matricula(p_asistente_id uuid, p_dia date); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.motivo_bloqueo_matricula(p_asistente_id uuid, p_dia date) IS 'Punto único de verdad de la regla dura de matrícula. NULL = ese día puede trabajar. Si no: sin_matricula, vencida o sin_verificar. Devuelve la palabra, nunca el texto: la traducción vive en el Panel.';


--
-- Name: nombre_de_usuario(uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.nombre_de_usuario(p_usuario_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT u.nombre
    FROM public.usuarios u
   WHERE u.id = p_usuario_id;
$$;


--
-- Name: FUNCTION nombre_de_usuario(p_usuario_id uuid); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.nombre_de_usuario(p_usuario_id uuid) IS 'El nombre visible de una persona, a partir de su identificador. Se saltea la protección por fila de usuarios, así que vive acá y no en un esquema publicado: sólo se llega a ella desde una vista, nunca desde afuera.';


--
-- Name: numero_comparable(text); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.numero_comparable(p_telefono text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT CASE
           WHEN regexp_replace(coalesce(p_telefono, ''), '[^0-9]', '', 'g') = '' THEN NULL
           ELSE md5(regexp_replace(p_telefono, '[^0-9]', '', 'g'))
         END;
$$;


--
-- Name: FUNCTION numero_comparable(p_telefono text); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.numero_comparable(p_telefono text) IS 'La huella de un telefono, para comparar dos numeros sin guardar ni mostrar ninguno.';


--
-- Name: orden_desde_el_que_cuentan_las_opciones_propias(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.orden_desde_el_que_cuentan_las_opciones_propias() RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT 100;
$$;


--
-- Name: FUNCTION orden_desde_el_que_cuentan_las_opciones_propias(); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.orden_desde_el_que_cuentan_las_opciones_propias() IS 'Las opciones que agrega una Prestadora se numeran desde acá hacia arriba, para que queden detrás del catálogo general en vez de intercalarse.';


--
-- Name: pacientes_de_la_guardia(uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.pacientes_de_la_guardia(p_guardia_id uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT paciente_id FROM guardia_pacientes WHERE guardia_id = p_guardia_id
