--
-- Name: pacientes_del_asistente(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.pacientes_del_asistente() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT gp.paciente_id
    FROM guardia_pacientes gp
    JOIN guardias g ON g.id = gp.guardia_id
   WHERE g.asistente_id = interno.asistente_de_la_sesion()
     AND g.prestadora_id = interno.current_tenant()
$$;


--
-- Name: pacientes_del_cliente(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.pacientes_del_cliente() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT p.id
  FROM pacientes p
  WHERE p.prestadora_id = interno.current_tenant()
    AND p.cliente_id = interno.cliente_id_de_usuario(auth.uid())
$$;


--
-- Name: patron_de_mensaje_en_postgres(text); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.patron_de_mensaje_en_postgres(p_patron text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'interno', 'public'
    AS $$
  SELECT replace(p_patron, '\b', '\y');
$$;


--
-- Name: FUNCTION patron_de_mensaje_en_postgres(p_patron text); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.patron_de_mensaje_en_postgres(p_patron text) IS 'Traduce una expresion escrita con la sintaxis corriente a la de Postgres. Hoy la unica diferencia que importa es el borde de palabra.';


--
-- Name: persona_autorizada_puede(uuid, text); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.persona_autorizada_puede(p_usuario uuid, p_clave text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT CASE
    WHEN p_usuario IS NULL THEN false
    WHEN EXISTS (
      SELECT 1 FROM clientes f
       WHERE f.usuario_id = p_usuario
         AND f.prestadora_id = interno.current_tenant()
    ) THEN true
    ELSE COALESCE(
      (SELECT p.permitido
         FROM permisos_personas_autorizadas p
        WHERE p.usuario_id = p_usuario
          AND p.clave = p_clave),
      false
    )
  END
$$;


--
-- Name: prestadora_de_la_restriccion(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.prestadora_de_la_restriccion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid;
BEGIN
  SELECT prestadora_id INTO v_prestadora FROM public.clientes WHERE id = NEW.cliente_id;
  IF v_prestadora IS NULL THEN
    RAISE EXCEPTION 'El Cliente del aviso no existe';
  END IF;
  NEW.prestadora_id := v_prestadora;
  RETURN NEW;
END;
$$;


--
-- Name: prestadora_del_estado_de_cuenta(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.prestadora_del_estado_de_cuenta() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid;
BEGIN
  SELECT prestadora_id INTO v_prestadora FROM public.clientes WHERE id = NEW.cliente_id;
  IF v_prestadora IS NULL THEN
    RAISE EXCEPTION 'El Cliente del aviso no existe';
  END IF;
  NEW.prestadora_id := v_prestadora;
  RETURN NEW;
END;
$$;


--
-- Name: puede_configurar_accesos_de_personas_autorizadas(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.puede_configurar_accesos_de_personas_autorizadas() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT interno.es_superadmin()
      OR (
        EXISTS (
          SELECT 1 FROM usuarios u
           WHERE u.id = auth.uid()
             AND u.rol IN ('admin_prestadora', 'coordinador')
        )
        AND interno.tiene_permiso('configurar_accesos_de_personas_autorizadas')
      )
$$;


--
-- Name: puede_habilitar(text, text); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.puede_habilitar(p_rol_de_quien text, p_rol_del_destinatario text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'interno', 'public'
    AS $$
  SELECT COALESCE(
    interno.escalon_del_rol(p_rol_de_quien) > interno.escalon_del_rol(p_rol_del_destinatario),
    false
  )
$$;


--
-- Name: FUNCTION puede_habilitar(p_rol_de_quien text, p_rol_del_destinatario text); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.puede_habilitar(p_rol_de_quien text, p_rol_del_destinatario text) IS 'Se habilita hacia abajo, y nunca a uno mismo ni a su propio escalón. Un rol que no se entiende —de cualquiera de los dos lados— no habilita y no es habilitado. Es la gemela de puedeHabilitar() del motor.';


--
-- Name: quien_tiene_la_alarma(uuid, text, uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.quien_tiene_la_alarma(p_prestadora uuid, p_tipo text, p_referencia uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT a.tomada_por
    FROM alarmas_tomadas a
   WHERE a.prestadora_id = p_prestadora
     AND a.tipo = p_tipo
     AND a.referencia_id = p_referencia
     AND a.soltada_at IS NULL
     AND a.vence_at > now()
   ORDER BY a.tomada_at DESC
   LIMIT 1;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: consultas_a_hce; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.consultas_a_hce (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    usuario_id uuid,
    paciente_id uuid NOT NULL,
    categorias text[] NOT NULL,
    momento timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    origen text NOT NULL,
    credencial_rol text NOT NULL,
    numero bigint NOT NULL,
    resumen_anterior bytea,
    resumen bytea NOT NULL,
    CONSTRAINT consultas_a_hce_alguna_categoria CHECK (((cardinality(categorias) > 0) AND (array_position(categorias, NULL::text) IS NULL))),
    CONSTRAINT consultas_a_hce_dice_quien CHECK (((usuario_id IS NOT NULL) OR (credencial_rol = 'trabajo_sin_persona'::text))),
    CONSTRAINT consultas_a_hce_el_origen_no_va_vacio CHECK (((btrim(origen) <> ''::text) AND (length(origen) <= 300))),
    CONSTRAINT consultas_a_hce_la_cadena_empieza_en_uno CHECK (((numero >= 1) AND ((numero = 1) = (resumen_anterior IS NULL))))
);


--
-- Name: TABLE consultas_a_hce; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.consultas_a_hce IS 'Quién leyó qué dato de salud de qué paciente, cuándo y por dónde. Una cadena por Prestadora: cada renglón guarda el resumen SHA-256 del anterior y el suyo. Lo escribe la base, no se edita y no se borra.';


--
-- Name: COLUMN consultas_a_hce.categorias; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.consultas_a_hce.categorias IS 'Las tablas de donde salió lo leído. La base comprueba que existan.';


--
-- Name: COLUMN consultas_a_hce.origen; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.consultas_a_hce.origen IS 'Por dónde llegó la lectura: método y ruta del pedido, sin lo que viaja después del signo de pregunta.';


--
-- Name: resumen_de_la_consulta(public.consultas_a_hce); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.resumen_de_la_consulta(e public.consultas_a_hce) RETURNS bytea
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT sha256(convert_to(jsonb_build_array(
    e.id,
    e.prestadora_id,
    e.numero,
    e.usuario_id,
    e.paciente_id,
    to_jsonb(e.categorias),
    to_char(e.momento AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    e.origen,
    e.credencial_rol,
    encode(e.resumen_anterior, 'hex')
  )::text, 'UTF8'));
$$;


--
-- Name: rige_la_restriccion_de_hce(uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.rige_la_restriccion_de_hce(p_prestadora uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT p_prestadora IS NULL
      OR interno.el_pais_exige_la_restriccion_de_hce(p_prestadora)
      OR COALESCE(
           (SELECT c.restriccion_de_hce FROM configuracion_de_hce c
             WHERE c.prestadora_id = p_prestadora),
           true)
$$;


--
-- Name: se_habilita_hacia_abajo_y_nunca_a_uno_mismo(); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.se_habilita_hacia_abajo_y_nunca_a_uno_mismo() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  v_destinatario record;
  v_quien record;
  v_quien_id uuid;
BEGIN
  v_quien_id := CASE TG_TABLE_NAME
    WHEN 'cambios_de_clave_habilitados' THEN NEW.habilitado_por
    ELSE NEW.confirmado_por
  END;

  SELECT rol, prestadora_id INTO v_destinatario FROM public.usuarios WHERE id = NEW.usuario_id;
  SELECT rol, prestadora_id INTO v_quien FROM public.usuarios WHERE id = v_quien_id;

  -- Falla cerrado ante cualquier cosa que no se pudo resolver.
  IF v_destinatario IS NULL OR v_quien IS NULL THEN
    RAISE EXCEPTION 'No se pudo resolver quién habilita a quién';
  END IF;

  -- Las dos cuentas son de la Prestadora de la fila, y de ninguna otra. El rol técnico de la
  -- empresa no tiene Prestadora propia, y por eso queda exceptuado del lado de quien habilita.
  IF v_destinatario.prestadora_id IS DISTINCT FROM NEW.prestadora_id THEN
    RAISE EXCEPTION 'La cuenta no es de esa Prestadora';
  END IF;
  IF v_quien.rol <> 'superadmin' AND v_quien.prestadora_id IS DISTINCT FROM NEW.prestadora_id THEN
    RAISE EXCEPTION 'Quien habilita no es de esa Prestadora';
  END IF;

  IF NOT interno.puede_habilitar(v_quien.rol, v_destinatario.rol) THEN
    RAISE EXCEPTION 'Nadie habilita a su propio escalón ni a uno de más arriba';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: tapar_lo_que_no_viaja_en_un_mensaje(text, uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.tapar_lo_que_no_viaja_en_un_mensaje(p_texto text, p_prestadora uuid DEFAULT NULL::uuid) RETURNS TABLE(texto text, regla text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'interno', 'public'
    AS $$
DECLARE
  v_texto  text := coalesce(p_texto, '');
  v_antes  text;
  v_regla  text;
  la_regla record;
  v_hay    boolean;
BEGIN
  SELECT EXISTS (SELECT 1 FROM public.reglas_de_los_mensajes WHERE activo) INTO v_hay;
  IF NOT v_hay THEN
    RAISE EXCEPTION 'reglas_de_los_mensajes_sin_cargar' USING ERRCODE = 'P0001';
  END IF;

  FOR la_regla IN
    SELECT r.clave, r.patron, r.banderas
      FROM public.reglas_de_los_mensajes r
     WHERE r.activo
       AND (r.prestadora_id IS NULL OR r.prestadora_id = p_prestadora)
     ORDER BY r.orden, r.clave
  LOOP
    v_antes := v_texto;
    v_texto := regexp_replace(
      v_texto,
      interno.patron_de_mensaje_en_postgres(la_regla.patron),
      interno.marca_de_lo_tapado(),
      la_regla.banderas
    );
    -- Queda anotada la primera que tapó algo. Alcanza para decirle a quien escribió por qué hay
    -- marcas; la lista entera de las que tocaron el texto no le agrega nada y le cuenta al que
    -- quiere esquivarlo cuántas puertas encontró.
    IF v_regla IS NULL AND v_texto IS DISTINCT FROM v_antes THEN
      v_regla := la_regla.clave;
    END IF;
  END LOOP;

  RETURN QUERY SELECT v_texto, v_regla;
END;
$$;


--
-- Name: FUNCTION tapar_lo_que_no_viaja_en_un_mensaje(p_texto text, p_prestadora uuid); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.tapar_lo_que_no_viaja_en_un_mensaje(p_texto text, p_prestadora uuid) IS 'Tapa en un texto lo que las reglas de los mensajes alcanzan, y devuelve el texto tapado y la clave de la primera regla que tapo algo. Nunca devuelve ni registra lo que tapo. Con el cuerpo de reglas vacio falla cerrado.';


--
-- Name: texto_en_los_tres_idiomas(jsonb); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.texto_en_los_tres_idiomas(texto jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT texto IS NOT NULL
     AND jsonb_typeof(texto) = 'object'
     AND coalesce(length(btrim(texto ->> 'es-AR')), 0) > 0
     AND coalesce(length(btrim(texto ->> 'en')), 0) > 0
     AND coalesce(length(btrim(texto ->> 'pt-BR')), 0) > 0;
$$;


--
-- Name: FUNCTION texto_en_los_tres_idiomas(texto jsonb); Type: COMMENT; Schema: interno; Owner: -
--

COMMENT ON FUNCTION interno.texto_en_los_tres_idiomas(texto jsonb) IS 'Verdadero si el texto trae los tres idiomas con contenido. Única definición: las restricciones de los formularios declarados la llaman en lugar de repetir la condición.';


--
