--
-- Name: verificar_cadena_de_consultas(uuid); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.verificar_cadena_de_consultas(p_prestadora uuid) RETURNS TABLE(intacta boolean, renglones bigint, rota_en_numero bigint, rota_en_id uuid, motivo text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  r           consultas_a_hce;
  v_esperado  bigint := 1;
  v_anterior  bytea := NULL;
BEGIN
  FOR r IN
    SELECT * FROM consultas_a_hce a
     WHERE a.prestadora_id = p_prestadora
     ORDER BY a.numero
  LOOP
    IF r.numero <> v_esperado THEN
      RETURN QUERY SELECT false, v_esperado - 1, r.numero, r.id, 'falta_un_renglon'::text;
      RETURN;
    END IF;
    IF r.resumen_anterior IS DISTINCT FROM v_anterior THEN
      RETURN QUERY SELECT false, v_esperado - 1, r.numero, r.id, 'no_sigue_al_anterior'::text;
      RETURN;
    END IF;
    IF r.resumen IS DISTINCT FROM interno.resumen_de_la_consulta(r) THEN
      RETURN QUERY SELECT false, v_esperado - 1, r.numero, r.id, 'el_renglon_fue_alterado'::text;
      RETURN;
    END IF;
    v_anterior := r.resumen;
    v_esperado := v_esperado + 1;
  END LOOP;

  RETURN QUERY SELECT true, v_esperado - 1, NULL::bigint, NULL::uuid, NULL::text;
END;
$$;


--
-- Name: versionar_tabla_clinica(regclass); Type: FUNCTION; Schema: interno; Owner: -
--

CREATE FUNCTION interno.versionar_tabla_clinica(p_tabla regclass) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $_$
DECLARE
  v_nombre text;
BEGIN
  SELECT c.relname INTO v_nombre
    FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
   WHERE c.oid = p_tabla AND n.nspname = 'public';
  IF v_nombre IS NULL THEN
    RAISE EXCEPTION 'Sólo se versionan tablas del esquema public: %', p_tabla;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                  WHERE table_schema = 'public' AND table_name = v_nombre
                    AND column_name = 'id' AND data_type = 'uuid')
     OR NOT EXISTS (SELECT 1 FROM information_schema.columns
                  WHERE table_schema = 'public' AND table_name = v_nombre
                    AND column_name = 'prestadora_id' AND data_type = 'uuid') THEN
    RAISE EXCEPTION 'La tabla % necesita id uuid y prestadora_id uuid para versionarse', v_nombre;
  END IF;

  EXECUTE format('ALTER TABLE %s ADD COLUMN IF NOT EXISTS nota_aclaratoria text', p_tabla);

  -- Lo que ya estaba escrito entra como primera versión. Lo que se pisó antes de hoy no se
  -- recupera: el momento es el de la última escritura conocida y el autor queda sin saberse.
  EXECUTE format($f$
    INSERT INTO versiones_registro_clinico
      (prestadora_id, paciente_id, tabla, registro_id, version, operacion, datos,
       nota_aclaratoria, autor_id, credencial_rol, momento)
    SELECT (to_jsonb(t) ->> 'prestadora_id')::uuid, (to_jsonb(t) ->> 'paciente_id')::uuid,
           %L, t.id, 1, 'anterior_al_historial', to_jsonb(t), NULL, NULL, session_user::text,
           COALESCE((to_jsonb(t) ->> 'updated_at')::timestamptz,
                    (to_jsonb(t) ->> 'created_at')::timestamptz, now())
      FROM %s t
     WHERE NOT EXISTS (SELECT 1 FROM versiones_registro_clinico v
                        WHERE v.tabla = %L AND v.registro_id = t.id)
  $f$, v_nombre, p_tabla, v_nombre);

  EXECUTE format('DROP TRIGGER IF EXISTS trg_la_nota_es_de_una_version ON %s', p_tabla);
  EXECUTE format('CREATE TRIGGER trg_la_nota_es_de_una_version BEFORE UPDATE ON %s
                  FOR EACH ROW EXECUTE FUNCTION interno.la_nota_aclaratoria_es_de_una_version()', p_tabla);

  EXECUTE format('DROP TRIGGER IF EXISTS trg_versiones_del_registro_clinico ON %s', p_tabla);
  EXECUTE format('CREATE TRIGGER trg_versiones_del_registro_clinico AFTER INSERT OR UPDATE OR DELETE ON %s
                  FOR EACH ROW EXECUTE FUNCTION interno.anotar_version_clinica()', p_tabla);
END;
$_$;


--
-- Name: asistente_asignado_a_cliente(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asistente_asignado_a_cliente(p_asistente_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM guardias g
    JOIN pacientes p ON p.id = g.paciente_id
    WHERE g.asistente_id = p_asistente_id
      AND p.cliente_id = cliente_id_de_usuario(auth.uid())
  );
$$;


--
-- Name: FUNCTION asistente_asignado_a_cliente(p_asistente_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.asistente_asignado_a_cliente(p_asistente_id uuid) IS 'Única fuente de verdad para saber si un Asistente atiende a un Paciente del Cliente de la sesión. Va por función y no dentro de la política para no armar una referencia circular entre asistentes y guardias.';


--
-- Name: ausencias_que_tapan(date, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ausencias_que_tapan(p_desde date, p_hasta date, p_hoy date DEFAULT CURRENT_DATE) RETURNS TABLE(asistente_id uuid, fecha_inicio date, fecha_fin date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
  WITH efectivas AS (
    SELECT a.asistente_id, a.fecha_inicio,
           CASE WHEN a.fecha_vuelta_real IS NULL AND a.fecha_fin < p_hoy THEN NULL
                ELSE a.fecha_fin END AS fecha_fin
    FROM public.ausencias a
    JOIN public.asistentes s ON s.id = a.asistente_id
    WHERE
      -- El aislamiento, primero y adentro: la licencia y la persona, las dos de esta Prestadora.
      a.prestadora_id = current_tenant()
      AND s.prestadora_id = current_tenant()
      -- Quién tiene derecho a preguntar: los tres roles de Panel y nadie más.
      AND (
        es_superadmin()
        OR es_admin_prestadora()
        OR EXISTS (SELECT 1 FROM public.usuarios u WHERE u.id = auth.uid() AND u.rol = 'coordinador')
      )
  )
  SELECT e.asistente_id, e.fecha_inicio, e.fecha_fin
  FROM efectivas e
  WHERE e.fecha_inicio <= p_hasta
    AND (e.fecha_fin IS NULL OR e.fecha_fin >= p_desde);
$$;


--
-- Name: bloquear_edicion_laboral_coordinador(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bloquear_edicion_laboral_coordinador() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  rol_actual TEXT;
BEGIN
  SELECT rol INTO rol_actual FROM usuarios WHERE id = auth.uid();

  IF rol_actual = 'coordinador' THEN
    IF NEW.tipo_vinculo IS DISTINCT FROM OLD.tipo_vinculo
      OR NEW.horas_semanales IS DISTINCT FROM OLD.horas_semanales
      OR NEW.fecha_baja IS DISTINCT FROM OLD.fecha_baja
    THEN
      RAISE EXCEPTION 'Coordinador no puede modificar datos laborales internos del Asistente (regla 8 de CLAUDE.md)';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: consentimiento_seguimiento_vigente(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consentimiento_seguimiento_vigente(p_asistente_id uuid, p_clave text DEFAULT 'seguimiento_ubicacion'::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM consentimientos_asistente c
    JOIN textos_consentimiento tx ON tx.id = c.texto_consentimiento_id
    WHERE c.asistente_id = p_asistente_id
      AND c.clave = p_clave
      AND c.retirado_at IS NULL
      AND c.decision = 'otorgado'
      AND tx.es_borrador = FALSE
      AND tx.vigente_hasta IS NULL
  );
$$;


--
-- Name: FUNCTION consentimiento_seguimiento_vigente(p_asistente_id uuid, p_clave text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.consentimiento_seguimiento_vigente(p_asistente_id uuid, p_clave text) IS 'Pendiente #102. Única fuente de verdad para saber si se puede registrar la ubicación de un Asistente. Devuelve FALSE si no consintió, si lo retiró, si el texto que firmó quedó desactualizado, o si firmó sobre un texto de relleno.';


--
-- Name: consumir_contacto_match(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consumir_contacto_match(p_acceso_id uuid, p_asistente_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_acceso public.accesos_match%ROWTYPE;
  v_ya_estaba boolean;
  v_saldo integer;
BEGIN
  -- Tomada la fila del acceso, el que llegue segundo espera acá. Sin esto, dos pedidos leen el
  -- mismo saldo y los dos descuentan sobre ese número: de dos contactos se cobra uno.
  SELECT * INTO v_acceso
    FROM public.accesos_match
   WHERE id = p_acceso_id
     FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'acceso_inexistente');
  END IF;

  -- Falla cerrado: un acceso vencido o dado de baja no abre nada, aunque le haya quedado saldo.
  IF v_acceso.estado <> 'vigente' THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'acceso_no_vigente');
  END IF;

  -- Ya abierto antes: se contesta que sí y no se cobra de nuevo. El contacto de un Asistente se
  -- paga una sola vez por Cliente, y mirarlo otra vez no es un contacto nuevo.
  SELECT EXISTS (
    SELECT 1 FROM public.contactos_vistos_match
     WHERE cliente_id = v_acceso.cliente_id AND asistente_id = p_asistente_id
  ) INTO v_ya_estaba;

  IF v_ya_estaba THEN
    RETURN jsonb_build_object(
      'ok', true, 'ya_estaba', true, 'saldo_contactos', v_acceso.saldo_contactos
    );
  END IF;

  IF v_acceso.saldo_contactos IS NOT NULL AND v_acceso.saldo_contactos <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'motivo', 'saldo_agotado', 'saldo_contactos', 0);
  END IF;

  -- Se anota primero y se descuenta después, en ese orden y no al revés: así el candado de la
  -- tabla es el que decide, y no queda ninguna forma de descontar sin haber anotado. La misma
  -- Cliente con dos paquetes abriendo el mismo Asistente a la vez llega hasta acá por dos filas
  -- de acceso distintas, que el candado de más arriba no cruza; el segundo choca contra éste.
  BEGIN
    INSERT INTO public.contactos_vistos_match
      (prestadora_id, cliente_id, asistente_id, acceso_id)
    VALUES
      (v_acceso.prestadora_id, v_acceso.cliente_id, p_asistente_id, p_acceso_id);
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object(
      'ok', true, 'ya_estaba', true, 'saldo_contactos', v_acceso.saldo_contactos
    );
  END;

  -- El que se sostiene por fecha no tiene qué descontar: queda anotado y el saldo sigue vacío.
  IF v_acceso.saldo_contactos IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'ya_estaba', false, 'saldo_contactos', NULL);
  END IF;

  UPDATE public.accesos_match
     SET saldo_contactos = saldo_contactos - 1,
         updated_at = now()
   WHERE id = p_acceso_id
  RETURNING saldo_contactos INTO v_saldo;

  RETURN jsonb_build_object('ok', true, 'ya_estaba', false, 'saldo_contactos', v_saldo);
END;
$$;


--
-- Name: FUNCTION consumir_contacto_match(p_acceso_id uuid, p_asistente_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.consumir_contacto_match(p_acceso_id uuid, p_asistente_id uuid) IS 'Anota a qué Asistente se le abrió el contacto y, si el acceso se sostiene por saldo, le descuenta uno, en la misma transacción. Un Asistente ya abierto no vuelve a descontar. El acceso que se sostiene por fecha se anota sin descontar nada. Devuelve ok y el saldo que queda, o el motivo por el que no se pudo.';


--
-- Name: correcciones_de_factura(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.correcciones_de_factura(p_factura_id uuid) RETURNS TABLE(neto numeric, correcciones_contadas integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    COALESCE(SUM(CASE WHEN c.sentido = 'resta' THEN -c.monto ELSE c.monto END), 0)::numeric(12, 2),
    COUNT(*)::integer
  FROM public.correcciones_factura_cliente c
  WHERE c.factura_id = p_factura_id;
$$;


--
-- Name: FUNCTION correcciones_de_factura(p_factura_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.correcciones_de_factura(p_factura_id uuid) IS 'Cuanto movieron en total las correcciones de una factura, y cuantas fueron. Negativo es que se facturo de mas.';


--
-- Name: dar_de_alta_la_cuenta(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dar_de_alta_la_cuenta(p_email text, p_clave text, p_rol text, p_nombre text, p_telefono text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid;
  v_correo text;
  v_ingreso text;
  v_existente uuid;
  v_usuario uuid := gen_random_uuid();
BEGIN
  IF auth.jwt() ->> 'role' IS DISTINCT FROM 'trabajo_sin_persona' THEN
    RAISE EXCEPTION 'sin_permiso';
  END IF;
  v_prestadora := interno.current_tenant();
  IF v_prestadora IS NULL THEN RAISE EXCEPTION 'sin_permiso'; END IF;
  IF p_rol IS NULL OR p_rol NOT IN ('coordinador', 'asistente', 'cliente') THEN
    RAISE EXCEPTION 'sin_permiso';
  END IF;

  v_correo := lower(btrim(coalesce(p_email, ''), E' \t\r\n'));
  IF v_correo = '' OR coalesce(p_clave, '') = '' THEN RAISE EXCEPTION 'faltan_datos'; END IF;

  v_ingreso := encode(extensions.digest(lower(v_prestadora::text) || ':' || v_correo, 'sha256'), 'hex')
               || '@acceso.careonys.invalid';

  -- Si ya hay una cuenta de ingreso con ese correo, se mira qué tiene detrás. Sin fila en
  -- `usuarios` es lo que dejó un alta anterior cortada por la mitad: no le sirve a nadie y se
  -- borra. Con fila, esa persona ya tiene cuenta en esta Prestadora: el correo lleva la
  -- Prestadora adentro, así que no puede ser de otra.
  SELECT id INTO v_existente FROM auth.users WHERE email = v_ingreso;
  IF v_existente IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM usuarios WHERE id = v_existente) THEN
      RAISE EXCEPTION 'correo_de_esta_prestadora';
    END IF;
    DELETE FROM auth.users WHERE id = v_existente;
  END IF;

  INSERT INTO auth.users (
    instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
    raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
    confirmation_token, recovery_token, email_change_token_new, email_change,
    email_change_token_current, phone_change, phone_change_token, reauthentication_token)
  VALUES (
    '00000000-0000-0000-0000-000000000000', v_usuario, 'authenticated', 'authenticated',
    v_ingreso, extensions.crypt(p_clave, extensions.gen_salt('bf', 10)), now(),
    '{"provider":"email","providers":["email"]}'::jsonb, '{}'::jsonb, now(), now(),
    '', '', '', '', '', '', '', '');

  INSERT INTO auth.identities (
    provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
  VALUES (
    v_usuario::text, v_usuario,
    jsonb_build_object('sub', v_usuario::text, 'email', v_ingreso, 'email_verified', true),
    'email', NULL, now(), now());

  -- El correo de verdad va acá y no del lado del ingreso, guardado comparable, que es como se busca.
  INSERT INTO usuarios (id, rol, nombre, telefono, email, prestadora_id)
  VALUES (v_usuario, p_rol, p_nombre, nullif(btrim(coalesce(p_telefono, '')), ''), v_correo, v_prestadora);

  RETURN v_usuario;
END;
$$;


--
-- Name: dar_de_baja_la_cuenta(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dar_de_baja_la_cuenta(p_usuario uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  v_prestadora uuid;
BEGIN
  IF auth.jwt() ->> 'role' IS DISTINCT FROM 'trabajo_sin_persona' THEN RETURN false; END IF;
  v_prestadora := interno.current_tenant();
  IF v_prestadora IS NULL OR p_usuario IS NULL THEN RETURN false; END IF;

  DELETE FROM usuarios
   WHERE id = p_usuario
     AND prestadora_id = v_prestadora
     AND rol IN ('coordinador', 'asistente', 'cliente');
  IF NOT FOUND THEN RETURN false; END IF;

  DELETE FROM auth.users WHERE id = p_usuario;
  RETURN true;
END;
$$;


--
-- Name: dia_en_que_termina_guardia(date, time without time zone, time without time zone, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dia_en_que_termina_guardia(p_fecha date, p_hora_inicio time without time zone, p_hora_fin time without time zone, p_dias_hasta_el_fin smallint DEFAULT NULL::smallint) RETURNS date
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
           -- Duración escrita: manda, y es el caso de toda guardia cargada de acá en adelante.
           WHEN p_dias_hasta_el_fin IS NOT NULL THEN p_fecha + p_dias_hasta_el_fin
           WHEN p_hora_fin IS NULL OR p_hora_inicio IS NULL THEN p_fecha
           -- Sin duración escrita se cae en la regla vieja, que sólo sabe de la guardia de noche.
           WHEN p_hora_fin <= p_hora_inicio THEN p_fecha + 1
           ELSE p_fecha
         END;
$$;


--
-- Name: domicilio_del_paciente_en(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.domicilio_del_paciente_en(p_paciente_id uuid, p_fecha date) RETURNS TABLE(paciente_id uuid, domicilio_temporal_id uuid, domicilio text, lat double precision, lng double precision, es_temporal boolean, motivo text, desde date, hasta date)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT * FROM public.domicilios_de_pacientes_en(ARRAY[p_paciente_id], p_fecha);
$$;


--
-- Name: FUNCTION domicilio_del_paciente_en(p_paciente_id uuid, p_fecha date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.domicilio_del_paciente_en(p_paciente_id uuid, p_fecha date) IS 'Dónde se atiende a un Paciente un día dado. Forma corta de domicilios_de_pacientes_en para un solo Paciente.';


--
-- Name: domicilios_de_pacientes_en(uuid[], date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.domicilios_de_pacientes_en(p_pacientes uuid[], p_fecha date) RETURNS TABLE(paciente_id uuid, domicilio_temporal_id uuid, domicilio text, lat double precision, lng double precision, es_temporal boolean, motivo text, desde date, hasta date)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    p.id AS paciente_id,
    -- Cuál es la fila que está mandando, para que quien la muestre pueda señalarla sin volver a
    -- resolver la regla por su cuenta. Vacío cuando manda la dirección de la ficha.
    d.id AS domicilio_temporal_id,
    COALESCE(d.domicilio, p.domicilio) AS domicilio,
    COALESCE(d.lat, p.lat) AS lat,
    COALESCE(d.lng, p.lng) AS lng,
    d.id IS NOT NULL AS es_temporal,
    d.motivo,
    d.fecha_inicio AS desde,
    d.fecha_fin AS hasta
  FROM public.pacientes p
  LEFT JOIN LATERAL (
    SELECT t.id, t.domicilio, t.lat, t.lng, t.motivo, t.fecha_inicio, t.fecha_fin
    FROM public.domicilios_temporales_paciente t
    WHERE t.paciente_id = p.id
      AND t.fecha_inicio <= p_fecha
      AND (t.fecha_fin IS NULL OR t.fecha_fin >= p_fecha)
    -- La restricción de arriba garantiza que haya una sola; el orden y el tope son la red por si
    -- alguna vez se afloja esa restricción.
    ORDER BY t.fecha_inicio DESC
    LIMIT 1
  ) d ON true
  WHERE p.id = ANY (p_pacientes);
$$;


--
-- Name: FUNCTION domicilios_de_pacientes_en(p_pacientes uuid[], p_fecha date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.domicilios_de_pacientes_en(p_pacientes uuid[], p_fecha date) IS 'Único lugar donde se decide dónde se atiende a un Paciente un día dado: la dirección temporal vigente, o la de la ficha. La usan el check-in, la aplicación del Asistente y el Panel.';


--
-- Name: el_mensaje_se_guarda_ya_tapado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.el_mensaje_se_guarda_ya_tapado() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  lo_tapado record;
BEGIN
  -- Un mensaje automático no lo escribió nadie: su cuerpo es una clave de traducción. Buscarle
  -- un teléfono a una clave no encuentra nada y podría romperla.
  IF NEW.automatico THEN
    NEW.regla_tapada := NULL;
    RETURN NEW;
  END IF;

  SELECT t.texto, t.regla
    INTO lo_tapado
    FROM interno.tapar_lo_que_no_viaja_en_un_mensaje(NEW.cuerpo, NEW.prestadora_id) t;

  NEW.cuerpo       := lo_tapado.texto;
  NEW.regla_tapada := lo_tapado.regla;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION el_mensaje_se_guarda_ya_tapado(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.el_mensaje_se_guarda_ya_tapado() IS 'Sobre mensajes_match: tapa el texto antes de escribirlo y anota que regla lo tapo. El texto tapado no se guarda, no se registra y no sale en ningun error.';


--
-- Name: estado_de_factura(numeric, numeric, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.estado_de_factura(p_monto_total numeric, p_cobrado numeric, p_fecha_vencimiento date) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    -- Nada por cobrar, nada que reclamar. Vale también para una factura de cero.
    WHEN COALESCE(p_cobrado, 0) >= COALESCE(p_monto_total, 0) THEN 'pagada'
    WHEN p_fecha_vencimiento IS NOT NULL AND p_fecha_vencimiento < CURRENT_DATE THEN 'vencida'
    ELSE 'pendiente'
  END;
$$;


--
-- Name: FUNCTION estado_de_factura(p_monto_total numeric, p_cobrado numeric, p_fecha_vencimiento date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.estado_de_factura(p_monto_total numeric, p_cobrado numeric, p_fecha_vencimiento date) IS 'Único lugar donde se decide si una factura está pagada, vencida o pendiente. Cobro parcial: sigue pendiente (o vencida), y el cuánto falta lo dice el saldo.';


--
-- Name: exigir_matricula_en_guardia(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.exigir_matricula_en_guardia() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  v_motivo text;
BEGIN
  IF NEW.asistente_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.asistente_id IS NOT DISTINCT FROM OLD.asistente_id THEN
    RETURN NEW;
  END IF;

  v_motivo := interno.motivo_bloqueo_matricula(
    NEW.asistente_id,
    public.dia_en_que_termina_guardia(NEW.fecha, NEW.hora_inicio, NEW.hora_fin)
  );

  IF v_motivo IS NOT NULL THEN
    RAISE EXCEPTION 'matricula_bloquea:%:', v_motivo
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: exigir_matricula_en_oferta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.exigir_matricula_en_oferta() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  v_motivo text;
  v_dia    date;
BEGIN
  -- Al invitar se mira contra hoy; al aceptar, contra el final de la guardia.
  IF TG_OP = 'UPDATE' THEN
    IF NEW.respuesta IS DISTINCT FROM 'acepta'
       OR NEW.respuesta IS NOT DISTINCT FROM OLD.respuesta THEN
      RETURN NEW;
    END IF;

    SELECT public.dia_en_que_termina_guardia(g.fecha, g.hora_inicio, g.hora_fin)
      INTO v_dia
      FROM public.guardias g
     WHERE g.id = NEW.guardia_id;
  ELSE
    v_dia := CURRENT_DATE;
  END IF;

  v_motivo := interno.motivo_bloqueo_matricula(NEW.asistente_id, COALESCE(v_dia, CURRENT_DATE));

  IF v_motivo IS NOT NULL THEN
    RAISE EXCEPTION 'matricula_bloquea:%:', v_motivo
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: exigir_paciente_del_turno(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.exigir_paciente_del_turno() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM guardia_pacientes gp
    WHERE gp.guardia_id = NEW.guardia_id AND gp.paciente_id = NEW.paciente_id
  ) THEN
    RAISE EXCEPTION 'El reporte habla de un Paciente que este turno no atiende';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_auditoria_de_acceso_mutacion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_auditoria_de_acceso_mutacion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  v_registro_id UUID;
BEGIN
  IF NOT hay_permiso_de_acceso_vigente() THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'DELETE' THEN
    BEGIN
      v_registro_id := OLD.id;
    EXCEPTION WHEN undefined_column THEN
      v_registro_id := NULL;
    END;
  ELSE
    BEGIN
      v_registro_id := NEW.id;
    EXCEPTION WHEN undefined_column THEN
      v_registro_id := NULL;
    END;
  END IF;

  INSERT INTO auditoria_de_accesos (admin_id, prestadora_id, tipo_evento, tabla_afectada, operacion, registro_id)
  VALUES (auth.uid(), current_tenant(), 'mutacion', TG_TABLE_NAME, TG_OP, v_registro_id);

  RETURN NULL;
END;
$$;


--
-- Name: fn_completar_moneda(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_completar_moneda() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
BEGIN
  IF NEW.moneda IS NULL AND NEW.prestadora_id IS NOT NULL THEN
    NEW.moneda := interno.moneda_de_prestadora(NEW.prestadora_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_completar_moneda_desde_cliente(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_completar_moneda_desde_cliente() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
BEGIN
  IF NEW.moneda IS NULL THEN
    SELECT interno.moneda_de_prestadora(f.prestadora_id) INTO NEW.moneda
    FROM public.clientes f WHERE f.id = NEW.cliente_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_completar_moneda_desde_padre(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_completar_moneda_desde_padre() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  tabla_padre text := TG_ARGV[0];
  columna_fk  text := TG_ARGV[1];
  moneda_padre public.moneda_iso;
BEGIN
  IF NEW.moneda IS NULL THEN
    EXECUTE format('SELECT moneda FROM public.%I WHERE id = ($1).%I', tabla_padre, columna_fk)
      INTO moneda_padre
      USING NEW;
    NEW.moneda := moneda_padre;
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: fn_completar_prestadora_desde_padre(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_completar_prestadora_desde_padre() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
DECLARE
  tabla_padre text := TG_ARGV[0];
  columna_fk  text := TG_ARGV[1];
  prestadora_padre uuid;
BEGIN
  IF NEW.prestadora_id IS NULL THEN
    EXECUTE format('SELECT prestadora_id FROM public.%I WHERE id = ($1).%I', tabla_padre, columna_fk)
      INTO prestadora_padre
      USING NEW;
    NEW.prestadora_id := prestadora_padre;
  END IF;
  RETURN NEW;
END;
$_$;


