--
-- Name: fn_estado_factura_segun_cobros(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_estado_factura_segun_cobros() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cobrado numeric;
BEGIN
  SELECT cobrado INTO v_cobrado FROM public.resumen_cobros_de_factura(NEW.id);
  NEW.estado := public.estado_de_factura(
    public.monto_a_cobrar_de_factura(NEW.monto_total, NEW.monto_facturado, NEW.id),
    v_cobrado,
    NEW.fecha_vencimiento
  );
  RETURN NEW;
END;
$$;


--
-- Name: fn_modalidad_de_la_guardia(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_modalidad_de_la_guardia() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
BEGIN
  IF NEW.asistente_id IS NULL OR NEW.canal_modalidad IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND NEW.asistente_id IS NOT DISTINCT FROM OLD.asistente_id
     AND NEW.canal_modalidad IS NOT DISTINCT FROM OLD.canal_modalidad THEN
    RETURN NEW;
  END IF;

  IF NOT interno.asistente_trabaja_en_modalidad(NEW.asistente_id, NEW.canal_modalidad) THEN
    RAISE EXCEPTION 'modalidad_bloquea:%:', NEW.canal_modalidad
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_modalidad_en_oferta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_modalidad_en_oferta() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  v_modalidad text;
BEGIN
  IF NEW.asistente_id IS NULL OR NEW.guardia_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND NEW.asistente_id IS NOT DISTINCT FROM OLD.asistente_id
     AND NEW.guardia_id IS NOT DISTINCT FROM OLD.guardia_id THEN
    RETURN NEW;
  END IF;

  SELECT g.canal_modalidad INTO v_modalidad
    FROM public.guardias g
   WHERE g.id = NEW.guardia_id;

  IF v_modalidad IS NOT NULL
     AND NOT interno.asistente_trabaja_en_modalidad(NEW.asistente_id, v_modalidad) THEN
    RAISE EXCEPTION 'modalidad_bloquea:%:', v_modalidad
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_modalidades_de_asistente_nuevo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_modalidades_de_asistente_nuevo() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
BEGIN
  -- Solo cuando no vinieron elegidas. Si el alta las mandó, mandan las que mandó:
  -- el valor por omisión de la columna no distingue una cosa de la otra.
  IF NEW.prestadora_id IS NOT NULL
     AND (NEW.canales IS NULL
          OR NEW.canales = ARRAY['directa'::text, 'match'::text]) THEN
    NEW.canales := interno.modalidades_habilitadas_de_prestadora(NEW.prestadora_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_modalidades_dentro_de_lo_habilitado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_modalidades_dentro_de_lo_habilitado() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'interno'
    AS $$
DECLARE
  v_habilitadas text[];
  v_sobrante text;
BEGIN
  IF NEW.prestadora_id IS NULL OR NEW.canales IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.canales IS NOT DISTINCT FROM OLD.canales THEN
    RETURN NEW;
  END IF;

  v_habilitadas := interno.modalidades_habilitadas_de_prestadora(NEW.prestadora_id);

  SELECT m INTO v_sobrante
    FROM unnest(NEW.canales) AS m
   WHERE NOT (m = ANY(v_habilitadas))
   LIMIT 1;

  IF v_sobrante IS NOT NULL THEN
    RAISE EXCEPTION 'modalidad_no_habilitada:%:', v_sobrante
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_moneda_de_prestadora_nueva(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_moneda_de_prestadora_nueva() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_moneda public.moneda_iso;
BEGIN
  IF NEW.moneda IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT m.moneda INTO v_moneda FROM public.monedas_por_pais m WHERE m.pais = NEW.pais;

  IF v_moneda IS NULL THEN
    RAISE EXCEPTION
      'No se sabe en qué moneda trabaja una Prestadora del país %. Agregue ese país al catálogo monedas_por_pais, o indique la moneda al dar de alta la Prestadora.',
      NEW.pais;
  END IF;

  NEW.moneda := v_moneda;
  RETURN NEW;
END;
$$;


--
-- Name: fn_rastro_del_cierre_por_el_asistente(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_rastro_del_cierre_por_el_asistente() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Que la hora de salida sea nueva. Un UPDATE cualquiera sobre una guardia ya cerrada no
  -- vuelve a marcar nada.
  IF NEW.checkout_at IS NULL OR OLD.checkout_at IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Que la guardia efectivamente quede cerrada. Marcar la salida sin dar por terminada la
  -- guardia no es un cierre.
  IF NEW.estado IS DISTINCT FROM 'completada' THEN
    RETURN NEW;
  END IF;

  -- Que nadie haya escrito ya el rastro en esta misma operación. Si vino escrito, manda quien
  -- lo escribió.
  IF NEW.cerrada_at IS NOT NULL OR NEW.cerrada_origen IS NOT NULL THEN
    RETURN NEW;
  END IF;

  NEW.cerrada_at     := NEW.checkout_at;
  NEW.cerrada_origen := 'asistente';
  NEW.cerrada_por    := NEW.asistente_id;
  NEW.cerrada_motivo := NULL;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_rastro_del_cierre_por_el_asistente(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_rastro_del_cierre_por_el_asistente() IS 'Le pone la etiqueta al cierre que hace el Asistente cuando marca su salida. No cierra guardias: solo escribe quién, cuándo y desde dónde, sobre un cierre que ya está ocurriendo en esa misma operación.';


--
-- Name: fn_refrescar_factura_de_un_cobro(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_refrescar_factura_de_un_cobro() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    UPDATE public.facturas_cliente SET updated_at = now() WHERE id = OLD.factura_id;
  END IF;

  IF TG_OP <> 'DELETE' AND (TG_OP = 'INSERT' OR NEW.factura_id IS DISTINCT FROM OLD.factura_id) THEN
    UPDATE public.facturas_cliente SET updated_at = now() WHERE id = NEW.factura_id;
  END IF;

  RETURN NULL;
END;
$$;


