--
-- Name: marcar_prestaciones_a_revisar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marcar_prestaciones_a_revisar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.precio IS DISTINCT FROM OLD.precio THEN
    UPDATE prestaciones
    SET requiere_revision = true
    WHERE precio_lista_id = NEW.id AND estado = 'vigente';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: monto_a_cobrar_de_factura(numeric, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.monto_a_cobrar_de_factura(p_monto_total numeric, p_monto_facturado numeric, p_factura_id uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT (COALESCE(p_monto_facturado, p_monto_total, 0)
          + (SELECT neto FROM public.correcciones_de_factura(p_factura_id)))::numeric(12, 2);
$$;


--
-- Name: FUNCTION monto_a_cobrar_de_factura(p_monto_total numeric, p_monto_facturado numeric, p_factura_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.monto_a_cobrar_de_factura(p_monto_total numeric, p_monto_facturado numeric, p_factura_id uuid) IS 'Lo que se le reclama al Cliente: lo que el software de facturacion emitio -o lo que se mando a facturar, mientras no se haya emitido- mas y menos las correcciones.';


