-- Name: advertencias_legales; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.advertencias_legales (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    jurisdiccion text NOT NULL,
    funcion_clave text NOT NULL,
