    motivo text,
    reportado_por uuid,
    detectado_at timestamp with time zone DEFAULT now() NOT NULL,
    resuelto_at timestamp with time zone,
    resuelto_nota text,
    ultima_notificacion_at timestamp with time zone,
    veces_notificado integer DEFAULT 0 NOT NULL,
    backup_notificado_at timestamp with time zone
);


--
-- Name: asistente_lugares; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.asistente_lugares (
    asistente_id uuid NOT NULL,
    lugar_id uuid NOT NULL,
    prestadora_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE asistente_lugares; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.asistente_lugares IS 'Los lugares donde cada Asistente acepta trabajar. Se guardan lugares y no zonas: su disponibilidad no tiene por que coincidir con el agrupamiento de la Prestadora.';


--
-- Name: asistentes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.asistentes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    nombre text NOT NULL,
    telefono text,
    email text,
    foto_url text,
    especialidades text[],
    disponibilidad jsonb,
    estado text DEFAULT 'activo'::text NOT NULL,
    qr_token text DEFAULT (gen_random_uuid())::text,
    tipo_vinculo text DEFAULT 'monotributo'::text NOT NULL,
    fecha_alta date DEFAULT CURRENT_DATE NOT NULL,
    fecha_baja date,
    horas_semanales numeric(5,2),
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    deleted_at timestamp with time zone,
    dni text,
    prestadora_id uuid NOT NULL,
    canales text[] DEFAULT ARRAY['directa'::text, 'match'::text] NOT NULL,
    importacion_id uuid,
    pendiente_conformidad boolean DEFAULT false NOT NULL,
    tipo_asistente_id uuid,
    domicilio text,
    lat double precision,
    lng double precision,
    disponible_para_ofertas boolean DEFAULT true NOT NULL,
    disponibilidad_cambiada_en timestamp with time zone,
    calle text,
    numero text,
    piso text,
    unidad text,
    lugar_id uuid,
    usuario_id uuid NOT NULL,
    CONSTRAINT asistentes_canales_valido CHECK (((canales <@ ARRAY['directa'::text, 'match'::text]) AND (array_length(canales, 1) > 0))),
    CONSTRAINT asistentes_estado_check CHECK ((estado = ANY (ARRAY['activo'::text, 'inactivo'::text, 'cesado'::text]))),
    CONSTRAINT asistentes_tipo_vinculo_check CHECK ((tipo_vinculo = ANY (ARRAY['monotributo'::text, 'dependencia'::text])))
);


--
-- Name: COLUMN asistentes.especialidades; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.asistentes.especialidades IS 'RETIRADA (2026-08-11). Texto libre de la época en que el tipo de Asistente se escribia a mano. Se conserva tal cual se cargo; no se escribe mas. Lo vigente es asistentes.tipo_asistente_id, que apunta al catalogo tipos_asistente.';


--
-- Name: COLUMN asistentes.canales; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.asistentes.canales IS 'En qué modalidades de trabajo está este Asistente: directa, match, o las dos. Nunca subcontratacion: esa gente no es nuestra. Tiene que estar dentro de lo que la Prestadora tenga habilitado. El nombre de la columna quedó de antes y no se renombra (regla 13); la palabra del producto es modalidad de trabajo.';


--
-- Name: COLUMN asistentes.tipo_asistente_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.asistentes.tipo_asistente_id IS 'Que ES este Asistente: cuidador/a, enfermero/a, kinesiologo/a, medico/a o el tipo que haya creado su Prestadora. Decide sus Tareas y si se le exige Matricula vigente para atender.';


--
-- Name: COLUMN asistentes.domicilio; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.asistentes.domicilio IS 'Dónde vive el Asistente, escrito para que lo lea una persona. Dato sensible: no sale en URLs, ni en registros, ni al Cliente (CLAUDE.md §6).';


--
-- Name: COLUMN asistentes.lat; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.asistentes.lat IS 'Latitud del domicilio del Asistente. Nula mientras no se haya ubicado la dirección en el mapa.';


--
-- Name: COLUMN asistentes.lng; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.asistentes.lng IS 'Longitud del domicilio del Asistente. Nula mientras no se haya ubicado la dirección en el mapa.';


--
-- Name: COLUMN asistentes.disponible_para_ofertas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.asistentes.disponible_para_ofertas IS 'Lo decide el Asistente desde su aplicacion, no la Prestadora. En false, la fase automatica de relevo no le escribe y en el panel de cobertura queda al fondo con su motivo. No cambia ninguna guardia ya asignada. Distinto de asistentes.estado, que es la decision administrativa de la Prestadora.';


--
-- Name: COLUMN asistentes.disponibilidad_cambiada_en; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.asistentes.disponibilidad_cambiada_en IS 'Cuando lo cambio por ultima vez. Sirve para que quien coordina sepa si el "no disponible" es de hoy o de hace tres meses.';


--
-- Name: COLUMN asistentes.lugar_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.asistentes.lugar_id IS 'La localidad o el barrio donde vive. Donde acepta trabajar se guarda aparte, en asistente_lugares.';


--
-- Name: COLUMN asistentes.usuario_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.asistentes.usuario_id IS 'De qué cuenta cuelga esta ficha. Una cuenta puede tener una ficha por Prestadora; la ficha es el legajo de trabajo en esa Prestadora y la cuenta es la persona.';


--
-- Name: asistentes_coordinador; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.asistentes_coordinador WITH (security_invoker='true') AS
 SELECT id,
    nombre,
    telefono,
    email,
    foto_url,
    especialidades,
    disponibilidad,
    estado,
    qr_token,
    fecha_alta,
    created_at,
    updated_at,
    deleted_at,
    dni,
    tipo_asistente_id
   FROM public.asistentes;


--
-- Name: VIEW asistentes_coordinador; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.asistentes_coordinador IS 'Lo que quien coordina ve de una Asistente: sin vinculo laboral y sin remuneraciones.';


--
-- Name: auditoria_advertencias_legales; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.auditoria_advertencias_legales (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    usuario_id uuid NOT NULL,
    funcion_clave text NOT NULL,
    jurisdiccion text NOT NULL,
    texto_mostrado text NOT NULL,
    created_at timestamp with time zone DEFAULT now()
);


--
-- Name: auditoria_asignaciones_con_aviso; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.auditoria_asignaciones_con_aviso (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    usuario_id uuid NOT NULL,
    guardia_id uuid NOT NULL,
    asistente_id uuid NOT NULL,
    avisos jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT auditoria_asignaciones_con_aviso_hay_algo CHECK (((jsonb_typeof(avisos) = 'array'::text) AND (jsonb_array_length(avisos) > 0)))
);


--
-- Name: TABLE auditoria_asignaciones_con_aviso; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.auditoria_asignaciones_con_aviso IS 'Quien asigno un turno teniendo avisos delante, y cuales eran. Registra la decision, no el resultado: se escribe antes de asignar.';


--
-- Name: COLUMN auditoria_asignaciones_con_aviso.avisos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.auditoria_asignaciones_con_aviso.avisos IS 'Los avisos que se mostraron, como claves de traduccion y valores. Los arma panel/src/lib/avisosAsignacion.js. Nunca datos de la persona atendida ni tipo de ausencia.';


--
-- Name: auditoria_cambio_dueno_push; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.auditoria_cambio_dueno_push (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    suscripcion_id uuid NOT NULL,
    prestadora_anterior uuid NOT NULL,
    prestadora_nueva uuid NOT NULL,
    usuario_anterior uuid NOT NULL,
    usuario_nuevo uuid NOT NULL,
    rol_anterior text NOT NULL,
    rol_nuevo text NOT NULL,
    user_agent text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT auditoria_cambio_dueno_push_rol_anterior_check CHECK ((rol_anterior = ANY (ARRAY['asistente'::text, 'cliente'::text]))),
    CONSTRAINT auditoria_cambio_dueno_push_rol_nuevo_check CHECK ((rol_nuevo = ANY (ARRAY['asistente'::text, 'cliente'::text])))
);


--
-- Name: auditoria_de_accesos; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.auditoria_de_accesos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    admin_id uuid NOT NULL,
    prestadora_id uuid NOT NULL,
    tipo_evento text NOT NULL,
    tabla_afectada text,
    operacion text,
    registro_id uuid,
    detalle jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT auditoria_de_accesos_operacion_check CHECK ((operacion = ANY (ARRAY['INSERT'::text, 'UPDATE'::text, 'DELETE'::text]))),
    CONSTRAINT auditoria_de_accesos_tipo_evento_check CHECK ((tipo_evento = ANY (ARRAY['login'::text, 'logout'::text, 'renovacion'::text, 'mutacion'::text])))
);


--
-- Name: TABLE auditoria_de_accesos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.auditoria_de_accesos IS 'Todo lo que se hizo con un permiso de acceso: la entrada, la renovacion, la salida —con su motivo— y cada escritura hecha adentro de la Prestadora visitada. Nunca claves ni contenido.';


--
-- Name: auditoria_respuesta_automatica_whatsapp; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.auditoria_respuesta_automatica_whatsapp (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    conversacion_id uuid,
    mensaje_entrante_id uuid,
    mensaje_saliente_id uuid,
    respuesta_preparada_id uuid,
    resultado text NOT NULL,
    motivo text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT el_motivo_sale_de_la_lista CHECK ((motivo = ANY (ARRAY['respuesta_aprobada'::text, 'sin_respuesta_aprobada'::text, 'tema_de_salud'::text, 'emergencia'::text, 'sin_telefono_de_emergencia'::text, 'no_se_pudo_clasificar'::text, 'envio_fallido'::text]))),
    CONSTRAINT el_resultado_sale_de_la_lista CHECK ((resultado = ANY (ARRAY['respondida'::text, 'derivada_a_una_persona'::text, 'emergencia_avisada'::text]))),
    CONSTRAINT lo_respondido_dice_con_que_respuesta CHECK (((resultado <> 'respondida'::text) OR (respuesta_preparada_id IS NOT NULL)))
);


--
-- Name: TABLE auditoria_respuesta_automatica_whatsapp; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.auditoria_respuesta_automatica_whatsapp IS 'Qué contestó sola la respuesta automática de WhatsApp, en cuál conversación y con cuál respuesta aprobada. Sin contenido: sólo identificadores y un motivo de lista cerrada.';


--
-- Name: ausencias; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ausencias (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    asistente_id uuid,
    tipo text NOT NULL,
    fecha_inicio date NOT NULL,
    fecha_fin date NOT NULL,
    certificado_url text,
    dias_computados numeric(5,1),
    guardias_afectadas uuid[],
    observaciones text,
    created_at timestamp with time zone DEFAULT now(),
    prestadora_id uuid NOT NULL,
    avisada_en timestamp with time zone DEFAULT now(),
    aviso_ausencia_at timestamp with time zone,
    aviso_ausencia_veces integer DEFAULT 0 NOT NULL,
    aviso_ausencia_clase text,
    fecha_vuelta_real date,
    pregunta_vuelta_at timestamp with time zone,
    pregunta_vuelta_veces integer DEFAULT 0 NOT NULL,
    usuario_id uuid,
    coordinador_que_cubre_id uuid,
    CONSTRAINT ausencias_de_una_sola_persona CHECK ((num_nonnulls(asistente_id, usuario_id) = 1)),
    CONSTRAINT ausencias_fin_no_antes_del_inicio CHECK ((fecha_fin >= fecha_inicio)),
    CONSTRAINT ausencias_tipo_check CHECK ((tipo = ANY (ARRAY['enfermedad_inculpable'::text, 'accidente_inculpable'::text, 'otra_licencia'::text, 'ausencia_no_justificada'::text]))),
    CONSTRAINT ausencias_vuelta_despues_del_inicio CHECK (((fecha_vuelta_real IS NULL) OR (fecha_vuelta_real > fecha_inicio)))
);


--
-- Name: COLUMN ausencias.avisada_en; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ausencias.avisada_en IS 'Momento en que la Prestadora se entero de esta ausencia, que no es el momento en que se cargo. De aca sale si llego con tiempo o de golpe; la cuenta no se guarda.';


--
-- Name: COLUMN ausencias.aviso_ausencia_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ausencias.aviso_ausencia_at IS 'Ultima vez que se aviso por esta ausencia. Lo escribe el proceso de fondo, no la pantalla.';


--
-- Name: COLUMN ausencias.aviso_ausencia_veces; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ausencias.aviso_ausencia_veces IS 'Cuantas veces se aviso por esta ausencia.';


--
-- Name: COLUMN ausencias.aviso_ausencia_clase; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ausencias.aviso_ausencia_clase IS 'Con que clase se aviso la ultima vez (con_tiempo o de_golpe). Si la clase cambia se vuelve a avisar aunque no haya pasado el intervalo: el problema dejo de ser el mismo.';


--
-- Name: ausencias_cambios_de_fecha; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ausencias_cambios_de_fecha (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    ausencia_id uuid NOT NULL,
    fecha_anterior date NOT NULL,
    fecha_nueva date NOT NULL,
    cambiado_por uuid DEFAULT auth.uid(),
    cambiado_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: autorizaciones_monitoreo_paciente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.autorizaciones_monitoreo_paciente (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    paciente_id uuid NOT NULL,
    nombre_avala text NOT NULL,
    rol_avala text NOT NULL,
    tipo_firma text NOT NULL,
    archivo_url text NOT NULL,
    fecha_autorizacion date NOT NULL,
    vigente boolean DEFAULT true NOT NULL,
    registrado_por uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT autorizaciones_monitoreo_paciente_rol_avala_check CHECK ((rol_avala = ANY (ARRAY['profesional'::text, 'familiar'::text]))),
    CONSTRAINT autorizaciones_monitoreo_paciente_tipo_firma_check CHECK ((tipo_firma = ANY (ARRAY['fisica'::text, 'digital'::text])))
);


--
-- Name: calificaciones_asistente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.calificaciones_asistente (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    asistente_id uuid NOT NULL,
    paciente_id uuid NOT NULL,
    cliente_id uuid NOT NULL,
    guardia_id uuid NOT NULL,
    prestadora_id uuid NOT NULL,
    estrellas integer NOT NULL,
    comentario text,
    visible_publica boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    descargo_asistente text,
    descargo_en timestamp with time zone,
    CONSTRAINT calificaciones_asistente_estrellas_check CHECK (((estrellas >= 1) AND (estrellas <= 5)))
);


--
-- Name: cambios_de_clave_habilitados; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cambios_de_clave_habilitados (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    usuario_id uuid NOT NULL,
    habilitado_por uuid NOT NULL,
    expira_en timestamp with time zone NOT NULL,
    usado_en timestamp with time zone,
    anulado_en timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT cambios_de_clave_habilitados_no_a_uno_mismo CHECK ((usuario_id <> habilitado_por))
);


--
-- Name: TABLE cambios_de_clave_habilitados; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.cambios_de_clave_habilitados IS 'La puerta que la Prestadora le abre a alguien que llamó porque no puede entrar. Dura poco, sirve una vez, y no guarda ninguna clave ni nada con que deducirla: quien habilita nunca elige ni ve la clave de nadie.';


--
-- Name: catalogo_acciones_permisos; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.catalogo_acciones_permisos (
    accion text NOT NULL,
    default_solo_admin boolean NOT NULL,
    orden smallint NOT NULL,
    creado_en timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE catalogo_acciones_permisos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.catalogo_acciones_permisos IS 'Las acciones que una Prestadora puede reservar al administrador, y qué pasa cuando no configuró nada. Punto único de verdad del valor por defecto (pendiente #127).';


--
-- Name: catalogo_acciones_registradas; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.catalogo_acciones_registradas (
    accion text NOT NULL,
    grupo text NOT NULL,
    orden smallint NOT NULL,
    creado_en timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT catalogo_acciones_registradas_grupo_conocido CHECK ((grupo = ANY (ARRAY['entrada_administrativa'::text, 'permisos_y_membresia'::text, 'borrado_de_datos'::text, 'modificacion_critica'::text, 'consecuencia_economica'::text])))
);


--
-- Name: TABLE catalogo_acciones_registradas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.catalogo_acciones_registradas IS 'Que acciones deja anotadas el registro de actividad. La clave es opaca: el texto visible vive en las traducciones del Panel, en los tres idiomas.';


--
-- Name: COLUMN catalogo_acciones_registradas.grupo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.catalogo_acciones_registradas.grupo IS 'A cual de los cinco casos que pide la regla de la empresa responde esta accion.';


--
-- Name: catalogo_datos_del_registro; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.catalogo_datos_del_registro (
    clave text NOT NULL,
    orden smallint NOT NULL,
    creado_en timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE catalogo_datos_del_registro; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.catalogo_datos_del_registro IS 'Los unicos datos con nombre que el registro de actividad admite adentro de `detalle`. Lista de lo permitido, no de lo prohibido: lo que no figura acá hace fallar la escritura.';


--
-- Name: catalogo_documentos_de_identidad; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.catalogo_documentos_de_identidad (
    pais text NOT NULL,
    clase text NOT NULL,
    codigo text NOT NULL,
    sigla text NOT NULL,
    orden integer DEFAULT 100 NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    CONSTRAINT catalogo_documentos_clase_conocida CHECK ((clase = ANY (ARRAY['fisica'::text, 'juridica'::text])))
);


--
-- Name: TABLE catalogo_documentos_de_identidad; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.catalogo_documentos_de_identidad IS 'Que documentos de identidad emite cada pais, y a que clase de Persona le corresponde cada uno. No es configuracion de ninguna Prestadora: es lo que emite un Estado.';


--
-- Name: catalogo_funciones_match; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.catalogo_funciones_match (
    clave text NOT NULL,
    orden smallint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE catalogo_funciones_match; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.catalogo_funciones_match IS 'Las funciones de la modalidad Match que tienen riesgo legal conocido. Es el catálogo de la plataforma: qué se puede encender. Si esa función tiene advertencia escrita para la jurisdicción de la Prestadora, encenderla la muestra y la deja auditada.';


--
-- Name: COLUMN catalogo_funciones_match.clave; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.catalogo_funciones_match.clave IS 'La misma cadena que nombra a esta función en advertencias_legales y en auditoria_advertencias_legales. Nombre guardado: no se renombra.';


--
-- Name: COLUMN catalogo_funciones_match.orden; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.catalogo_funciones_match.orden IS 'En qué orden se listan en pantalla. Es el orden del documento legal, para poder leerlas al lado del documento.';


--
-- Name: catalogo_identificadores_de_cuenta; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.catalogo_identificadores_de_cuenta (
    pais text NOT NULL,
    codigo text NOT NULL,
    sigla text NOT NULL,
    orden integer DEFAULT 100 NOT NULL,
    activo boolean DEFAULT true NOT NULL
);


--
-- Name: TABLE catalogo_identificadores_de_cuenta; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.catalogo_identificadores_de_cuenta IS 'Con que numero se identifica una cuenta bancaria en cada pais. Un pais nuevo entra cargando filas, nunca tocando codigo.';


--
-- Name: COLUMN catalogo_identificadores_de_cuenta.sigla; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.catalogo_identificadores_de_cuenta.sigla IS 'Como se llama ese identificador en su pais. No se traduce: CBU y CVU son nombres propios.';


--
-- Name: catalogo_periodos_cobro; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.catalogo_periodos_cobro (
    clave text NOT NULL,
    orden smallint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: catalogo_prefijos_de_celular; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.catalogo_prefijos_de_celular (
    pais text NOT NULL,
    prefijo text NOT NULL,
    orden integer DEFAULT 100 NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    CONSTRAINT el_prefijo_de_celular_es_solo_digitos CHECK ((prefijo ~ '^[0-9]+$'::text))
);


--
-- Name: TABLE catalogo_prefijos_de_celular; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.catalogo_prefijos_de_celular IS 'Con que empieza un numero de celular en cada pais, en forma internacional y solo con digitos. Un pais nuevo entra cargando filas, nunca tocando codigo. El pais sin filas no tiene ningun numero reconocido como celular.';


--
-- Name: COLUMN catalogo_prefijos_de_celular.prefijo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.catalogo_prefijos_de_celular.prefijo IS 'Digitos con los que empieza el numero, sin el mas y sin separadores. Incluye el codigo de pais.';


--
-- Name: catalogo_proveedores_de_mensaje_de_texto; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.catalogo_proveedores_de_mensaje_de_texto (
    proveedor text NOT NULL,
    orden smallint DEFAULT 100 NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    creado_en timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE catalogo_proveedores_de_mensaje_de_texto; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.catalogo_proveedores_de_mensaje_de_texto IS 'Los proveedores de mensaje de texto que el producto conoce. Nace vacio a proposito: con este catalogo vacio la via sale en la lista de Avisos y no se puede elegir. Un proveedor entra cargando una fila, nunca tocando codigo.';


--
-- Name: COLUMN catalogo_proveedores_de_mensaje_de_texto.proveedor; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.catalogo_proveedores_de_mensaje_de_texto.proveedor IS 'Como se llama el proveedor. Es un nombre propio y no se traduce.';


--
-- Name: catalogo_software_externo; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.catalogo_software_externo (
    clave text NOT NULL,
    clase text NOT NULL,
    nombre text NOT NULL,
    orden smallint DEFAULT 0 NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT catalogo_software_externo_clase_check CHECK ((clase = ANY (ARRAY['facturacion'::text, 'creditos_y_cobranzas'::text]))),
    CONSTRAINT catalogo_software_externo_nombre_check CHECK ((length(btrim(nombre)) > 0))
);


--
-- Name: TABLE catalogo_software_externo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.catalogo_software_externo IS 'Con que software de afuera se puede conectar una Prestadora: los de facturacion y los de creditos y cobranzas. Ninguna de las dos tareas se hace aca; esto dice unicamente con quien se habla.';


--
-- Name: COLUMN catalogo_software_externo.clase; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.catalogo_software_externo.clase IS 'Para que sirve ese software: facturacion, o creditos_y_cobranzas.';


--
-- Name: COLUMN catalogo_software_externo.nombre; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.catalogo_software_externo.nombre IS 'El nombre comercial del producto de ese tercero. No se traduce: es una marca.';


--
-- Name: catalogo_usos_del_codigo_al_telefono; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.catalogo_usos_del_codigo_al_telefono (
    uso text NOT NULL,
    orden smallint NOT NULL,
    creado_en timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE catalogo_usos_del_codigo_al_telefono; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.catalogo_usos_del_codigo_al_telefono IS 'Para qué se manda un código al teléfono. Son tres y ninguna Prestadora las cambia: verificar el número, entrar desde un equipo nuevo y recuperar la clave.';


--
-- Name: certificados; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.certificados (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    asistente_id uuid,
    fecha_emision date NOT NULL,
    fecha_vencimiento date,
    activo boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    prestadora_id uuid NOT NULL
);


--
-- Name: ceses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ceses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    asistente_id uuid NOT NULL,
    fecha_cese date NOT NULL,
    causal public.causal_cese NOT NULL,
    detalle_calculo jsonb,
    monto_total numeric(14,2),
    documentos_generados jsonb,
    revisado_por_abogado boolean DEFAULT false NOT NULL,
    creado_por uuid,
    created_at timestamp with time zone DEFAULT now(),
    prestadora_id uuid NOT NULL,
    moneda public.moneda_iso NOT NULL
);


--
-- Name: cierre_servicio_asistentes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cierre_servicio_asistentes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    cierre_id uuid NOT NULL,
    asistente_id uuid NOT NULL,
    avisado_verbalmente_at timestamp with time zone,
    avisado_verbalmente_por uuid,
    aviso_automatico_enviado_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: cierres_servicio_paciente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cierres_servicio_paciente (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    paciente_id uuid NOT NULL,
    motivo text NOT NULL,
    motivo_detalle text,
    cerrado_por uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    servicio_id uuid
);


--
-- Name: COLUMN cierres_servicio_paciente.servicio_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.cierres_servicio_paciente.servicio_id IS 'Qué Servicio se cerró. Es lo que se pactó con el Cliente, y es por donde preguntan las políticas del Coordinador.';


--
-- Name: clientes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.clientes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    solicitud_id bigint,
    plan text DEFAULT 'directo'::text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    deleted_at timestamp with time zone,
    prestadora_id uuid NOT NULL,
    importacion_id uuid,
    pendiente_conformidad boolean DEFAULT false NOT NULL,
    dias_hasta_el_vencimiento smallint,
    financiador_tipo text,
    pagador_legajo_id uuid,
    usuario_id uuid NOT NULL,
    numero_cliente bigint NOT NULL,
    CONSTRAINT clientes_dias_hasta_el_vencimiento_check CHECK (((dias_hasta_el_vencimiento IS NULL) OR ((dias_hasta_el_vencimiento >= 0) AND (dias_hasta_el_vencimiento <= 365)))),
    CONSTRAINT clientes_financiador_conocido CHECK (((financiador_tipo IS NULL) OR (financiador_tipo = ANY (ARRAY['cliente'::text, 'obra_social'::text, 'otro'::text]))))
);


--
-- Name: COLUMN clientes.dias_hasta_el_vencimiento; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clientes.dias_hasta_el_vencimiento IS 'Cuantos dias tiene este Cliente para pagar, desde que se emite la factura. Vacio hereda el plazo de la Prestadora.';


--
-- Name: COLUMN clientes.financiador_tipo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clientes.financiador_tipo IS 'A quien se le reclama lo que se le factura a este Cliente: cliente, obra_social u otro. Vacio quiere decir que se le reclama al Cliente, que es lo corriente. Cada factura se lleva este dato copiado el dia que se genera.';


--
-- Name: COLUMN clientes.pagador_legajo_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clientes.pagador_legajo_id IS 'Cuál Legajo paga lo que se le factura a este Cliente. Vacío quiere decir que paga el Cliente por sí mismo. Cuando el contrato lo dice, la responsabilidad legal y comercial también es suya.';


--
-- Name: COLUMN clientes.usuario_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clientes.usuario_id IS 'De qué cuenta cuelga esta ficha. Es la cuenta del titular; las demás personas autorizadas cuelgan de `personas_autorizadas`.';


--
-- Name: COLUMN clientes.numero_cliente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clientes.numero_cliente IS 'Unico adentro de la Prestadora. Lo asigna el disparador, no se elige y no se reasigna nunca. Es lo que usan el sistema y los documentos; el nombre visible del Cliente se calcula aparte y es para la pantalla.';


--
-- Name: coberturas_de_ausencia; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.coberturas_de_ausencia (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    ausencia_id uuid NOT NULL,
    serie_id uuid NOT NULL,
    asistente_sustituto_id uuid NOT NULL,
    motivo text,
    motivo_detalle text,
    costo_adicional numeric,
    moneda text,
    asignada_por uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    objetada_at timestamp with time zone
);


--
-- Name: cobros_cliente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cobros_cliente (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    factura_id uuid NOT NULL,
    monto numeric(12,2) NOT NULL,
    moneda public.moneda_iso NOT NULL,
    fecha_cobro date DEFAULT CURRENT_DATE NOT NULL,
    medio text NOT NULL,
    origen text DEFAULT 'panel'::text NOT NULL,
    referencia_externa text,
    observaciones text,
    estado text DEFAULT 'registrado'::text NOT NULL,
    motivo_anulacion text,
    anulado_por uuid,
    anulado_at timestamp with time zone,
    registrado_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT cobros_cliente_anulado_con_fecha CHECK (((estado = 'anulado'::text) = (anulado_at IS NOT NULL))),
    CONSTRAINT cobros_cliente_anulado_con_motivo CHECK (((estado <> 'anulado'::text) OR (motivo_anulacion IS NOT NULL))),
    CONSTRAINT cobros_cliente_estado_check CHECK ((estado = ANY (ARRAY['registrado'::text, 'anulado'::text]))),
    CONSTRAINT cobros_cliente_monto_check CHECK ((monto > (0)::numeric)),
    CONSTRAINT cobros_cliente_origen_check CHECK ((origen = ANY (ARRAY['panel'::text, 'importacion'::text, 'api'::text, 'pasarela'::text, 'migracion'::text])))
);


--
-- Name: TABLE cobros_cliente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.cobros_cliente IS 'Cada entrada de plata contra una factura de un Cliente. Varias filas por factura: así se representa el cobro parcial. No es un comprobante fiscal.';


--
-- Name: COLUMN cobros_cliente.medio; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.cobros_cliente.medio IS 'Con que medio pago el Cliente. Es una opcion de la lista «medios_de_pago_del_cliente»: las que trae el producto y las que agrego esta Prestadora.';


--
-- Name: cobros_match; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cobros_match (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    acceso_id uuid NOT NULL,
    prestadora_id uuid NOT NULL,
    medio text NOT NULL,
    monto numeric(12,2) NOT NULL,
    periodo date NOT NULL,
    estado_cobro text DEFAULT 'pendiente'::text NOT NULL,
    referencia_externa text,
    fecha_cobro date DEFAULT CURRENT_DATE NOT NULL,
    registrado_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    moneda public.moneda_iso NOT NULL,
    url_accion text,
    codigo_cupon text,
    CONSTRAINT cobros_match_estado_cobro_check CHECK ((estado_cobro = ANY (ARRAY['pendiente'::text, 'exitoso'::text, 'fallido'::text])))
);


--
-- Name: COLUMN cobros_match.url_accion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.cobros_match.url_accion IS 'Dirección del QR con el que el Cliente paga este período, en los rieles que la devuelven.';


--
-- Name: COLUMN cobros_match.codigo_cupon; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.cobros_match.codigo_cupon IS 'Código del cupón con el que el Cliente paga este período, en los rieles de cobranza en efectivo.';


--
-- Name: codigos_al_telefono; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.codigos_al_telefono (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    usuario_id uuid NOT NULL,
    uso text NOT NULL,
    telefono text NOT NULL,
    codigo_huella text NOT NULL,
    codigo_expira_en timestamp with time zone NOT NULL,
    codigo_intentos smallint DEFAULT 0 NOT NULL,
    verificado_en timestamp with time zone,
    anulado_en timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE codigos_al_telefono; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.codigos_al_telefono IS 'El código corto que se le manda al teléfono de una persona. Se guarda la huella del código, nunca el código. Lo escribe y lo lee únicamente el motor.';


--
-- Name: COLUMN codigos_al_telefono.telefono; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.codigos_al_telefono.telefono IS 'El número que se está verificando, que es al que se le manda el mensaje. No viaja a ninguna pantalla ni a ningún registro.';


--
-- Name: COLUMN codigos_al_telefono.codigo_intentos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.codigos_al_telefono.codigo_intentos IS 'Cuántas veces se probó un código contra este pedido. Es la cuenta del acto, no la del código: pedir uno nuevo no la vuelve a cero. Un código vencido no gasta intento.';


--
-- Name: codigos_de_presencia; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.codigos_de_presencia (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    sujeto_tipo text NOT NULL,
    sujeto_id uuid NOT NULL,
    codigo_huella text NOT NULL,
    expira_en timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT codigos_de_presencia_sujeto_tipo_check CHECK ((sujeto_tipo = ANY (ARRAY['cliente'::text, 'asistente'::text])))
);


--
-- Name: TABLE codigos_de_presencia; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.codigos_de_presencia IS 'El código de seis dígitos que una persona muestra en la pantalla de su teléfono para que el Asistente que llega compruebe que está en la casa (pendiente #113, Plan A). Se guarda hasheado y vence solo a los segundos que configuró la Prestadora.';


--
-- Name: COLUMN codigos_de_presencia.sujeto_tipo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.codigos_de_presencia.sujeto_tipo IS 'Quién muestra el código: cliente (cualquiera de las personas autorizadas) o asistente (el que se va, cuando hay relevo). El Paciente no tiene cuenta en el producto y por eso no figura acá.';


--
-- Name: COLUMN codigos_de_presencia.codigo_huella; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.codigos_de_presencia.codigo_huella IS 'sha256 del código. El código en claro no se guarda en ningún lado: sólo viaja a la pantalla que lo muestra y de ahí a la que lo lee.';


--
-- Name: conceptos_liquidacion; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.conceptos_liquidacion (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    nombre text NOT NULL,
    signo text NOT NULL,
    unidad text NOT NULL,
    origen_valor text DEFAULT 'propio'::text NOT NULL,
    valor numeric(14,4),
    escala_tipo text,
    moneda public.moneda_iso,
    aplica_a text DEFAULT 'todos'::text NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    orden smallint DEFAULT 100 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT conceptos_liquidacion_aplica_a_check CHECK ((aplica_a = ANY (ARRAY['todos'::text, 'dependencia'::text, 'monotributo'::text]))),
    CONSTRAINT conceptos_liquidacion_moneda_cuando_es_plata CHECK ((((unidad <> 'porcentaje'::text) AND (origen_valor = 'propio'::text)) = (moneda IS NOT NULL))),
    CONSTRAINT conceptos_liquidacion_origen_valor_check CHECK ((origen_valor = ANY (ARRAY['propio'::text, 'escala_legal'::text]))),
    CONSTRAINT conceptos_liquidacion_signo_check CHECK ((signo = ANY (ARRAY['suma'::text, 'resta'::text]))),
    CONSTRAINT conceptos_liquidacion_unidad_check CHECK ((unidad = ANY (ARRAY['monto_fijo_mensual'::text, 'porcentaje'::text, 'monto_por_hora'::text]))),
    CONSTRAINT conceptos_liquidacion_valor_segun_origen CHECK ((((origen_valor = 'propio'::text) AND (valor IS NOT NULL) AND (escala_tipo IS NULL)) OR ((origen_valor = 'escala_legal'::text) AND (escala_tipo IS NOT NULL) AND (valor IS NULL))))
);


--
-- Name: TABLE conceptos_liquidacion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.conceptos_liquidacion IS 'Los conceptos de suma y resta que cada Prestadora aplica al pago de sus Asistentes. Ninguno viene cargado de fábrica.';


--
-- Name: conexiones_con_software_externo; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.conexiones_con_software_externo (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    clase text NOT NULL,
    software text NOT NULL,
    credencial_secret_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT conexiones_con_software_externo_clase_check CHECK ((clase = ANY (ARRAY['facturacion'::text, 'creditos_y_cobranzas'::text])))
);


--
-- Name: TABLE conexiones_con_software_externo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.conexiones_con_software_externo IS 'Cual es el software de facturacion y cual el de creditos y cobranzas de cada Prestadora, y la referencia a la caja fuerte con la credencial con la que se entra. Aca no se factura ni se cobra: esto dice unicamente con quien habla.';


--
-- Name: COLUMN conexiones_con_software_externo.credencial_secret_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.conexiones_con_software_externo.credencial_secret_id IS 'Referencia a vault.secrets con la credencial con la que se entra a ese software. El texto nunca se guarda aca y nunca sale hacia el navegador.';


--
-- Name: configuracion_alarmas_tomadas; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_alarmas_tomadas (
    prestadora_id uuid NOT NULL,
    regla jsonb DEFAULT '{}'::jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT configuracion_alarmas_tomadas_regla_es_objeto CHECK ((jsonb_typeof(regla) = 'object'::text))
);


--
-- Name: TABLE configuracion_alarmas_tomadas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.configuracion_alarmas_tomadas IS 'Cuanto dura hacerse cargo de una alarma. Solo lo que esta Prestadora corrio; los valores de fabrica y los bordes viven en panel/src/lib/alarmasTomadas.js.';


--
-- Name: configuracion_alertas_ia; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_alertas_ia (
    prestadora_id uuid NOT NULL,
    palabras_clave text[] DEFAULT '{}'::text[] NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    reportes_a_analizar integer DEFAULT 7 NOT NULL,
    roja_avisa_cliente boolean DEFAULT true NOT NULL,
    amarilla_avisa_cliente boolean DEFAULT false NOT NULL,
    amarilla_avisa_coordinador boolean DEFAULT true NOT NULL,
    CONSTRAINT configuracion_alertas_ia_reportes_a_analizar_check CHECK (((reportes_a_analizar >= 1) AND (reportes_a_analizar <= 30)))
);


--
-- Name: TABLE configuracion_alertas_ia; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.configuracion_alertas_ia IS 'Cómo revisa esta Prestadora los reportes de sus Pacientes con inteligencia artificial: qué palabras adelantan la revisión, cuánto material mira y a quién le avisa según lo que encuentra. Sin fila, valen los valores de fábrica que están en backend/src/routes/panelConfiguracion.js.';


--
-- Name: COLUMN configuracion_alertas_ia.palabras_clave; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_alertas_ia.palabras_clave IS 'Palabras que, si aparecen en un reporte, disparan la revisión en el momento en vez de esperar al horario de siempre (por ejemplo: caída, sangrado, no responde). Las lee backend/src/routes/appAsistentes.js al recibir el reporte.';


--
-- Name: COLUMN configuracion_alertas_ia.reportes_a_analizar; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_alertas_ia.reportes_a_analizar IS 'Cuántos de los últimos reportes de ese Paciente mira la revisión. De fábrica, 7. Cuantos más mire, más contexto tiene y más cuesta cada revisión.';


--
-- Name: COLUMN configuracion_alertas_ia.roja_avisa_cliente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_alertas_ia.roja_avisa_cliente IS 'Si una alerta roja —lo urgente— también le llega al Cliente del Paciente. De fábrica, sí. Al Coordinador le llega siempre, eso no se configura.';


--
-- Name: COLUMN configuracion_alertas_ia.amarilla_avisa_cliente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_alertas_ia.amarilla_avisa_cliente IS 'Si una alerta amarilla —lo que conviene mirar, sin urgencia— también le llega al Cliente. De fábrica, no: la amarilla es material de trabajo de la Prestadora, no una noticia para dar.';


--
-- Name: COLUMN configuracion_alertas_ia.amarilla_avisa_coordinador; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_alertas_ia.amarilla_avisa_coordinador IS 'Si una alerta amarilla le llega al Coordinador. De fábrica, sí. Se puede apagar en una Prestadora que prefiera revisarlas por pantalla en vez de recibirlas de a una.';


--
-- Name: configuracion_ausencia_automatica; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_ausencia_automatica (
    prestadora_id uuid NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    minutos_tolerancia_checkin integer DEFAULT 15 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    metros_tolerancia_checkin integer DEFAULT 150 NOT NULL,
    segundos_codigo_en_pantalla integer DEFAULT 30 NOT NULL,
    minutos_codigo_de_la_prestadora integer DEFAULT 10 NOT NULL,
    CONSTRAINT minutos_codigo_de_la_prestadora_razonable CHECK (((minutos_codigo_de_la_prestadora >= 1) AND (minutos_codigo_de_la_prestadora <= 120))),
    CONSTRAINT segundos_codigo_en_pantalla_razonable CHECK (((segundos_codigo_en_pantalla >= 10) AND (segundos_codigo_en_pantalla <= 300)))
);


--
-- Name: COLUMN configuracion_ausencia_automatica.segundos_codigo_en_pantalla; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_ausencia_automatica.segundos_codigo_en_pantalla IS 'Cada cuántos segundos se renueva el código que el Cliente —o el Asistente que se va— muestra en la pantalla de su teléfono para que lo lea el Asistente que llega. Decisión de cada Prestadora.';


--
-- Name: COLUMN configuracion_ausencia_automatica.minutos_codigo_de_la_prestadora; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_ausencia_automatica.minutos_codigo_de_la_prestadora IS 'Cuántos minutos vale el código de un solo uso que suelta la Prestadora cuando no hay nadie en la casa que pueda mostrar el suyo. Decisión de cada Prestadora.';


--
-- Name: configuracion_ausencias; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_ausencias (
    prestadora_id uuid NOT NULL,
    regla jsonb DEFAULT '{}'::jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT configuracion_ausencias_regla_es_objeto CHECK ((jsonb_typeof(regla) = 'object'::text))
);


--
-- Name: TABLE configuracion_ausencias; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.configuracion_ausencias IS 'Con cuanta anticipacion sobre el primer turno afectado una ausencia se considera avisada con tiempo, y cada cuanto se insiste. Solo lo que esta Prestadora corrio; los valores de fabrica y los bordes viven en panel/src/lib/avisoDeAusencia.js.';


--
-- Name: configuracion_aviso_cese_asistente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_aviso_cese_asistente (
    prestadora_id uuid NOT NULL,
    horas_plazo_aviso_verbal smallint DEFAULT 24 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    activo boolean DEFAULT true NOT NULL
);


--
-- Name: configuracion_aviso_guardia_sin_cubrir; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_aviso_guardia_sin_cubrir (
    prestadora_id uuid NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    horas_antes smallint DEFAULT 48 NOT NULL,
    horas_entre_avisos smallint DEFAULT 12 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT configuracion_aviso_guardia_sin_cubrir_horas_antes_check CHECK (((horas_antes > 0) AND (horas_antes <= 720))),
    CONSTRAINT configuracion_aviso_guardia_sin_cubrir_horas_entre_avisos_check CHECK (((horas_entre_avisos > 0) AND (horas_entre_avisos <= 720)))
);


--
-- Name: TABLE configuracion_aviso_guardia_sin_cubrir; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.configuracion_aviso_guardia_sin_cubrir IS 'Cuándo avisarle al Coordinador que una guardia próxima sigue sin Asistente. Una fila por Prestadora; sin fila no se manda ningún aviso.';


--
-- Name: COLUMN configuracion_aviso_guardia_sin_cubrir.horas_antes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_aviso_guardia_sin_cubrir.horas_antes IS 'Con cuánta anticipación avisar. El aviso arranca cuando faltan estas horas para que empiece la guardia.';


--
-- Name: COLUMN configuracion_aviso_guardia_sin_cubrir.horas_entre_avisos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_aviso_guardia_sin_cubrir.horas_entre_avisos IS 'Cada cuánto repetir el aviso mientras el hueco siga abierto. Evita que el proceso, que corre cada 5 minutos, mande el mismo correo doce veces por hora.';


--
-- Name: configuracion_calculo_candidatos; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_calculo_candidatos (
    prestadora_id uuid NOT NULL,
    perfil text DEFAULT 'continuidad'::text NOT NULL,
    pesos jsonb DEFAULT '{}'::jsonb NOT NULL,
    topes jsonb DEFAULT '{}'::jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT configuracion_calculo_candidatos_perfil_conocido CHECK ((perfil = ANY (ARRAY['continuidad'::text, 'descanso'::text, 'cercania'::text]))),
    CONSTRAINT configuracion_calculo_candidatos_pesos_es_objeto CHECK ((jsonb_typeof(pesos) = 'object'::text)),
    CONSTRAINT configuracion_calculo_candidatos_topes_es_objeto CHECK ((jsonb_typeof(topes) = 'object'::text))
);


--
-- Name: TABLE configuracion_calculo_candidatos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.configuracion_calculo_candidatos IS 'Como ordena cada Prestadora la lista de quienes pueden cubrir un hueco: el perfil elegido y lo que corrio respecto de el. Los valores de fabrica y las tres formas armadas viven en panel/src/lib/perfilesDeCandidatos.js.';


--
-- Name: COLUMN configuracion_calculo_candidatos.perfil; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_calculo_candidatos.perfil IS 'Identificador permanente de la forma armada. Se nombra por su funcion y no se renombra.';


--
-- Name: configuracion_cobro_match; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_cobro_match (
    prestadora_id uuid NOT NULL,
    dias_de_aviso_antes_del_cobro integer DEFAULT 3 NOT NULL,
    dias_de_gracia_por_cobro_rechazado integer DEFAULT 7 NOT NULL,
    dias_de_vida_del_cupon integer DEFAULT 10 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT configuracion_cobro_match_aviso_al_menos_un_dia CHECK ((dias_de_aviso_antes_del_cobro >= 1)),
    CONSTRAINT configuracion_cobro_match_cupon_al_menos_un_dia CHECK ((dias_de_vida_del_cupon >= 1)),
    CONSTRAINT configuracion_cobro_match_gracia_al_menos_un_dia CHECK ((dias_de_gracia_por_cobro_rechazado >= 1))
);


--
-- Name: TABLE configuracion_cobro_match; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.configuracion_cobro_match IS 'Los plazos comerciales del cobro de Match, elegidos por cada Prestadora. Una fila por Prestadora, sembrada al darla de alta.';


--
-- Name: COLUMN configuracion_cobro_match.dias_de_aviso_antes_del_cobro; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_cobro_match.dias_de_aviso_antes_del_cobro IS 'Con cuántos días de anticipación se avisa el primer cobro que viene.';


--
-- Name: COLUMN configuracion_cobro_match.dias_de_gracia_por_cobro_rechazado; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_cobro_match.dias_de_gracia_por_cobro_rechazado IS 'Cuántos días se conserva el acceso, con reintentos, cuando un cobro no entra.';


--
-- Name: COLUMN configuracion_cobro_match.dias_de_vida_del_cupon; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_cobro_match.dias_de_vida_del_cupon IS 'Cuántos días vive el cupón de la red de cobranza desde que se emite.';


--
-- Name: configuracion_de_hce; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_de_hce (
    prestadora_id uuid NOT NULL,
    restriccion_de_hce boolean DEFAULT true NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE configuracion_de_hce; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.configuracion_de_hce IS 'Si rige la restricción de HCE: la información de salud de un paciente la ve sólo quien lo atiende. Sin renglón, rige.';


--
-- Name: configuracion_equipo_paciente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_equipo_paciente (
    prestadora_id uuid NOT NULL,
    regla jsonb DEFAULT '{}'::jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT configuracion_equipo_paciente_regla_es_objeto CHECK ((jsonb_typeof(regla) = 'object'::text))
);


--
-- Name: TABLE configuracion_equipo_paciente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.configuracion_equipo_paciente IS 'Con cuantos turnos y en que ventana de dias se entra solo al equipo de un Paciente. Solo lo que esta Prestadora corrio; los valores de fabrica y los bordes viven en panel/src/lib/equipoDelPaciente.js.';


--
-- Name: configuracion_escalada_coordinador; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_escalada_coordinador (
    prestadora_id uuid NOT NULL,
    coordinador_backup_id uuid,
    minutos_antes_backup integer DEFAULT 15 NOT NULL,
    umbrales_premura jsonb DEFAULT '[{"maximo_minutos": 60, "intervalo_minutos": 10}, {"maximo_minutos": 240, "intervalo_minutos": 30}, {"maximo_minutos": null, "intervalo_minutos": 60}]'::jsonb NOT NULL,
    fase_automatica_activa boolean DEFAULT false NOT NULL,
    minutos_antes_fase_automatica integer DEFAULT 120 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    minutos_gracia_cierre_guardia integer DEFAULT 15 NOT NULL,
    horas_antes_aviso_grave_sin_cerrar integer DEFAULT 4 NOT NULL,
    minutos_antes_todos_los_coordinadores integer DEFAULT 45,
    minutos_antes_administracion integer DEFAULT 90,
    CONSTRAINT horas_antes_aviso_grave_sin_cerrar_razonable CHECK (((horas_antes_aviso_grave_sin_cerrar > 0) AND (horas_antes_aviso_grave_sin_cerrar <= 72))),
    CONSTRAINT minutos_gracia_cierre_guardia_razonable CHECK (((minutos_gracia_cierre_guardia > 0) AND (minutos_gracia_cierre_guardia <= 1440)))
);


--
-- Name: COLUMN configuracion_escalada_coordinador.horas_antes_aviso_grave_sin_cerrar; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_escalada_coordinador.horas_antes_aviso_grave_sin_cerrar IS 'Cuántas horas después de vencido el plazo de cierre el aviso escala al evento guardia_sin_cerrar_grave, que tiene su propia lista de destinatarios. Sale una sola vez por guardia.';


--
-- Name: COLUMN configuracion_escalada_coordinador.minutos_antes_todos_los_coordinadores; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_escalada_coordinador.minutos_antes_todos_los_coordinadores IS 'Minutos desde que empezo la alarma antes de avisarle a todos los Coordinadores. En nulo, ese escalon queda apagado.';


--
-- Name: COLUMN configuracion_escalada_coordinador.minutos_antes_administracion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_escalada_coordinador.minutos_antes_administracion IS 'Minutos desde que empezo la alarma antes de avisarle a la administracion. En nulo, ese escalon queda apagado.';


--
-- Name: configuracion_escalada_relevo; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_escalada_relevo (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    nivel integer NOT NULL,
    minutos_demora integer,
    orden_prioridad text[],
    plantilla_mensaje text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: configuracion_facturacion_clientes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_facturacion_clientes (
    prestadora_id uuid NOT NULL,
    regla jsonb DEFAULT '{}'::jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    secreto_del_aviso_secret_id uuid,
    secreto_del_aviso_de_facturacion_secret_id uuid,
    CONSTRAINT configuracion_facturacion_clientes_regla_es_objeto CHECK ((jsonb_typeof(regla) = 'object'::text))
);


--
-- Name: TABLE configuracion_facturacion_clientes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.configuracion_facturacion_clientes IS 'Como factura y como cobra esta Prestadora lo que no depende de un Cliente sola: el plazo de pago acordado y si el seguimiento de la cobranza es suyo o de otro software. Solo lo que corrio respecto de fabrica; los bordes viven en panel/src/lib/facturacionDeClientes.js.';


--
-- Name: COLUMN configuracion_facturacion_clientes.secreto_del_aviso_secret_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_facturacion_clientes.secreto_del_aviso_secret_id IS 'Referencia a vault.secrets con el secreto con el que el software de creditos y cobranzas de esta Prestadora firma sus avisos de restriccion. El texto nunca se guarda aca. Vacio quiere decir que no entra ningun aviso.';


--
-- Name: COLUMN configuracion_facturacion_clientes.secreto_del_aviso_de_facturacion_secret_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_facturacion_clientes.secreto_del_aviso_de_facturacion_secret_id IS 'Referencia a vault.secrets con el secreto con el que el software de facturacion de esta Prestadora firma lo que emitio. El texto nunca se guarda aca. Vacio quiere decir que no entra ningun aviso.';


--
-- Name: configuracion_funciones_match; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_funciones_match (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    funcion_clave text NOT NULL,
    activa boolean DEFAULT false NOT NULL,
    advertida_en timestamp with time zone,
    advertida_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE configuracion_funciones_match; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.configuracion_funciones_match IS 'Qué funciones de riesgo legal de Match tiene encendidas cada Prestadora. Sin fila, apagada. Nada acá bloquea nada: encender muestra el aviso de la jurisdicción, si lo hay, y lo deja auditado.';


--
-- Name: COLUMN configuracion_funciones_match.advertida_en; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_funciones_match.advertida_en IS 'Cuándo se mostró el último aviso legal al encender esta función. El historial completo, con el texto mostrado, está en auditoria_advertencias_legales.';


--
-- Name: configuracion_incidentes_turno_sin_cubrir; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_incidentes_turno_sin_cubrir (
    prestadora_id uuid NOT NULL,
    regla jsonb DEFAULT '{}'::jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT configuracion_incidentes_turno_sin_cubrir_regla_es_objeto CHECK ((jsonb_typeof(regla) = 'object'::text))
);


--
-- Name: TABLE configuracion_incidentes_turno_sin_cubrir; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.configuracion_incidentes_turno_sin_cubrir IS 'A cuantas horas de empezar un turno sin nadie abre un incidente, y cada cuanto se insiste. Solo lo que esta Prestadora corrio; los valores de fabrica y los bordes viven en panel/src/lib/incidenteTurnoSinCubrir.js.';


--
-- Name: configuracion_matricula_via_medicacion; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_matricula_via_medicacion (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    via_administracion text NOT NULL,
    tipo_matricula_requerida text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);


--
-- Name: TABLE configuracion_matricula_via_medicacion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.configuracion_matricula_via_medicacion IS 'Qué matrícula exige cada vía de administración de medicación, por Prestadora. Ejemplo: los inyectables piden matrícula de enfermería.';


--
-- Name: configuracion_mensaje_de_texto_prestadora; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_mensaje_de_texto_prestadora (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    proveedor text,
    remitente text,
    token_secret_id uuid,
    activo boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sin_proveedor_el_mensaje_de_texto_no_se_enciende CHECK (((NOT activo) OR (proveedor IS NOT NULL)))
);


--
-- Name: TABLE configuracion_mensaje_de_texto_prestadora; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.configuracion_mensaje_de_texto_prestadora IS 'Con que proveedor manda mensajes de texto cada Prestadora. Sin fila no hay proveedor y la via no se puede elegir. La credencial vive en Vault; aca solo su puntero.';


--
-- Name: COLUMN configuracion_mensaje_de_texto_prestadora.token_secret_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_mensaje_de_texto_prestadora.token_secret_id IS 'Puntero al secreto de Vault. Nunca la credencial en texto plano, igual que el token de WhatsApp.';


--
-- Name: COLUMN configuracion_mensaje_de_texto_prestadora.activo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_mensaje_de_texto_prestadora.activo IS 'Si la via esta encendida en esta Prestadora. Sin proveedor no puede estar en verdadero.';


--
-- Name: configuracion_notificaciones; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_notificaciones (
    evento text NOT NULL,
    descripcion text NOT NULL,
    emails text[] DEFAULT '{}'::text[] NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    prestadora_id uuid NOT NULL,
    whatsapp_activo boolean DEFAULT false NOT NULL,
    notificar_cliente boolean DEFAULT false NOT NULL,
    plantilla_whatsapp_id uuid,
    mensaje_de_texto_activo boolean DEFAULT false NOT NULL
);


--
-- Name: COLUMN configuracion_notificaciones.descripcion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_notificaciones.descripcion IS 'Texto histórico, en español, de cuando la lista de avisos vivía en esta tabla. El Panel ya no lo muestra: el nombre y la explicación de cada aviso salen traducidos de panel/src/i18n/translations.js, y la lista de avisos que existen es la de backend/src/utils/catalogoAvisos.js. Se conserva como respaldo por si llegara una fila de un aviso que el catálogo no conoce.';


--
-- Name: COLUMN configuracion_notificaciones.plantilla_whatsapp_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_notificaciones.plantilla_whatsapp_id IS 'Con qué plantilla aprobada sale este aviso por WhatsApp. Nulo mientras la Prestadora no eligió ninguna, y entonces el aviso sale por correo.';


--
-- Name: COLUMN configuracion_notificaciones.mensaje_de_texto_activo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_notificaciones.mensaje_de_texto_activo IS 'Si este aviso sale tambien por mensaje de texto. Respaldo de WhatsApp: se intenta despues de WhatsApp y antes del correo. Encenderla no alcanza si la Prestadora no tiene proveedor cargado.';


--
-- Name: configuracion_pago_asistentes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_pago_asistentes (
    prestadora_id uuid NOT NULL,
    regla jsonb DEFAULT '{}'::jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    frecuencia_pago jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT configuracion_pago_asistentes_frecuencia_es_objeto CHECK ((jsonb_typeof(frecuencia_pago) = 'object'::text)),
    CONSTRAINT configuracion_pago_asistentes_regla_es_objeto CHECK ((jsonb_typeof(regla) = 'object'::text))
);


--
-- Name: TABLE configuracion_pago_asistentes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.configuracion_pago_asistentes IS 'Como paga esta Prestadora lo que no depende de una persona sola. Solo lo que corrio respecto de fabrica; los valores de fabrica y los bordes viven en panel/src/lib/formaDePago.js.';


--
-- Name: COLUMN configuracion_pago_asistentes.frecuencia_pago; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_pago_asistentes.frecuencia_pago IS 'Cada cuánto cobran los Asistentes de esta Prestadora. Sólo lo corrido respecto de fábrica; vacío es fábrica.';


--
-- Name: configuracion_plataforma; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_plataforma (
    id boolean DEFAULT true NOT NULL,
    mfa_admin_obligatorio boolean DEFAULT false NOT NULL,
    actualizado_por uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT configuracion_plataforma_id_check CHECK ((id = true))
);


--
-- Name: configuracion_prestadora; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_prestadora (
    prestadora_id uuid NOT NULL,
    nombre text NOT NULL,
    telefono text,
    whatsapp_numero text,
    email text,
    dominio text,
    zona_cobertura_texto text,
    updated_at timestamp with time zone DEFAULT now()
);


--
-- Name: COLUMN configuracion_prestadora.dominio; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_prestadora.dominio IS 'La direccion por la que entra esta Prestadora. Se le asigna sola al darla de alta, es unica y no cambia nunca.';


--
-- Name: configuracion_referencias_laborales; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_referencias_laborales (
    prestadora_id uuid NOT NULL,
    minimo_verificadas smallint DEFAULT 2 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT configuracion_referencias_laborales_minimo_razonable CHECK (((minimo_verificadas >= 0) AND (minimo_verificadas <= 5)))
);


--
-- Name: TABLE configuracion_referencias_laborales; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.configuracion_referencias_laborales IS 'Cuántas referencias laborales verificadas espera cada Prestadora antes de incorporar a un Asistente. Sin fila, no se espera ninguna y no se avisa nada.';


--
-- Name: COLUMN configuracion_referencias_laborales.minimo_verificadas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_referencias_laborales.minimo_verificadas IS 'El tope de cinco es el mismo del formulario de postulación: no se puede exigir más de lo que se puede cargar. En cero, el aviso no aparece nunca.';


--
-- Name: configuracion_visibilidad_app; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_visibilidad_app (
    prestadora_id uuid NOT NULL,
    clave text NOT NULL,
    visible boolean NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE configuracion_visibilidad_app; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.configuracion_visibilidad_app IS 'Qué muestran las aplicaciones del Cliente y del Asistente en cada Prestadora. Solo guarda lo que se cambió respecto del valor de fábrica; la lista de claves posibles vive en backend/src/utils/catalogoVisibilidad.js.';


--
-- Name: COLUMN configuracion_visibilidad_app.clave; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_visibilidad_app.clave IS 'Identificador permanente de la cosa que se prende o se apaga. Nombrado por su función, nunca por la pantalla donde aparece hoy, y no se renombra jamás (CLAUDE.md §7 regla 13).';


--
-- Name: configuracion_whatsapp_prestadora; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.configuracion_whatsapp_prestadora (
    prestadora_id uuid NOT NULL,
    activo boolean DEFAULT false NOT NULL,
    numero_telefono text,
    waba_id text,
    phone_number_id text,
    token_secret_id uuid,
    verificado_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    app_secret_secret_id uuid,
    verify_token_secret_id uuid
);


--
-- Name: COLUMN configuracion_whatsapp_prestadora.app_secret_secret_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_whatsapp_prestadora.app_secret_secret_id IS 'Referencia a vault.secrets con el secreto de la aplicación de Meta, con el que se comprueba la firma X-Hub-Signature-256 de cada aviso entrante. El texto nunca se guarda acá. Pendiente #165.';


--
-- Name: COLUMN configuracion_whatsapp_prestadora.verify_token_secret_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.configuracion_whatsapp_prestadora.verify_token_secret_id IS 'Referencia a vault.secrets con el token que Meta devuelve en el saludo inicial de la dirección de esta Prestadora. Uno por Prestadora, nunca uno solo para todo el producto. El texto nunca se guarda acá. Pendiente #165.';


--
-- Name: consentimientos_asistente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.consentimientos_asistente (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    asistente_id uuid NOT NULL,
    clave text NOT NULL,
    texto_consentimiento_id uuid NOT NULL,
    version_mostrada integer NOT NULL,
    idioma_mostrado text NOT NULL,
    texto_mostrado text NOT NULL,
    decision text NOT NULL,
    decidido_at timestamp with time zone DEFAULT now() NOT NULL,
    retirado_at timestamp with time zone,
    motivo_retiro text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT consentimientos_asistente_decision_check CHECK ((decision = ANY (ARRAY['otorgado'::text, 'rechazado'::text]))),
    CONSTRAINT consentimientos_asistente_retiro_coherente CHECK (((retirado_at IS NULL) OR (decision = 'otorgado'::text)))
);


--
-- Name: consentimientos_paciente_solo; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.consentimientos_paciente_solo (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    guardia_id uuid NOT NULL,
    paciente_id uuid NOT NULL,
    quien_consintio text NOT NULL,
    cliente_id uuid,
    medio text NOT NULL,
    desde_at timestamp with time zone NOT NULL,
    hasta_at timestamp with time zone NOT NULL,
    registrado_por uuid NOT NULL,
    registrado_at timestamp with time zone DEFAULT now() NOT NULL,
    nota text,
    CONSTRAINT consentimientos_paciente_solo_con_nombre CHECK ((length(btrim(quien_consintio)) > 0)),
    CONSTRAINT consentimientos_paciente_solo_medio_conocido CHECK ((medio = ANY (ARRAY['telefono'::text, 'en_persona'::text, 'mensaje'::text, 'correo'::text]))),
    CONSTRAINT consentimientos_paciente_solo_termina_despues CHECK ((hasta_at > desde_at))
);


--
-- Name: TABLE consentimientos_paciente_solo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.consentimientos_paciente_solo IS 'El Cliente supo y acepto que la persona atendida quedara sola durante un rato de este turno. Registra una conversacion que ya ocurrio; no cubre el turno ni lo cierra.';


--
-- Name: COLUMN consentimientos_paciente_solo.quien_consintio; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.consentimientos_paciente_solo.quien_consintio IS 'Nombre de la persona del Cliente con la que se hablo. La cuenta es de todas; quien dijo que si es una.';


--
-- Name: COLUMN consentimientos_paciente_solo.hasta_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.consentimientos_paciente_solo.hasta_at IS 'Hasta cuando vale. Obligatorio: un consentimiento sin fin no es un consentimiento.';


--
-- Name: COLUMN consentimientos_paciente_solo.nota; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.consentimientos_paciente_solo.nota IS 'Lo que quedo de la conversacion. Nunca datos de salud de la persona atendida.';


--
-- Name: consentimientos_pagador; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.consentimientos_pagador (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    cliente_id uuid NOT NULL,
    pagador_legajo_id uuid NOT NULL,
    pagador_nombre text NOT NULL,
    documento_texto text NOT NULL,
    documento_huella text NOT NULL,
    documento_idioma text NOT NULL,
    estado text DEFAULT 'pendiente_firma'::text NOT NULL,
    cerrado_como text,
    cerrado_en timestamp with time zone,
    cerrado_desde text,
    archivo_firmado_url text,
    cargado_por uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    firmante_legajo_id uuid,
    firmante_nombre text,
    CONSTRAINT consentimientos_pagador_cerrado_como_conocido CHECK (((cerrado_como IS NULL) OR (cerrado_como = ANY (ARRAY['papel_firmado'::text, 'confirmado_en_la_app'::text])))),
    CONSTRAINT consentimientos_pagador_cierre_coherente CHECK (((estado = 'cerrado'::text) = ((cerrado_como IS NOT NULL) AND (cerrado_en IS NOT NULL)))),
    CONSTRAINT consentimientos_pagador_con_nombre CHECK ((length(btrim(pagador_nombre)) > 0)),
    CONSTRAINT consentimientos_pagador_estado_conocido CHECK ((estado = ANY (ARRAY['pendiente_firma'::text, 'cerrado'::text, 'anulado'::text]))),
    CONSTRAINT consentimientos_pagador_firmante_entero CHECK ((((firmante_legajo_id IS NULL) AND (firmante_nombre IS NULL)) OR ((firmante_legajo_id IS NOT NULL) AND (length(btrim(firmante_nombre)) > 0))))
);


--
-- Name: TABLE consentimientos_pagador; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.consentimientos_pagador IS 'Que el Pagador asumio la obligacion de pagar esta contratacion, y lo firmo. Sin una fila cerrada no hay Pagador definido.';


--
-- Name: COLUMN consentimientos_pagador.pagador_nombre; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.consentimientos_pagador.pagador_nombre IS 'Como se llamaba el dia que firmo. El Legajo dice con quien quedo atado; esto, que fue lo que leyo.';


--
-- Name: COLUMN consentimientos_pagador.documento_huella; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.consentimientos_pagador.documento_huella IS 'Huella del texto firmado. Si alguien le mueve una coma, deja de coincidir.';


--
-- Name: COLUMN consentimientos_pagador.cerrado_desde; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.consentimientos_pagador.cerrado_desde IS 'Con que aparato se cerro. Nunca la direccion de red ni ningun otro dato que no haga falta.';


--
-- Name: COLUMN consentimientos_pagador.firmante_legajo_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.consentimientos_pagador.firmante_legajo_id IS 'El Apoderado que firmo por la entidad. Nulo cuando quien paga es una persona fisica y firma ella.';


--
-- Name: COLUMN consentimientos_pagador.firmante_nombre; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.consentimientos_pagador.firmante_nombre IS 'Como se llamaba el Apoderado el dia que firmo. Si manana la entidad cambia de apoderado, el papel sigue diciendo quien lo firmo.';


--
-- Name: contactos_vistos_match; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.contactos_vistos_match (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    cliente_id uuid NOT NULL,
    asistente_id uuid NOT NULL,
    acceso_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE contactos_vistos_match; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.contactos_vistos_match IS 'Qué Asistentes tiene ya abiertos un Cliente, y con qué acceso los pagó. Es lo que hace que el saldo del paquete se descuente de a un Asistente y no de a una mirada. docs/PRD_07_Modalidad_Match.md §3.3.';


--
-- Name: contenidos_para_clientes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.contenidos_para_clientes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    titulo text NOT NULL,
    cuerpo text NOT NULL,
    enlace_url text,
    orden integer DEFAULT 0 NOT NULL,
    publicado boolean DEFAULT false NOT NULL,
    creado_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT contenidos_para_clientes_cuerpo_con_texto CHECK ((btrim(cuerpo) <> ''::text)),
    CONSTRAINT contenidos_para_clientes_enlace_es_https CHECK (((enlace_url IS NULL) OR (enlace_url ~ '^https://'::text))),
    CONSTRAINT contenidos_para_clientes_titulo_con_texto CHECK ((btrim(titulo) <> ''::text))
);


--
-- Name: TABLE contenidos_para_clientes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.contenidos_para_clientes IS 'La biblioteca que cada Prestadora escribe para los Clientes de su Organización: contenido y recursos para quien cuida en su casa. Sin siembra de fábrica y sin traducción: lo escribe la Prestadora.';


--
-- Name: COLUMN contenidos_para_clientes.titulo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contenidos_para_clientes.titulo IS 'Título tal como lo escribió la Prestadora. No se traduce.';


--
-- Name: COLUMN contenidos_para_clientes.cuerpo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contenidos_para_clientes.cuerpo IS 'Texto tal como lo escribió la Prestadora. No se traduce.';


--
-- Name: COLUMN contenidos_para_clientes.enlace_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contenidos_para_clientes.enlace_url IS 'Enlace opcional a material que la Prestadora ya publica en otro lado. Siempre https://. Acá no se guardan archivos.';


--
-- Name: COLUMN contenidos_para_clientes.orden; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contenidos_para_clientes.orden IS 'En qué orden se muestran. A igual número, manda la fecha de creación.';


--
-- Name: COLUMN contenidos_para_clientes.publicado; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contenidos_para_clientes.publicado IS 'Si el Cliente lo ve. Lo mueve la Prestadora; sin publicar, la pieza existe solamente para ella.';


--
-- Name: conversaciones_match; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.conversaciones_match (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    cliente_id uuid NOT NULL,
    asistente_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    ultimo_mensaje_at timestamp with time zone,
    sala_videollamada text,
    sala_abierta_at timestamp with time zone
);


--
-- Name: TABLE conversaciones_match; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.conversaciones_match IS 'El hilo entre un Cliente y un Asistente de Match, antes de contratarlo. Una por pareja. El chat es libre; lo que se cobra es el dato de contacto, que viaja tapado hasta que ese contacto se abre.';


--
-- Name: conversaciones_whatsapp; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.conversaciones_whatsapp (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    telefono text NOT NULL,
    asistente_id uuid,
    ultimo_mensaje_at timestamp with time zone DEFAULT now() NOT NULL,
    requiere_atencion_coordinador boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: correcciones_factura_cliente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.correcciones_factura_cliente (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    factura_id uuid NOT NULL,
    sentido text NOT NULL,
    monto numeric(12,2) NOT NULL,
    comprobante_tipo text NOT NULL,
    comprobante_numero text,
    motivo text NOT NULL,
    fecha date DEFAULT CURRENT_DATE NOT NULL,
    registrada_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    moneda public.moneda_iso,
    CONSTRAINT correcciones_factura_cliente_comprobante_tipo_check CHECK ((length(btrim(comprobante_tipo)) > 0)),
    CONSTRAINT correcciones_factura_cliente_monto_check CHECK ((monto > (0)::numeric)),
    CONSTRAINT correcciones_factura_cliente_motivo_check CHECK ((length(btrim(motivo)) > 0)),
    CONSTRAINT correcciones_factura_cliente_sentido_check CHECK ((sentido = ANY (ARRAY['resta'::text, 'suma'::text])))
);


--
-- Name: TABLE correcciones_factura_cliente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.correcciones_factura_cliente IS 'Los comprobantes que corrigen una factura ya emitida. El tipo es texto del software de facturacion y no se interpreta; lo unico que se usa es el sentido y el monto.';


--
-- Name: COLUMN correcciones_factura_cliente.sentido; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.correcciones_factura_cliente.sentido IS 'Que le hace al saldo: resta cuando se facturo de mas, suma cuando se facturo de menos.';


--
-- Name: COLUMN correcciones_factura_cliente.motivo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.correcciones_factura_cliente.motivo IS 'Por que se corrigio. Obligatorio: una correccion sin explicacion no se puede revisar despues.';


--
-- Name: credenciales_pasarela_pago; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.credenciales_pasarela_pago (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    proveedor text NOT NULL,
    credencial_secret_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    secreto_firma_secret_id uuid
);


--
-- Name: COLUMN credenciales_pasarela_pago.secreto_firma_secret_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.credenciales_pasarela_pago.secreto_firma_secret_id IS 'Referencia a vault.secrets con el secreto con el que la pasarela firma sus avisos de cobro. El texto nunca se guarda acá. Pendiente #159.';


--
-- Name: datos_bancarios_asistente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.datos_bancarios_asistente (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    asistente_id uuid NOT NULL,
    pais text NOT NULL,
    identificador_clase text NOT NULL,
    identificador text NOT NULL,
    banco text,
    titular text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT el_identificador_de_la_cuenta_no_esta_vacio CHECK ((length(btrim(identificador)) > 0))
);


--
-- Name: TABLE datos_bancarios_asistente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.datos_bancarios_asistente IS 'Adonde se le paga a cada Asistente. Dato sensible: vive aparte de la ficha porque la proteccion por fila filtra filas y no columnas. No se registra, no viaja en ninguna direccion y no aparece en ningun mensaje de error.';


--
-- Name: COLUMN datos_bancarios_asistente.identificador; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.datos_bancarios_asistente.identificador IS 'El numero con el que se identifica la cuenta. Nunca se muestra en un registro ni en un mensaje.';


--
-- Name: datos_reservados_asistente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.datos_reservados_asistente (
    asistente_id uuid NOT NULL,
    prestadora_id uuid NOT NULL,
    causal_baja text,
    score_riesgo_reclasificacion integer DEFAULT 0 NOT NULL,
    indicadores_riesgo jsonb DEFAULT '{}'::jsonb NOT NULL,
    motivo_exclusion_directo text,
    motivo_exclusion_match text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT datos_reservados_asistente_score_riesgo_reclasificacion_check CHECK (((score_riesgo_reclasificacion >= 0) AND (score_riesgo_reclasificacion <= 100)))
);


--
-- Name: TABLE datos_reservados_asistente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.datos_reservados_asistente IS 'Lo reservado de la ficha del Asistente: por qué se lo dio de baja, su puntaje de riesgo con los motivos que lo forman, y por qué quedó excluido de recibir trabajo. Vive separado de `asistentes` porque las reglas de acceso de la base filtran filas, no columnas: solo en una tabla propia se puede exigir el permiso `ver_datos_reservados_asistente` para leerlo.';


--
-- Name: desafios_de_llave; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.desafios_de_llave (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    desafio text NOT NULL,
    para text NOT NULL,
    rol text NOT NULL,
    prestadora_id uuid,
    usuario_id uuid,
    creado_en timestamp with time zone DEFAULT now() NOT NULL,
    vence_en timestamp with time zone NOT NULL,
    usado_en timestamp with time zone,
    CONSTRAINT desafios_de_llave_el_alta_sabe_de_quien_es CHECK (((para <> 'alta'::text) OR ((prestadora_id IS NOT NULL) AND (usuario_id IS NOT NULL)))),
    CONSTRAINT desafios_de_llave_para_check CHECK ((para = ANY (ARRAY['alta'::text, 'entrada'::text]))),
    CONSTRAINT desafios_de_llave_rol_check CHECK ((rol = ANY (ARRAY['asistente'::text, 'cliente'::text])))
);


--
-- Name: TABLE desafios_de_llave; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.desafios_de_llave IS 'Numeros al azar de un solo uso que el telefono firma para probar que tiene la llave. Vencen a los pocos minutos y quedan marcados al usarse, para que una firma grabada no sirva dos veces.';


--
-- Name: COLUMN desafios_de_llave.para; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.desafios_de_llave.para IS 'Si es para agregar una llave nueva -con la sesion ya abierta- o para entrar.';


--
-- Name: COLUMN desafios_de_llave.prestadora_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.desafios_de_llave.prestadora_id IS 'Queda nulo en los desafios de entrada: ahi todavia no se sabe quien esta entrando. En los de alta es obligatorio, porque la sesion ya lo dice.';


--
-- Name: COLUMN desafios_de_llave.usado_en; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.desafios_de_llave.usado_en IS 'Cuando se gasto. Un desafio usado no vuelve a servir, aunque no haya vencido.';


--
-- Name: descansos_guardia; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.descansos_guardia (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    guardia_id uuid NOT NULL,
    inicio_at timestamp with time zone DEFAULT now() NOT NULL,
    fin_at timestamp with time zone,
    registrado_por uuid NOT NULL,
    nota text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    cliente_uuid uuid,
    cliente_uuid_fin uuid,
    CONSTRAINT descansos_guardia_fin_despues_del_inicio CHECK (((fin_at IS NULL) OR (fin_at > inicio_at)))
);


--
-- Name: TABLE descansos_guardia; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.descansos_guardia IS 'Los ratos de descanso que la Asistente toma adentro de una guardia larga, sin dejar de estar disponible. No se descuenta de lo que se le paga, no interrumpe el turno y no la saca de la guardia: no es una ausencia.';


--
-- Name: COLUMN descansos_guardia.inicio_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.descansos_guardia.inicio_at IS 'Cuando paso, no cuando se pudo enviar. Un aviso guardado en la cola sin conexion conserva el momento del telefono.';


--
-- Name: COLUMN descansos_guardia.fin_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.descansos_guardia.fin_at IS 'En blanco mientras el descanso sigue abierto.';


--
-- Name: COLUMN descansos_guardia.cliente_uuid; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.descansos_guardia.cliente_uuid IS 'El identificador que pone el telefono antes del primer intento, para el que abre el descanso. Dos llegadas con el mismo identificador son el mismo hecho.';


--
-- Name: COLUMN descansos_guardia.cliente_uuid_fin; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.descansos_guardia.cliente_uuid_fin IS 'El identificador del aviso que cerro el descanso. Un reenvio del cierre se reconoce por aca y no vuelve a escribir la hora de fin.';


--
-- Name: direcciones_reservadas; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.direcciones_reservadas (
    direccion text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE direcciones_reservadas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.direcciones_reservadas IS 'Los rotulos que el producto usa para sus propias pantallas bajo su dominio. Ninguna Prestadora puede recibir uno.';


--
-- Name: documentos_asistente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.documentos_asistente (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    asistente_id uuid NOT NULL,
    tipo_documento_id uuid NOT NULL,
    fecha_vencimiento date,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    ruta_archivo text
);


--
-- Name: COLUMN documentos_asistente.ruta_archivo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.documentos_asistente.ruta_archivo IS 'Dónde está el papel dentro del depósito «documentos-asistente». Es la ruta, no un enlace: lo que hay en este depósito se abre sólo con enlace temporal.';


--
-- Name: documentos_pagador; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.documentos_pagador (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    cliente_id uuid NOT NULL,
    tipo_documento_id uuid NOT NULL,
    archivo_url text,
    fecha_vencimiento date,
    cargado_por uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE documentos_pagador; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.documentos_pagador IS 'Los papeles que el financiador exigio para esta contratacion, cargados. Uno por Cliente y por tipo.';


--
-- Name: domicilios_temporales_paciente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.domicilios_temporales_paciente (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    paciente_id uuid NOT NULL,
    domicilio text NOT NULL,
    lat double precision NOT NULL,
    lng double precision NOT NULL,
    motivo text NOT NULL,
    fecha_inicio date NOT NULL,
    fecha_fin date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    calle text,
    numero text,
    piso text,
    unidad text,
    lugar_id uuid,
    CONSTRAINT domicilios_temp_fechas_coherentes CHECK (((fecha_fin IS NULL) OR (fecha_fin >= fecha_inicio)))
);


--
-- Name: COLUMN domicilios_temporales_paciente.lugar_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.domicilios_temporales_paciente.lugar_id IS 'La localidad o el barrio donde esta el Paciente mientras dura el domicilio temporal.';


--
-- Name: dominios_de_correo_gratuitos; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.dominios_de_correo_gratuitos (
    dominio text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE dominios_de_correo_gratuitos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.dominios_de_correo_gratuitos IS 'Catálogo de plataforma: dominios de casillas gratuitas. Lo usa el alta de una Prestadora para distinguir una dirección de empresa de una personal, y así saber de dónde sacar el nombre de su casilla de envío. Se amplía agregando filas, nunca tocando código.';


--
-- Name: emergencias_guardia; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.emergencias_guardia (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    guardia_id uuid NOT NULL,
    reportado_por uuid NOT NULL,
    reportado_at timestamp with time zone DEFAULT now() NOT NULL,
    detalle text NOT NULL,
    atendida_at timestamp with time zone,
    atendida_por uuid,
    atendida_nota text,
    ultima_notificacion_at timestamp with time zone,
    veces_notificado integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    cliente_uuid uuid,
    CONSTRAINT emergencias_guardia_detalle_check CHECK ((length(btrim(detalle)) > 0))
);


--
-- Name: TABLE emergencias_guardia; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.emergencias_guardia IS 'Lo que el Asistente avisa desde la Guardia Activa cuando pasa algo que no admite esperar. No es la revision automatica de reportes ni la alerta de guardia sin cubrir: es un aviso de una persona, en el momento, que alguien tiene que atender.';


--
-- Name: COLUMN emergencias_guardia.reportado_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.emergencias_guardia.reportado_at IS 'Cuando paso, no cuando se pudo enviar. Un aviso guardado en la cola sin conexion conserva el momento del telefono.';


--
-- Name: COLUMN emergencias_guardia.detalle; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.emergencias_guardia.detalle IS 'Texto libre escrito por quien esta ahi. Es informacion sensible: no viaja en el aviso que sale por WhatsApp ni por correo, se lee entrando al Panel.';


--
-- Name: COLUMN emergencias_guardia.cliente_uuid; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.emergencias_guardia.cliente_uuid IS 'El identificador que pone el telefono antes del primer intento. Dos llegadas con el mismo identificador son el mismo hecho: la segunda no escribe nada.';


--
-- Name: entrevistas_postulacion; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.entrevistas_postulacion (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    postulacion_id bigint NOT NULL,
    agendada_para timestamp with time zone NOT NULL,
    llave_publica text NOT NULL,
    sala_videollamada text,
    estado text DEFAULT 'agendada'::text NOT NULL,
    agendada_por uuid NOT NULL,
    cerrada_por uuid,
    cerrada_at timestamp with time zone,
    observaciones text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT entrevistas_postulacion_estado_check CHECK ((estado = ANY (ARRAY['agendada'::text, 'realizada'::text, 'no_asistio'::text, 'cancelada'::text]))),
    CONSTRAINT entrevistas_postulacion_llave_publica_check CHECK ((length(llave_publica) >= 32))
);


--
-- Name: TABLE entrevistas_postulacion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.entrevistas_postulacion IS 'La entrevista de la etapa 3 del Proceso de Incorporacion de Asistentes. Guarda cuando es, quien la agendo, como salio y la sala donde se hizo. El postulante entra con una llave, porque todavia no tiene cuenta.';


--
-- Name: COLUMN entrevistas_postulacion.llave_publica; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.entrevistas_postulacion.llave_publica IS 'Lo que el postulante recibe por correo. No es la direccion de la sala: es una direccion del producto, que comprueba que sea la hora antes de dejar entrar.';


--
-- Name: envios_de_correo; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.envios_de_correo (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid,
    aceptado boolean NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE envios_de_correo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.envios_de_correo IS 'Un renglón por correo despachado, para contar contra el tope del despachante. No guarda destinatario, asunto ni contenido: para contar no hacen falta, y un registro no lleva información sensible adentro.';


--
-- Name: COLUMN envios_de_correo.prestadora_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.envios_de_correo.prestadora_id IS 'De qué Prestadora era el correo. Vacío cuando el envío no sale de ninguna en particular, como la recuperación de una cuenta. Si la Prestadora se borra, el renglón queda: la cuenta del mes ya pasó.';


--
-- Name: COLUMN envios_de_correo.aceptado; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.envios_de_correo.aceptado IS 'Si el despachante lo tomó. Falso es un correo que no salió, y muchos seguidos son la señal de que se llegó al tope.';


--
-- Name: equipo_paciente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.equipo_paciente (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    paciente_id uuid NOT NULL,
    asistente_id uuid,
    usuario_id uuid,
    situacion text NOT NULL,
    cubre_francos boolean DEFAULT false NOT NULL,
    motivo text,
    decidido_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT equipo_paciente_es_una_persona_o_la_otra CHECK ((num_nonnulls(asistente_id, usuario_id) = 1)),
    CONSTRAINT equipo_paciente_sacada_no_cubre_francos CHECK ((NOT ((situacion = 'sacada'::text) AND cubre_francos))),
    CONSTRAINT equipo_paciente_situacion_conocida CHECK ((situacion = ANY (ARRAY['sumada'::text, 'sacada'::text])))
);


--
-- Name: TABLE equipo_paciente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.equipo_paciente IS 'Las correcciones a mano sobre el equipo de un Paciente: a quien se sumo, a quien se saco y quien cubre francos. La lista entera no se guarda: se deduce de las guardias y las series, y estas filas la corrigen. La regla vive en panel/src/lib/equipoDelPaciente.js.';


--
-- Name: COLUMN equipo_paciente.situacion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.equipo_paciente.situacion IS 'sumada = entra aunque no llegue sola. sacada = queda afuera aunque llegue. Identificadores permanentes.';


--
-- Name: COLUMN equipo_paciente.cubre_francos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.equipo_paciente.cubre_francos IS 'Cubre los francos de las demas. Es a quien se llama primero cuando alguien falta.';


--
-- Name: equipos_conocidos; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.equipos_conocidos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    usuario_id uuid NOT NULL,
    marca_huella text NOT NULL,
    primera_entrada_en timestamp with time zone DEFAULT now() NOT NULL,
    ultima_entrada_en timestamp with time zone DEFAULT now() NOT NULL,
    revocado_en timestamp with time zone
);


--
-- Name: TABLE equipos_conocidos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.equipos_conocidos IS 'Los aparatos desde los que esta persona ya entró. Guarda la huella de una marca que emitió el motor y que el navegador conserva, nunca nada del aparato ni de dónde se conecta.';


--
-- Name: escalas_legales; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.escalas_legales (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tipo text NOT NULL,
    categoria text,
    valor numeric(14,4) NOT NULL,
    unidad text NOT NULL,
    vigencia_desde date NOT NULL,
    vigencia_hasta date,
    fuente text,
    cargado_por uuid,
    created_at timestamp with time zone DEFAULT now(),
    jurisdiccion text NOT NULL,
    moneda public.moneda_iso,
    CONSTRAINT escalas_legales_moneda_cuando_es_plata CHECK (((unidad = ANY (ARRAY['monto_fijo_mensual'::text, 'monto_por_hora'::text])) = (moneda IS NOT NULL))),
    CONSTRAINT escalas_legales_unidad_check CHECK ((unidad = ANY (ARRAY['monto_fijo_mensual'::text, 'porcentaje'::text, 'dias'::text, 'meses'::text, 'horas'::text, 'anios'::text, 'monto_por_hora'::text])))
);


--
-- Name: escalones_de_alarma_avisados; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.escalones_de_alarma_avisados (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    tipo text NOT NULL,
    referencia_id uuid NOT NULL,
    escalon text NOT NULL,
    avisado_at timestamp with time zone DEFAULT now() NOT NULL,
    destinatarios integer DEFAULT 0 NOT NULL,
    CONSTRAINT escalones_de_alarma_avisados_escalon_conocido CHECK ((escalon = ANY (ARRAY['coordinador_respaldo'::text, 'todos_los_coordinadores'::text, 'administracion'::text]))),
    CONSTRAINT escalones_de_alarma_avisados_tipo_conocido CHECK ((tipo = ANY (ARRAY['alerta_temprana_guardia'::text, 'incidente_relevo'::text, 'guardia_sin_cerrar'::text, 'incidente_turno_sin_cubrir'::text, 'emergencia_guardia'::text])))
);


--
-- Name: TABLE escalones_de_alarma_avisados; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.escalones_de_alarma_avisados IS 'Que escalon de la escalada ya salio para cada alarma. Escalar no es volver a insistir: es ampliar quien se entera, y eso pasa una sola vez por escalon.';


--
-- Name: COLUMN escalones_de_alarma_avisados.referencia_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.escalones_de_alarma_avisados.referencia_id IS 'La fila alarmada. La tabla a la que apunta depende del tipo: no hay clave foranea posible.';


--
-- Name: COLUMN escalones_de_alarma_avisados.destinatarios; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.escalones_de_alarma_avisados.destinatarios IS 'A cuanta gente le salio. Cero es un problema de configuracion, no del aviso.';


--
-- Name: estados_de_cuenta_externos; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.estados_de_cuenta_externos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    cliente_id uuid NOT NULL,
    saldo numeric(14,2) NOT NULL,
    moneda text NOT NULL,
    atrasado boolean NOT NULL,
    dias_de_atraso integer,
    vencimiento_mas_antiguo date,
    fecha_del_estado date,
    numero_del_aviso text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT estados_de_cuenta_externos_atraso_no_negativo CHECK (((dias_de_atraso IS NULL) OR (dias_de_atraso >= 0))),
    CONSTRAINT estados_de_cuenta_externos_moneda_con_forma CHECK ((moneda ~ '^[A-Z]{3}$'::text))
);


--
-- Name: TABLE estados_de_cuenta_externos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.estados_de_cuenta_externos IS 'Lo que el software de creditos y cobranzas de la Prestadora informo sobre la cuenta de un Cliente. Informacion, no decision: nada se corta ni se bloquea por esto, y este sistema no lo recalcula.';


--
-- Name: COLUMN estados_de_cuenta_externos.saldo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.estados_de_cuenta_externos.saldo IS 'Cuanto debe ese Cliente segun quien lleva la cobranza. Negativo es saldo a favor. No se calcula aca: se guarda tal como llego.';


--
-- Name: COLUMN estados_de_cuenta_externos.moneda; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.estados_de_cuenta_externos.moneda IS 'En que moneda esta el saldo, en codigo de tres letras. Todo importe viaja con su moneda.';


--
-- Name: COLUMN estados_de_cuenta_externos.atrasado; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.estados_de_cuenta_externos.atrasado IS 'Si quien lleva la cobranza considera que ese Cliente esta atrasado. Lo decide el, no este sistema.';


--
-- Name: COLUMN estados_de_cuenta_externos.dias_de_atraso; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.estados_de_cuenta_externos.dias_de_atraso IS 'Cuantos dias de atraso informo quien avisa. Vacio cuando no lo informa: no se deduce de ninguna fecha.';


--
-- Name: COLUMN estados_de_cuenta_externos.vencimiento_mas_antiguo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.estados_de_cuenta_externos.vencimiento_mas_antiguo IS 'La fecha de vencimiento mas vieja que sigue impaga, si quien avisa la informa.';


--
-- Name: COLUMN estados_de_cuenta_externos.fecha_del_estado; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.estados_de_cuenta_externos.fecha_del_estado IS 'A que dia corresponde esta foto de la cuenta. Es de quien avisa, no de cuando entro el aviso.';


--
-- Name: COLUMN estados_de_cuenta_externos.numero_del_aviso; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.estados_de_cuenta_externos.numero_del_aviso IS 'Como numero el aviso quien lo mando. Sirve para no atender dos veces el mismo.';


--
-- Name: estado_de_cuenta_externo_vigente; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.estado_de_cuenta_externo_vigente WITH (security_invoker='true') AS
 SELECT DISTINCT ON (cliente_id) cliente_id,
    prestadora_id,
    saldo,
    moneda,
    atrasado,
    dias_de_atraso,
    vencimiento_mas_antiguo,
    fecha_del_estado,
    numero_del_aviso,
    created_at AS informado_at
   FROM public.estados_de_cuenta_externos e
  ORDER BY cliente_id, created_at DESC;


--
-- Name: VIEW estado_de_cuenta_externo_vigente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.estado_de_cuenta_externo_vigente IS 'El ultimo estado de cuenta informado de cada Cliente, que es el que rige. Los anteriores quedan guardados en estados_de_cuenta_externos.';


--
-- Name: matriculas_asistente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.matriculas_asistente (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    asistente_id uuid NOT NULL,
    tipo text NOT NULL,
    numero_matricula text,
    vigente_desde date NOT NULL,
    vigente_hasta date,
    archivo_url text,
    registrado_por uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    verificada_at timestamp with time zone,
    verificada_por uuid,
    metodo_verificacion text,
    nota_verificacion text,
    cargada_por_el_asistente boolean DEFAULT false NOT NULL,
    prestadora_id uuid NOT NULL,
    CONSTRAINT matriculas_asistente_metodo_verificacion_valido CHECK (((metodo_verificacion IS NULL) OR (metodo_verificacion = ANY (ARRAY['documento_a_la_vista'::text, 'constancia_del_organismo'::text, 'registro_oficial_en_linea'::text])))),
    CONSTRAINT matriculas_asistente_verificacion_completa CHECK ((((verificada_at IS NULL) AND (verificada_por IS NULL) AND (metodo_verificacion IS NULL)) OR ((verificada_at IS NOT NULL) AND (verificada_por IS NOT NULL) AND (metodo_verificacion IS NOT NULL))))
);


--
-- Name: TABLE matriculas_asistente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.matriculas_asistente IS 'El papel que autoriza legalmente a un Asistente a ejercer: número, vigencia y archivo. No guarda tareas ni tipo de Asistente — son otras tres cosas.';


--
-- Name: COLUMN matriculas_asistente.verificada_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.matriculas_asistente.verificada_at IS 'Cuándo se verificó. Mientras esté vacía, la matrícula está cargada pero no aprobada, y el Asistente sigue bloqueado.';


--
-- Name: COLUMN matriculas_asistente.verificada_por; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.matriculas_asistente.verificada_por IS 'Quién la verificó. Es una persona con nombre, no "el sistema": si mañana se descubre que una matrícula no era válida, tiene que saberse quién la dio por buena.';


--
-- Name: COLUMN matriculas_asistente.metodo_verificacion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.matriculas_asistente.metodo_verificacion IS 'Por qué medio se verificó. Existe por el pendiente #107: si la ley termina exigiendo comprobación contra el registro oficial, esta columna dice cuáles hay que volver a mirar.';


--
-- Name: COLUMN matriculas_asistente.nota_verificacion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.matriculas_asistente.nota_verificacion IS 'Aclaración libre de quien verificó. Para el caso raro que no entra en ninguna de las tres formas.';


--
-- Name: COLUMN matriculas_asistente.cargada_por_el_asistente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.matriculas_asistente.cargada_por_el_asistente IS 'Verdadero si la subió el propio Asistente desde su aplicación. Esas siempre necesitan verificación, aunque la Prestadora esté en modo flexible: el interesado no se aprueba a sí mismo.';


--
-- Name: COLUMN matriculas_asistente.prestadora_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.matriculas_asistente.prestadora_id IS 'La Prestadora de la Matrícula. No puede diferir de la de su Asistente: la clave foránea va compuesta contra asistentes (id, prestadora_id).';


--
-- Name: prestadoras; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.prestadoras (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    razon_social text NOT NULL,
    nombre_fantasia text NOT NULL,
    identificacion_fiscal text,
    pais text DEFAULT 'AR'::text NOT NULL,
    estado public.estado_prestadora DEFAULT 'prospecto'::public.estado_prestadora NOT NULL,
    zonas_operacion text[],
    fecha_alta date,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    dias_aviso_vencimiento_documentos smallint DEFAULT 30 NOT NULL,
    dias_generacion_series_guardia smallint DEFAULT 90 NOT NULL,
    politica_verificacion_alta_manual text DEFAULT 'omitir'::text NOT NULL,
    modo_control_matricula text DEFAULT 'estricto'::text NOT NULL,
    logo_url text,
    minutos_aviso_previo_guardia integer DEFAULT 60 NOT NULL,
    moneda public.moneda_iso NOT NULL,
    videollamada_base_url text,
    casilla_envio text,
    regla_reenvio text,
    CONSTRAINT prestadoras_minutos_aviso_previo_guardia_check CHECK (((minutos_aviso_previo_guardia >= 5) AND (minutos_aviso_previo_guardia <= 1440))),
    CONSTRAINT prestadoras_modo_control_matricula_check CHECK ((modo_control_matricula = ANY (ARRAY['estricto'::text, 'flexible'::text]))),
    CONSTRAINT prestadoras_politica_verificacion_alta_manual_check CHECK ((politica_verificacion_alta_manual = ANY (ARRAY['omitir'::text, 'pendiente'::text, 'aprobado'::text])))
);


--
-- Name: COLUMN prestadoras.modo_control_matricula; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.prestadoras.modo_control_matricula IS 'Si para trabajar hace falta que la matrícula esté verificada (estricto) o alcanza con que esté cargada y vigente (flexible). Lo lee una sola función: motivo_bloqueo_matricula().';


--
-- Name: COLUMN prestadoras.logo_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.prestadoras.logo_url IS 'Dirección del logo de la Prestadora, la marca que ven el Cliente y el Asistente. Vacío significa que todavía no lo subió: en ese caso las pantallas muestran nombre_fantasia escrito. Los archivos viven en el depósito marca-prestadoras, en la carpeta de esa Prestadora.';


--
-- Name: COLUMN prestadoras.minutos_aviso_previo_guardia; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.prestadoras.minutos_aviso_previo_guardia IS 'Cuántos minutos antes de que empiece la guardia se le manda el recordatorio al Asistente. De fábrica, 60. El tope es un día entero; menos de cinco minutos no llegaría a tiempo de servir para nada.';


--
-- Name: COLUMN prestadoras.moneda; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.prestadoras.moneda IS 'Moneda en la que esta Prestadora carga sus precios y cobra. Nace del país configurado y se cambia desde Configuración.';


--
-- Name: COLUMN prestadoras.videollamada_base_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.prestadoras.videollamada_base_url IS 'Direccion base de las salas de videollamada de esta Prestadora, sin barra final. El producto le agrega el nombre de sala. Vacia: esta Prestadora no ofrece videollamada y el boton no aparece. No lleva ninguna credencial.';


--
-- Name: COLUMN prestadoras.casilla_envio; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.prestadoras.casilla_envio IS 'Nombre de la casilla desde la que esta Prestadora manda sus avisos, sin el dominio. Se fija al darla de alta y no cambia: es la dirección que la gente ya tiene en su buzón. El dominio lo pone el motor.';


--
-- Name: COLUMN prestadoras.regla_reenvio; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.prestadoras.regla_reenvio IS 'Identificador del reenvío de las respuestas de esta Prestadora, tal como lo da el servicio de correo. Se abre al darla de alta y se corta cuando se va. Vacío: no hay reenvío y las respuestas se pierden.';


--
-- Name: tipos_asistente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tipos_asistente (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid,
    clave text,
    nombre text,
    descripcion text,
    requiere_matricula boolean DEFAULT false NOT NULL,
    tipo_matricula text,
    activo boolean DEFAULT true NOT NULL,
    orden integer DEFAULT 100 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tipos_asistente_matricula_con_tipo CHECK (((requiere_matricula = false) OR (tipo_matricula IS NOT NULL))),
    CONSTRAINT tipos_asistente_nombre_segun_nivel CHECK ((((prestadora_id IS NULL) AND (clave IS NOT NULL) AND (nombre IS NULL)) OR ((prestadora_id IS NOT NULL) AND (clave IS NULL) AND (nombre IS NOT NULL))))
);


--
-- Name: TABLE tipos_asistente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tipos_asistente IS 'Qué ES un Asistente: cuidador/a, enfermero/a, kinesiólogo/a, médico/a y los que agregue cada Prestadora. Distinto de sus Tareas (qué hace) y de su Matrícula (qué lo autoriza).';


--
-- Name: COLUMN tipos_asistente.prestadora_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tipos_asistente.prestadora_id IS 'NULL = tipo general de CeltaTech, lo ven todas las Prestadoras y ninguna lo puede tocar. Con dato = lo creó esa Prestadora y solo lo ve ella.';


--
-- Name: COLUMN tipos_asistente.clave; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tipos_asistente.clave IS 'Solo para los tipos generales. El nombre visible sale de los archivos de traducción, buscándolo por esta clave, para que el Panel en inglés no muestre "enfermero".';


--
-- Name: COLUMN tipos_asistente.nombre; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tipos_asistente.nombre IS 'Solo para los tipos que crea una Prestadora. Es información suya, escrita por ella, y no se traduce.';


--
-- Name: COLUMN tipos_asistente.requiere_matricula; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tipos_asistente.requiere_matricula IS 'Si está en verdadero, un Asistente de este tipo sin matrícula cargada, vigente y verificada no puede atender a ningún Paciente.';


--
-- Name: COLUMN tipos_asistente.tipo_matricula; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tipos_asistente.tipo_matricula IS 'Qué matrícula exige. Se compara contra matriculas_asistente.tipo y contra configuracion_matricula_via_medicacion.tipo_matricula_requerida — los tres tienen que hablar el mismo idioma o la regla no engancha.';


--
-- Name: estado_matricula_asistente; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.estado_matricula_asistente WITH (security_invoker='true') AS
 SELECT a.id AS asistente_id,
    a.prestadora_id,
    a.nombre,
    a.tipo_asistente_id,
    t.requiere_matricula,
    t.tipo_matricula,
    p.modo_control_matricula,
    interno.motivo_bloqueo_matricula(a.id) AS motivo_bloqueo,
    m.id AS matricula_id,
    m.vigente_hasta,
    m.verificada_at,
        CASE
            WHEN (m.vigente_hasta IS NULL) THEN NULL::integer
            ELSE (m.vigente_hasta - CURRENT_DATE)
        END AS dias_para_vencer
   FROM (((public.asistentes a
     JOIN public.prestadoras p ON ((p.id = a.prestadora_id)))
     LEFT JOIN public.tipos_asistente t ON ((t.id = a.tipo_asistente_id)))
     LEFT JOIN LATERAL ( SELECT mm.id,
            mm.asistente_id,
            mm.tipo,
            mm.numero_matricula,
            mm.vigente_desde,
            mm.vigente_hasta,
            mm.archivo_url,
            mm.registrado_por,
            mm.created_at,
            mm.verificada_at,
            mm.verificada_por,
            mm.metodo_verificacion,
            mm.nota_verificacion
           FROM public.matriculas_asistente mm
          WHERE ((mm.asistente_id = a.id) AND (mm.prestadora_id = a.prestadora_id) AND (mm.tipo = t.tipo_matricula) AND ((mm.vigente_desde IS NULL) OR (mm.vigente_desde <= CURRENT_DATE)))
          ORDER BY (mm.vigente_hasta IS NULL) DESC, mm.vigente_hasta DESC
         LIMIT 1) m ON (true))
  WHERE (a.deleted_at IS NULL);


--
-- Name: VIEW estado_matricula_asistente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.estado_matricula_asistente IS 'Cómo está la matrícula de cada Asistente, ya resuelta: si le hace falta, si está bloqueado hoy y por qué, cuándo vence, cuántos días faltan y si su Prestadora exige verificación. La consultan el Estado actual de la Prestadora, el panel para cubrir una vacante y la aplicación del Asistente, para que ninguno vuelva a escribir la regla por su cuenta.';


--
