    codigo_expira_en timestamp with time zone,
    codigo_intentos integer DEFAULT 0 NOT NULL,
    codigo_emitido_por uuid,
    codigo_emitido_en timestamp with time zone,
    motivo_sin_comprobar text,
    motivo_detalle text,
    cerrada_en timestamp with time zone,
    cerrada_por uuid,
    cerrada_nota text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT guardia_comprobaciones_cierre_check CHECK ((((cerrada_en IS NULL) AND (cerrada_por IS NULL)) OR ((cerrada_en IS NOT NULL) AND (cerrada_por IS NOT NULL)))),
    CONSTRAINT guardia_comprobaciones_coherencia_check CHECK ((((estado = 'comprobada'::text) AND (medio IS NOT NULL) AND (comprobada_en IS NOT NULL) AND (motivo_sin_comprobar IS NULL)) OR ((estado = 'sin_comprobar'::text) AND (motivo_sin_comprobar IS NOT NULL) AND (medio IS NULL)) OR ((estado = 'pendiente_de_codigo'::text) AND (medio IS NULL) AND (motivo_sin_comprobar IS NULL) AND (pedido_en IS NOT NULL)))),
    CONSTRAINT guardia_comprobaciones_estado_check CHECK ((estado = ANY (ARRAY['pendiente_de_codigo'::text, 'comprobada'::text, 'sin_comprobar'::text]))),
    CONSTRAINT guardia_comprobaciones_medio_check CHECK (((medio IS NULL) OR (medio = ANY (ARRAY['codigo_cliente'::text, 'codigo_asistente_saliente'::text, 'codigo_prestadora'::text])))),
    CONSTRAINT guardia_comprobaciones_momento_check CHECK ((momento = ANY (ARRAY['checkin'::text, 'checkout'::text]))),
    CONSTRAINT guardia_comprobaciones_motivo_check CHECK (((motivo_sin_comprobar IS NULL) OR (motivo_sin_comprobar = ANY (ARRAY['nadie_para_mostrar'::text, 'prestadora_no_responde'::text, 'sin_camara'::text, 'sin_conexion'::text, 'otro'::text])))),
    CONSTRAINT guardia_comprobaciones_sujeto_coherencia_check CHECK ((((medio = ANY (ARRAY['codigo_cliente'::text, 'codigo_asistente_saliente'::text])) AND (sujeto_tipo IS NOT NULL) AND (sujeto_id IS NOT NULL)) OR ((medio = 'codigo_prestadora'::text) AND (sujeto_tipo IS NULL) AND (sujeto_id IS NULL)) OR (medio IS NULL))),
    CONSTRAINT guardia_comprobaciones_sujeto_tipo_check CHECK (((sujeto_tipo IS NULL) OR (sujeto_tipo = ANY (ARRAY['cliente'::text, 'asistente'::text]))))
);


--
-- Name: TABLE guardia_comprobaciones; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.guardia_comprobaciones IS 'Cómo se comprobó que el Asistente estaba realmente en el domicilio al llegar y al irse (pendiente #113). Una fila por acto: cuando hay relevo, la guardia que termina y la que empieza tienen cada una la suya.';


--
-- Name: COLUMN guardia_comprobaciones.estado; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardia_comprobaciones.estado IS 'comprobada (alguien mostró el código, o lo soltó la Prestadora), pendiente_de_codigo (el Asistente avisó que no hay quién se lo muestre y espera), sin_comprobar (se entró igual, con un motivo, y el Coordinador lo tiene que cerrar).';


--
-- Name: COLUMN guardia_comprobaciones.medio; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardia_comprobaciones.medio IS 'Con qué se comprobó: el código del Cliente, el del Asistente que se iba, o el que soltó la Prestadora. Es lo que decide si al Cliente se le avisa: se le avisa cuando él no participó de la comprobación.';


--
-- Name: COLUMN guardia_comprobaciones.pedido_texto; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardia_comprobaciones.pedido_texto IS 'Lo que el Asistente escribió con sus palabras al avisar que no tiene a quién pedirle el código. Aparece tal cual en la pantalla de la Prestadora.';


--
-- Name: COLUMN guardia_comprobaciones.codigo_huella; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardia_comprobaciones.codigo_huella IS 'sha256 del código de un solo uso que soltó la Prestadora. El código en claro se muestra una vez a quien lo emitió y no se guarda.';


--
-- Name: COLUMN guardia_comprobaciones.codigo_intentos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardia_comprobaciones.codigo_intentos IS 'Cuántas veces se probó un código contra esta llegada o esta salida. Es la cuenta del acto, no la del código: soltar un código nuevo no la vuelve a cero. Agotada, queda el piso de siempre: se entra igual eligiendo un motivo.';


--
-- Name: COLUMN guardia_comprobaciones.motivo_sin_comprobar; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardia_comprobaciones.motivo_sin_comprobar IS 'Por qué se entró sin comprobar. La guardia nunca se traba: si en la Prestadora no atiende nadie, el Asistente elige un motivo, entra a trabajar, y esto queda en la lista del Coordinador.';


--
-- Name: guardia_pacientes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.guardia_pacientes (
    guardia_id uuid NOT NULL,
    paciente_id uuid NOT NULL,
    prestadora_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE guardia_pacientes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.guardia_pacientes IS 'A quiénes atiende una guardia. Una fila por Paciente. Una guardia puede tener varias: un matrimonio en su casa, o todo un piso de un asilo.';


--
-- Name: guardias; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.guardias (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    asistente_id uuid,
    paciente_id uuid NOT NULL,
    serie_id uuid,
    coordinador_id uuid,
    fecha date NOT NULL,
    hora_inicio time without time zone NOT NULL,
    hora_fin time without time zone NOT NULL,
    modalidad text NOT NULL,
    estado text DEFAULT 'programada'::text NOT NULL,
    cancelacion_origen text,
    cancelacion_alcance text,
    salida_checkin_at timestamp with time zone,
    salida_lat double precision,
    salida_lng double precision,
    medio_transporte text,
    checkin_at timestamp with time zone,
    checkin_lat double precision,
    checkin_lng double precision,
    checkout_at timestamp with time zone,
    checkout_lat double precision,
    checkout_lng double precision,
    checkout_bloqueado boolean DEFAULT false NOT NULL,
    checkout_excepcion_motivo text,
    checkout_excepcion_autorizado_por uuid,
    checkout_excepcion_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    push_asignacion_enviado_at timestamp with time zone,
    push_recordatorio_enviado_at timestamp with time zone,
    ubicacion_actual_lat double precision,
    ubicacion_actual_lng double precision,
    ubicacion_actual_at timestamp with time zone,
    push_llegada_enviado_at timestamp with time zone,
    push_reporte_enviado_at timestamp with time zone,
    servicio_id uuid,
    canal_modalidad text DEFAULT 'directa'::text NOT NULL,
    ofrecida_at timestamp with time zone,
    ofrecida_por uuid,
    oferta_limite_at timestamp with time zone,
    aviso_sin_cubrir_at timestamp with time zone,
    aviso_sin_cubrir_veces smallint DEFAULT 0 NOT NULL,
    cerrada_at timestamp with time zone,
    cerrada_por uuid,
    cerrada_origen text,
    cerrada_motivo text,
    aviso_sin_cerrar_at timestamp with time zone,
    aviso_sin_cerrar_veces smallint,
    aviso_sin_cerrar_backup_at timestamp with time zone,
    aviso_sin_cerrar_grave_at timestamp with time zone,
    dias_hasta_el_fin smallint DEFAULT 0 NOT NULL,
    horas_extra numeric(5,2) DEFAULT 0 NOT NULL,
    horas_extra_motivo text,
    CONSTRAINT guardias_canal_modalidad_check CHECK ((canal_modalidad = ANY (ARRAY['directa'::text, 'match'::text, 'subcontratacion'::text]))),
    CONSTRAINT guardias_cancelacion_alcance_check CHECK ((cancelacion_alcance = ANY (ARRAY['parcial'::text, 'total'::text]))),
    CONSTRAINT guardias_cancelacion_check CHECK (((estado = 'cancelada'::text) OR ((cancelacion_origen IS NULL) AND (cancelacion_alcance IS NULL)))),
    CONSTRAINT guardias_cancelacion_origen_check CHECK ((cancelacion_origen = ANY (ARRAY['cliente'::text, 'prestadora'::text]))),
    CONSTRAINT guardias_cerrada_origen_check CHECK ((cerrada_origen = ANY (ARRAY['asistente'::text, 'panel'::text]))),
    CONSTRAINT guardias_checkout_bloqueado_requiere_excepcion CHECK (((checkout_at IS NULL) OR (NOT checkout_bloqueado) OR ((checkout_excepcion_motivo IS NOT NULL) AND (checkout_excepcion_autorizado_por IS NOT NULL) AND (checkout_excepcion_at IS NOT NULL)))),
    CONSTRAINT guardias_cierre_por_el_asistente_sin_motivo CHECK (((cerrada_origen IS DISTINCT FROM 'asistente'::text) OR (cerrada_motivo IS NULL))),
    CONSTRAINT guardias_cierre_por_el_panel_exige_persona_y_motivo CHECK (((cerrada_origen IS DISTINCT FROM 'panel'::text) OR ((cerrada_por IS NOT NULL) AND (cerrada_motivo IS NOT NULL) AND (btrim(cerrada_motivo) <> ''::text)))),
    CONSTRAINT guardias_cierre_rastro_completo CHECK ((((cerrada_at IS NULL) AND (cerrada_origen IS NULL) AND (cerrada_por IS NULL) AND (cerrada_motivo IS NULL)) OR ((cerrada_at IS NOT NULL) AND (cerrada_origen IS NOT NULL)))),
    CONSTRAINT guardias_dias_hasta_el_fin_valido CHECK (((dias_hasta_el_fin >= 0) AND (dias_hasta_el_fin <= 3))),
    CONSTRAINT guardias_estado_check CHECK ((estado = ANY (ARRAY['programada'::text, 'activa'::text, 'completada'::text, 'cancelada'::text, 'ausente'::text, 'pausada'::text]))),
    CONSTRAINT guardias_horas_extra_con_motivo CHECK (((horas_extra = (0)::numeric) OR ((horas_extra_motivo IS NOT NULL) AND (btrim(horas_extra_motivo) <> ''::text)))),
    CONSTRAINT guardias_horas_extra_no_negativas CHECK ((horas_extra >= (0)::numeric)),
    CONSTRAINT guardias_limite_solo_si_ofrecida_check CHECK (((oferta_limite_at IS NULL) OR (ofrecida_at IS NOT NULL))),
    CONSTRAINT guardias_ofrecida_solo_sin_cubrir_check CHECK (((ofrecida_at IS NULL) OR (asistente_id IS NULL))),
    CONSTRAINT guardias_sin_cubrir_estado_check CHECK (((asistente_id IS NOT NULL) OR (estado = ANY (ARRAY['programada'::text, 'cancelada'::text])))),
    CONSTRAINT guardias_sin_cubrir_sin_marcas_check CHECK (((asistente_id IS NOT NULL) OR ((checkin_at IS NULL) AND (checkout_at IS NULL) AND (salida_checkin_at IS NULL))))
);


--
-- Name: COLUMN guardias.asistente_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardias.asistente_id IS 'NULL = guardia sin cubrir. Es un estado normal y esperado, no un dato faltante.';


--
-- Name: COLUMN guardias.paciente_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardias.paciente_id IS 'EN RETIRO. Guarda a uno solo de los Pacientes de la guardia, el primero. La lista completa vive en guardia_pacientes. Sigue acá únicamente para que las pantallas todavía sin actualizar no se rompan; se elimina cuando ninguna la lea.';


--
-- Name: COLUMN guardias.ofrecida_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardias.ofrecida_at IS 'Fecha en que la guardia se publicó como disponible para los Asistentes. NULL = no publicada.';


--
-- Name: COLUMN guardias.ofrecida_por; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardias.ofrecida_por IS 'Usuario del Panel que la publicó.';


--
-- Name: COLUMN guardias.oferta_limite_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardias.oferta_limite_at IS 'Fecha y hora hasta la que se espera respuesta de los Asistentes invitados. NULL = se publicó sin plazo.';


--
-- Name: COLUMN guardias.aviso_sin_cubrir_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardias.aviso_sin_cubrir_at IS 'Última vez que se le avisó al Coordinador que esta guardia sigue sin cubrir. NULL = nunca se avisó.';


--
-- Name: COLUMN guardias.aviso_sin_cubrir_veces; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardias.aviso_sin_cubrir_veces IS 'Cuántas veces se avisó. Sirve para que el aviso repetido diga que ya es la tercera vez, no para decidir si mandarlo.';


--
-- Name: COLUMN guardias.cerrada_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardias.cerrada_at IS 'Cuándo se dio por terminada la guardia. Es distinto de checkout_at: esa es la hora en que el Asistente marcó que se iba de la casa, y esta es la hora en que alguien confirmó que la guardia quedó cerrada.';


--
-- Name: COLUMN guardias.cerrada_por; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardias.cerrada_por IS 'Quién la cerró. Si la cerró el Asistente, es él mismo (todo Asistente es también una fila de usuarios). Si la cerró alguien desde el Panel, es el Coordinador o el Admin de la Prestadora que apretó el botón.';


--
-- Name: COLUMN guardias.cerrada_origen; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardias.cerrada_origen IS 'Desde dónde se cerró: asistente (marcó la salida en su teléfono) o panel (la cerró una persona de la Prestadora porque quedó sin cerrar). Cuando dice panel, la guardia NO tiene hora ni lugar de salida, y el informe a la Obra Social tiene que leerlo así.';


--
-- Name: COLUMN guardias.cerrada_motivo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardias.cerrada_motivo IS 'Por qué se cerró desde el Panel, escrito por la persona que la cerró. Solo se llena cuando el origen es panel: el Asistente que marca su salida no explica nada.';


--
-- Name: COLUMN guardias.aviso_sin_cerrar_grave_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardias.aviso_sin_cerrar_grave_at IS 'Cuándo se avisó por el evento guardia_sin_cerrar_grave. Nulo mientras no se haya escalado.';


--
-- Name: COLUMN guardias.dias_hasta_el_fin; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardias.dias_hasta_el_fin IS 'Cuantos dias despues de fecha termina el turno: 0 el mismo dia, 1 al siguiente, 2 dos dias despues. Permite las guardias de 24, 48 y 72 horas.';


--
-- Name: COLUMN guardias.horas_extra; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardias.horas_extra IS 'Horas de mas autorizadas en esta guardia, anotadas cuando pasaron. No se deducen de la diferencia entre la marca de salida y la hora de fin planificada: irse tarde no es una hora extra autorizada.';


--
-- Name: guardias_cobertura; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.guardias_cobertura (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    guardia_original_id uuid,
    ausencia_id uuid,
    asistente_sustituto_id uuid NOT NULL,
    costo_adicional numeric(12,2),
    created_at timestamp with time zone DEFAULT now(),
    prestadora_id uuid NOT NULL,
    moneda public.moneda_iso NOT NULL,
    asistente_titular_id uuid,
    motivo text,
    motivo_detalle text,
    cobertura_de_ausencia_id uuid,
    CONSTRAINT guardias_cobertura_titular_distinto_del_sustituto CHECK (((asistente_titular_id IS NULL) OR (asistente_titular_id <> asistente_sustituto_id)))
);


--
-- Name: COLUMN guardias_cobertura.costo_adicional; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardias_cobertura.costo_adicional IS 'Lo que la sustitución le cuesta de más a la Prestadora, aparte de lo que se le paga al sustituto por la guardia. La remuneración del sustituto no se escribe acá: la guardia quedó a su nombre, así que se liquida con su propio valor, como la de cualquiera.';


--
-- Name: COLUMN guardias_cobertura.asistente_titular_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardias_cobertura.asistente_titular_id IS 'A quién le tocaba ese turno antes de la sustitución. La guardia en sí pasa a nombre de quien la hace, que es el sustituto; que el titular haya faltado se ve en su ausencia, no acá. Vacío en las coberturas anotadas antes de que existiera esta columna.';


--
-- Name: COLUMN guardias_cobertura.motivo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.guardias_cobertura.motivo IS 'Causa de la sustitución: la clave o el nombre de una fila de motivos_sustitucion_guardia. Vacío en las coberturas anotadas antes de que existiera el catálogo.';


--
-- Name: guardias_tracking_gps; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.guardias_tracking_gps (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    guardia_id uuid NOT NULL,
    lat double precision NOT NULL,
    lng double precision NOT NULL,
    registrado_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: hospitalizaciones_paciente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hospitalizaciones_paciente (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    paciente_id uuid NOT NULL,
    institucion text NOT NULL,
    motivo text,
    fecha_inicio date DEFAULT CURRENT_DATE NOT NULL,
    fecha_fin date,
    registrado_por uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: importaciones_prestadora; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.importaciones_prestadora (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    usuario_id uuid NOT NULL,
    tipo text NOT NULL,
    archivo_nombre text,
    filas_totales integer DEFAULT 0 NOT NULL,
    filas_creadas integer DEFAULT 0 NOT NULL,
    filas_error integer DEFAULT 0 NOT NULL,
    errores jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    estado_conformidad text DEFAULT 'pendiente'::text NOT NULL,
    revisada_en timestamp with time zone,
    revisada_por uuid,
    CONSTRAINT importaciones_prestadora_estado_conformidad_check CHECK ((estado_conformidad = ANY (ARRAY['pendiente'::text, 'confirmada'::text, 'rechazada'::text]))),
    CONSTRAINT importaciones_prestadora_tipo_check CHECK ((tipo = ANY (ARRAY['asistente'::text, 'cliente'::text])))
);


--
-- Name: incidentes_relevo; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.incidentes_relevo (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    guardia_saliente_id uuid,
    guardia_entrante_id uuid NOT NULL,
    nivel_actual integer DEFAULT 1 NOT NULL,
    iniciado_at timestamp with time zone DEFAULT now() NOT NULL,
    resuelto_at timestamp with time zone,
    resuelto_por_tipo text,
    resuelto_por_id uuid,
    ultima_notificacion_at timestamp with time zone,
    veces_notificado integer DEFAULT 0 NOT NULL,
    backup_notificado_at timestamp with time zone,
    fase_automatica_notificada_at timestamp with time zone,
    CONSTRAINT incidentes_relevo_resuelto_por_check CHECK (((resuelto_por_id IS NULL) = ((resuelto_por_tipo = 'familiar'::text) OR (resuelto_por_tipo IS NULL)))),
    CONSTRAINT incidentes_relevo_resuelto_por_tipo_check CHECK ((resuelto_por_tipo = ANY (ARRAY['suplente'::text, 'franquero'::text, 'emergencia'::text, 'familiar'::text])))
);


--
-- Name: incidentes_turno_sin_cubrir; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.incidentes_turno_sin_cubrir (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    guardia_id uuid NOT NULL,
    abierto_at timestamp with time zone DEFAULT now() NOT NULL,
    ultimo_recordatorio_at timestamp with time zone,
    veces_recordado integer DEFAULT 0 NOT NULL,
    resuelto_at timestamp with time zone,
    resuelto_como text,
    resuelto_por uuid,
    nota text,
    resuelto_detalle text,
    CONSTRAINT incidentes_turno_sin_cubrir_cerrar_es_decir_como CHECK (((resuelto_at IS NULL) = (resuelto_como IS NULL)))
);


--
-- Name: TABLE incidentes_turno_sin_cubrir; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.incidentes_turno_sin_cubrir IS 'Un turno que llego a pocas horas de empezar sin nadie asignado. Queda abierto hasta que alguien elija como termino, de la lista que arma cada Prestadora en finales_turno_sin_cubrir.';


--
-- Name: COLUMN incidentes_turno_sin_cubrir.resuelto_como; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.incidentes_turno_sin_cubrir.resuelto_como IS 'Como termino el turno: la clave o el nombre de una fila de finales_turno_sin_cubrir. Si eso fue un defecto grave lo dice esa fila, no esta tabla. Los expedientes cerrados antes del catalogo guardan uno de los tres finales viejos.';


--
-- Name: COLUMN incidentes_turno_sin_cubrir.nota; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.incidentes_turno_sin_cubrir.nota IS 'Lo que la Coordinadora dejo escrito al cerrar. Nunca datos de salud ni de la persona atendida.';


--
-- Name: COLUMN incidentes_turno_sin_cubrir.resuelto_detalle; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.incidentes_turno_sin_cubrir.resuelto_detalle IS 'Que se hizo, cuando el final elegido lo exige. Nunca datos de salud ni de la persona atendida.';


--
-- Name: indicaciones_medicacion; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.indicaciones_medicacion (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    paciente_id uuid NOT NULL,
    cliente_id uuid NOT NULL,
    medicamento text NOT NULL,
    dosis text NOT NULL,
    frecuencia text NOT NULL,
    via_administracion text NOT NULL,
    prescripcion_archivo_url text,
    fecha_desde date NOT NULL,
    fecha_hasta date,
    estado text DEFAULT 'pendiente'::text NOT NULL,
    motivo_rechazo text,
    solicitado_por uuid NOT NULL,
    revisado_por uuid,
    revisado_en timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    nota_aclaratoria text,
    CONSTRAINT indicaciones_medicacion_estado_check CHECK ((estado = ANY (ARRAY['pendiente'::text, 'aceptada'::text, 'rechazada'::text, 'finalizada'::text])))
);


--
-- Name: informes_obra_social; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.informes_obra_social (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    paciente_id uuid NOT NULL,
    cliente_id uuid NOT NULL,
    tipo text NOT NULL,
    periodo_desde date NOT NULL,
    periodo_hasta date NOT NULL,
    contenido jsonb NOT NULL,
    estado text DEFAULT 'validado'::text NOT NULL,
    motivo_anulacion text,
    generado_por uuid NOT NULL,
    validado_por uuid NOT NULL,
    validado_en timestamp with time zone DEFAULT now() NOT NULL,
    anulado_por uuid,
    anulado_en timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT informes_obra_social_anulacion_check CHECK (((estado = 'anulado'::text) OR ((anulado_por IS NULL) AND (anulado_en IS NULL) AND (motivo_anulacion IS NULL)))),
    CONSTRAINT informes_obra_social_estado_check CHECK ((estado = ANY (ARRAY['validado'::text, 'anulado'::text]))),
    CONSTRAINT informes_obra_social_tipo_check CHECK ((tipo = ANY (ARRAY['planilla_asistencia'::text, 'resumen_mensual'::text])))
);


--
-- Name: instrucciones_acceso_personas_autorizadas; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.instrucciones_acceso_personas_autorizadas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    cliente_id uuid NOT NULL,
    dada_por uuid NOT NULL,
    cargada_por uuid NOT NULL,
    documento_texto text NOT NULL,
    documento_huella text NOT NULL,
    documento_idioma text NOT NULL,
    estado text DEFAULT 'pendiente_firma'::text NOT NULL,
    cerrada_como text,
    cerrada_en timestamp with time zone,
    cerrada_desde text,
    archivo_firmado_url text,
    codigo_huella text,
    codigo_expira_en timestamp with time zone,
    codigo_intentos integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT instrucciones_acceso_personas_autorizadas_cerrada_como_check CHECK ((cerrada_como = ANY (ARRAY['confirmada_en_la_app'::text, 'papel_firmado'::text]))),
    CONSTRAINT instrucciones_acceso_personas_autorizadas_estado_check CHECK ((estado = ANY (ARRAY['pendiente_firma'::text, 'cerrada'::text, 'anulada'::text])))
);


--
-- Name: COLUMN instrucciones_acceso_personas_autorizadas.codigo_intentos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.instrucciones_acceso_personas_autorizadas.codigo_intentos IS 'Cuántas veces se probó un código contra esta instrucción. Es la cuenta del acto, no la del código: pedir un código nuevo no la vuelve a cero. Un código vencido no gasta intento, así que quien pide uno nuevo porque el anterior venció no pierde nada.';


--
-- Name: legajos; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.legajos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    numero_legajo bigint NOT NULL,
    clase text NOT NULL,
    nombre text NOT NULL,
    apellido text,
    documento_tipo text,
    documento_numero text,
    calle text,
    numero text,
    piso text,
    unidad text,
    lugar_id uuid,
    email text,
    notas text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    nombre_visible text GENERATED ALWAYS AS (
CASE
    WHEN (clase = 'juridica'::text) THEN nombre
    WHEN ((apellido IS NULL) OR (btrim(apellido) = ''::text)) THEN nombre
    ELSE ((apellido || ', '::text) || nombre)
END) STORED,
    apoderado_legajo_id uuid,
    CONSTRAINT legajos_clase_conocida CHECK ((clase = ANY (ARRAY['fisica'::text, 'juridica'::text]))),
    CONSTRAINT legajos_el_documento_va_entero CHECK (((documento_tipo IS NULL) = (documento_numero IS NULL))),
    CONSTRAINT legajos_el_nombre_no_va_vacio CHECK ((btrim(nombre) <> ''::text)),
    CONSTRAINT legajos_la_fisica_lleva_apellido CHECK (((clase <> 'fisica'::text) OR ((apellido IS NOT NULL) AND (btrim(apellido) <> ''::text)))),
    CONSTRAINT legajos_la_juridica_no_lleva_apellido CHECK (((clase <> 'juridica'::text) OR (apellido IS NULL))),
    CONSTRAINT legajos_solo_la_juridica_tiene_apoderado CHECK (((clase = 'juridica'::text) OR (apoderado_legajo_id IS NULL)))
);


--
-- Name: TABLE legajos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.legajos IS 'El Padron de la Prestadora: un Legajo por Persona, fisica o juridica. Guarda quien es y nada mas; los roles viven donde ocurren y citan el Legajo. No se borra nunca.';


--
-- Name: COLUMN legajos.numero_legajo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.legajos.numero_legajo IS 'Unico adentro de la Prestadora. Lo asigna el disparador y no se reasigna nunca, porque ningun Legajo se borra.';


--
-- Name: COLUMN legajos.clase; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.legajos.clase IS 'fisica (una persona) o juridica (una obra social, una prepaga, una empresa). Las dos cumplen los mismos papeles.';


--
-- Name: COLUMN legajos.nombre; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.legajos.nombre IS 'El nombre de pila de la persona fisica, o la razon social entera de la juridica.';


--
-- Name: COLUMN legajos.nombre_visible; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.legajos.nombre_visible IS 'Cómo se nombra este Legajo en pantalla. La calcula la base para que todas las pantallas digan lo mismo: la persona jurídica por su razón social, la física por apellido y nombre.';


--
-- Name: COLUMN legajos.apoderado_legajo_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.legajos.apoderado_legajo_id IS 'La Persona con poder legal para firmar por esta entidad. Solo la clase juridica lo tiene. No otorga ningun permiso.';


--
-- Name: liquidaciones_asistente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.liquidaciones_asistente (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    asistente_id uuid NOT NULL,
    periodo date NOT NULL,
    tipo_vinculo text NOT NULL,
    base_unidad text NOT NULL,
    base_valor numeric(12,2) NOT NULL,
    horas numeric(10,2) DEFAULT 0 NOT NULL,
    guardias_contadas integer DEFAULT 0 NOT NULL,
    bruto numeric(12,2) NOT NULL,
    total_sumas numeric(12,2) DEFAULT 0 NOT NULL,
    total_restas numeric(12,2) DEFAULT 0 NOT NULL,
    neto numeric(12,2) NOT NULL,
    moneda public.moneda_iso NOT NULL,
    estado text DEFAULT 'pendiente'::text NOT NULL,
    fecha_pago date,
    forma_pago text,
    referencia_pago text,
    generada_por uuid,
    pagada_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    horas_extra numeric(8,2) DEFAULT 0 NOT NULL,
    valor_hora_extra numeric(12,2),
    importe_horas_extra numeric(12,2) DEFAULT 0 NOT NULL,
    periodo_desde date NOT NULL,
    periodo_hasta date NOT NULL,
    CONSTRAINT liquidaciones_asistente_base_unidad_check CHECK ((base_unidad = ANY (ARRAY['valor_hora'::text, 'sueldo_basico'::text, 'valor_guardia'::text, 'valor_semana'::text]))),
    CONSTRAINT liquidaciones_asistente_bordes_en_orden CHECK (((periodo_desde <= periodo_hasta) AND (periodo = periodo_desde))),
    CONSTRAINT liquidaciones_asistente_estado_check CHECK ((estado = ANY (ARRAY['pendiente'::text, 'pagada'::text]))),
    CONSTRAINT liquidaciones_asistente_horas_extra_con_valor CHECK ((((importe_horas_extra = (0)::numeric) AND (valor_hora_extra IS NULL)) OR ((importe_horas_extra > (0)::numeric) AND (valor_hora_extra IS NOT NULL)))),
    CONSTRAINT liquidaciones_asistente_pagada_con_fecha CHECK (((estado <> 'pagada'::text) OR (fecha_pago IS NOT NULL))),
    CONSTRAINT liquidaciones_asistente_tipo_vinculo_check CHECK ((tipo_vinculo = ANY (ARRAY['monotributo'::text, 'dependencia'::text])))
);


--
-- Name: TABLE liquidaciones_asistente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.liquidaciones_asistente IS 'Lo que se le liquidó a un Asistente en un período, con los valores congelados al momento de generarla. No es un comprobante fiscal.';


--
-- Name: COLUMN liquidaciones_asistente.periodo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.liquidaciones_asistente.periodo IS 'El día en que empieza el período. Es siempre igual a periodo_desde.';


--
-- Name: COLUMN liquidaciones_asistente.forma_pago; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.liquidaciones_asistente.forma_pago IS 'Con que medio se le pago al Asistente. Es una opcion de la lista «medios_de_pago_al_asistente», que es otra que la del cobro del Cliente porque no son los mismos medios.';


--
-- Name: COLUMN liquidaciones_asistente.horas_extra; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.liquidaciones_asistente.horas_extra IS 'Horas de mas pagadas en este periodo, sumadas de las guardias. Se copian al generar y no se vuelven a mirar de donde salieron.';


--
-- Name: COLUMN liquidaciones_asistente.valor_hora_extra; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.liquidaciones_asistente.valor_hora_extra IS 'El valor con el que se pagaron las horas de mas de este periodo. Vacio cuando no se pagaron: o no hubo horas anotadas, o las hubo y la ficha no tenia cargado el valor.';


--
-- Name: COLUMN liquidaciones_asistente.periodo_desde; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.liquidaciones_asistente.periodo_desde IS 'Primer día que entra en esta liquidación.';


--
-- Name: COLUMN liquidaciones_asistente.periodo_hasta; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.liquidaciones_asistente.periodo_hasta IS 'Último día que entra en esta liquidación.';


--
-- Name: liquidaciones_asistente_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.liquidaciones_asistente_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    liquidacion_id uuid NOT NULL,
    concepto_id uuid,
    descripcion text NOT NULL,
    signo text NOT NULL,
    unidad text NOT NULL,
    valor_aplicado numeric(14,4) NOT NULL,
    monto numeric(12,2) NOT NULL,
    moneda public.moneda_iso NOT NULL,
    orden smallint DEFAULT 100 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT liquidaciones_asistente_items_signo_check CHECK ((signo = ANY (ARRAY['suma'::text, 'resta'::text]))),
    CONSTRAINT liquidaciones_asistente_items_unidad_check CHECK ((unidad = ANY (ARRAY['monto_fijo_mensual'::text, 'porcentaje'::text, 'monto_por_hora'::text, 'base'::text, 'horas_extra'::text])))
);


--
-- Name: TABLE liquidaciones_asistente_items; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.liquidaciones_asistente_items IS 'Cada renglón de una liquidación, con el nombre y el valor copiados del momento en que se generó.';


--
-- Name: lista_precios; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lista_precios (
    id bigint NOT NULL,
    tipo_servicio text NOT NULL,
    modalidad text NOT NULL,
    precio numeric(12,2) NOT NULL,
    vigente_desde date DEFAULT CURRENT_DATE NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    prestadora_id uuid NOT NULL,
    moneda public.moneda_iso NOT NULL
);


--
-- Name: lista_precios_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.lista_precios ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.lista_precios_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: listas_de_opciones; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.listas_de_opciones (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid,
    clave text NOT NULL,
    i18n jsonb NOT NULL,
    admite_opciones_propias boolean DEFAULT false NOT NULL,
    orden smallint DEFAULT 0 NOT NULL,
    activa boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT el_titulo_de_la_lista_esta_en_los_idiomas_que_le_tocan CHECK (
CASE
    WHEN (prestadora_id IS NOT NULL) THEN interno.i18n_minimo(i18n)
    ELSE interno.i18n_completo(i18n)
END),
    CONSTRAINT la_clave_de_la_lista_no_esta_vacia CHECK ((length(btrim(clave)) > 0))
);


--
-- Name: TABLE listas_de_opciones; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.listas_de_opciones IS 'Las listas de opciones del producto y las que agrega cada Prestadora. Una lista nueva es una fila, no una migracion.';


--
-- Name: COLUMN listas_de_opciones.prestadora_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.listas_de_opciones.prestadora_id IS 'Nulo: la lista que trae el producto, igual para todas. Con valor: la que armo esa Prestadora.';


--
-- Name: COLUMN listas_de_opciones.clave; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.listas_de_opciones.clave IS 'Nombre guardado. Lo cita la pantalla que pide la lista, asi que no se renombra.';


--
-- Name: COLUMN listas_de_opciones.admite_opciones_propias; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.listas_de_opciones.admite_opciones_propias IS 'Si esta lista admite opciones propias de una Prestadora. Falsa cuando lo que guarda se compara entre Organizaciones o contra la ley.';


--
-- Name: llaves_de_dispositivo; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.llaves_de_dispositivo (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    usuario_id uuid NOT NULL,
    rol text NOT NULL,
    credencial_id text NOT NULL,
    clave_publica text NOT NULL,
    contador bigint DEFAULT 0 NOT NULL,
    transportes text[],
    creada_en timestamp with time zone DEFAULT now() NOT NULL,
    ultimo_uso_en timestamp with time zone,
    revocada_en timestamp with time zone,
    CONSTRAINT llaves_de_dispositivo_rol_check CHECK ((rol = ANY (ARRAY['asistente'::text, 'cliente'::text])))
);


--
-- Name: TABLE llaves_de_dispositivo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.llaves_de_dispositivo IS 'Llaves que cada persona guarda en su propio telefono para entrar sin escribir la contrasena. Se guarda la mitad publica de la llave; la privada nunca sale del aparato y ningun dato biometrico entra aca.';


--
-- Name: COLUMN llaves_de_dispositivo.rol; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.llaves_de_dispositivo.rol IS 'En cual de las dos aplicaciones nacio la llave. Una llave del Asistente no sirve para entrar a la del Cliente: son dos aplicaciones con permisos distintos.';


--
-- Name: COLUMN llaves_de_dispositivo.credencial_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.llaves_de_dispositivo.credencial_id IS 'Como el telefono nombra a esta llave. Unico en todo el producto, porque asi llega la firma cuando la pantalla de ingreso todavia no sabe quien esta entrando.';


--
-- Name: COLUMN llaves_de_dispositivo.contador; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.llaves_de_dispositivo.contador IS 'Cuantas veces el aparato dice haber usado esta llave. Si baja, hay dos copias de la misma llave dando vueltas. Muchos telefonos no llevan cuenta y lo dejan siempre en cero.';


--
-- Name: COLUMN llaves_de_dispositivo.revocada_en; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.llaves_de_dispositivo.revocada_en IS 'Cuando se dio de baja. La fila no se borra: deja constancia de que esa llave existio.';


--
-- Name: lugares; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lugares (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    nombre text NOT NULL,
    pais text NOT NULL,
    provincia text,
    municipio text,
    id_oficial text,
    fuente text DEFAULT 'propio'::text NOT NULL,
    parte_de uuid,
    lat double precision,
    lng double precision,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT lugares_el_oficial_trae_su_identificador CHECK (((fuente <> 'oficial'::text) OR (id_oficial IS NOT NULL))),
    CONSTRAINT lugares_fuente_conocida CHECK ((fuente = ANY (ARRAY['oficial'::text, 'propio'::text]))),
    CONSTRAINT lugares_no_se_contiene_a_si_mismo CHECK (((parte_de IS NULL) OR (parte_de <> id)))
);


--
-- Name: TABLE lugares; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.lugares IS 'Las localidades y los barrios donde trabaja una Prestadora, en una sola lista de un solo nivel. Cada renglon dice si salio del organismo oficial del pais o lo agrego la Prestadora.';


--
-- Name: COLUMN lugares.id_oficial; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lugares.id_oficial IS 'El identificador del organismo oficial del pais. En blanco cuando el lugar lo agrego la Prestadora.';


--
-- Name: COLUMN lugares.fuente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lugares.fuente IS 'oficial (nombre e identificador del organismo, no se editan a mano) o propio (los puso la Prestadora).';


--
-- Name: COLUMN lugares.parte_de; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lugares.parte_de IS 'El lugar que lo contiene, cuando lo hay: un barrio cuelga de su localidad. Una localidad no cuelga de nada.';


--
-- Name: matriculas_asistente_verificacion; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.matriculas_asistente_verificacion WITH (security_invoker='true') AS
 SELECT id,
    asistente_id,
    tipo,
    numero_matricula,
    vigente_desde,
    vigente_hasta,
    archivo_url,
    registrado_por,
    created_at,
    verificada_at,
    verificada_por,
    metodo_verificacion,
    nota_verificacion,
    cargada_por_el_asistente,
    interno.nombre_de_usuario(verificada_por) AS verificada_por_nombre
   FROM public.matriculas_asistente m;


--
-- Name: VIEW matriculas_asistente_verificacion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.matriculas_asistente_verificacion IS 'Las matrículas de los Asistentes con el nombre de quien las verificó ya resuelto. Se evalúa con los permisos de quien consulta, así que muestra exactamente las mismas filas que matriculas_asistente: lo único que agrega es el nombre. Para escribir se usa la tabla.';


--
-- Name: COLUMN matriculas_asistente_verificacion.verificada_por_nombre; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.matriculas_asistente_verificacion.verificada_por_nombre IS 'Nombre de quien verificó la matrícula. Vacío cuando todavía no se verificó.';


--
-- Name: mensajes_asistente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mensajes_asistente (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    asistente_id uuid NOT NULL,
    usuario_id uuid NOT NULL,
    mensaje text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    push_enviado_at timestamp with time zone
);


--
-- Name: mensajes_del_sistema; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mensajes_del_sistema (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid,
    clave text NOT NULL,
    i18n jsonb NOT NULL,
    admite_texto_propio boolean DEFAULT true NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT el_mensaje_trae_los_idiomas_que_le_tocan CHECK (
CASE
    WHEN (prestadora_id IS NOT NULL) THEN interno.i18n_minimo(i18n)
    ELSE interno.i18n_completo(i18n)
END),
    CONSTRAINT la_clave_del_mensaje_no_viene_vacia CHECK ((btrim(clave) <> ''::text))
);


--
-- Name: mensajes_match; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mensajes_match (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    conversacion_id uuid NOT NULL,
    lado text NOT NULL,
    autor_usuario_id uuid NOT NULL,
    cuerpo text NOT NULL,
    automatico boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    leido_at timestamp with time zone,
    push_enviado_at timestamp with time zone,
    regla_tapada text,
    CONSTRAINT mensajes_match_cuerpo_check CHECK ((btrim(cuerpo) <> ''::text)),
    CONSTRAINT mensajes_match_lado_check CHECK ((lado = ANY (ARRAY['cliente'::text, 'asistente'::text])))
);


--
-- Name: TABLE mensajes_match; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.mensajes_match IS 'Los mensajes de un hilo de Match. Se guardan ya tapados: lo que no puede viajar en un mensaje no queda escrito en ningun lado, asi que llegar al dato por otra via no lo muestra.';


--
-- Name: COLUMN mensajes_match.cuerpo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.mensajes_match.cuerpo IS 'El texto ya tapado. Lo que las reglas de los mensajes alcanzan no se guarda: se tapa antes de escribirlo, del lado de la base.';


--
-- Name: COLUMN mensajes_match.automatico; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.mensajes_match.automatico IS 'Lo escribio el producto, no una persona. El cuerpo es una clave de traduccion, no texto visible.';


--
-- Name: COLUMN mensajes_match.regla_tapada; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.mensajes_match.regla_tapada IS 'La clave de la primera regla que tapo algo en este mensaje, o nula si no se tapo nada. Es una clave, nunca el texto tapado.';


--
-- Name: mensajes_whatsapp; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mensajes_whatsapp (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    conversacion_id uuid NOT NULL,
    direccion text NOT NULL,
    texto text NOT NULL,
    generado_por_ia boolean DEFAULT false NOT NULL,
    enviado_automaticamente boolean DEFAULT false NOT NULL,
    revisado_por_coordinador_at timestamp with time zone,
    meta_message_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT mensajes_whatsapp_direccion_check CHECK ((direccion = ANY (ARRAY['entrante'::text, 'saliente'::text])))
);


--
-- Name: mfa_codigos_recuperacion; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mfa_codigos_recuperacion (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    usuario_id uuid NOT NULL,
    codigo_hash text NOT NULL,
    expira_at timestamp with time zone NOT NULL,
    usado boolean DEFAULT false NOT NULL,
    usado_en timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: monedas_por_pais; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.monedas_por_pais (
    pais text NOT NULL,
    moneda public.moneda_iso NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE monedas_por_pais; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.monedas_por_pais IS 'Catálogo de plataforma: qué moneda le corresponde a cada país. Lo usa el alta de una Prestadora para saber en qué moneda carga sus precios. Se amplía agregando filas, nunca tocando código.';


--
-- Name: motivos_aviso_previo_guardia; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.motivos_aviso_previo_guardia (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    nombre text NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now()
);


--
-- Name: motivos_cierre_servicio; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.motivos_cierre_servicio (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    clave text,
    nombre text,
    pide_detalle boolean DEFAULT false NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    orden integer DEFAULT 100 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT motivos_cierre_servicio_nombre_segun_nivel CHECK ((((clave IS NOT NULL) AND (nombre IS NULL)) OR ((clave IS NULL) AND (nombre IS NOT NULL))))
);


--
-- Name: TABLE motivos_cierre_servicio; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.motivos_cierre_servicio IS 'Por qué se cierra la atención de un Paciente. Cada Prestadora arma su lista: nace con siete que trae el producto y a partir de ahí agrega y saca los que quiera.';


--
-- Name: COLUMN motivos_cierre_servicio.clave; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.motivos_cierre_servicio.clave IS 'Motivo que trajo el producto. El texto visible sale de las traducciones, buscándolo por esta clave; es también lo que se guarda en el cierre.';


--
-- Name: COLUMN motivos_cierre_servicio.nombre; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.motivos_cierre_servicio.nombre IS 'Motivo que escribió la Prestadora. Se muestra tal cual, sin traducir, y es lo que se guarda en el cierre.';


--
-- Name: COLUMN motivos_cierre_servicio.pide_detalle; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.motivos_cierre_servicio.pide_detalle IS 'Cerrar con este motivo obliga a escribir el detalle.';


--
-- Name: motivos_resolucion; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.motivos_resolucion (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    tabla text NOT NULL,
    estado text NOT NULL,
    nombre_es_ar text NOT NULL,
    nombre_en text NOT NULL,
    nombre_pt_br text NOT NULL,
    pide_detalle boolean DEFAULT false NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    orden integer DEFAULT 100 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT motivos_resolucion_estado_no_vacio CHECK ((length(btrim(estado)) > 0)),
    CONSTRAINT motivos_resolucion_tabla_no_vacia CHECK ((length(btrim(tabla)) > 0)),
    CONSTRAINT motivos_resolucion_tres_idiomas CHECK (((length(btrim(nombre_es_ar)) > 0) AND (length(btrim(nombre_en)) > 0) AND (length(btrim(nombre_pt_br)) > 0)))
);


--
-- Name: TABLE motivos_resolucion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.motivos_resolucion IS 'Por que se resolvio algo. Cada Prestadora arma su lista: nace con los motivos que trae el producto y a partir de ahi agrega, apaga y ordena los suyos.';


--
-- Name: COLUMN motivos_resolucion.tabla; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.motivos_resolucion.tabla IS 'Que se resuelve con este motivo. Es el nombre guardado de la tabla cuya fila se resuelve, por ejemplo postulaciones o solicitudes.';


--
-- Name: COLUMN motivos_resolucion.estado; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.motivos_resolucion.estado IS 'En que estado queda lo resuelto al elegir este motivo. Lo dice el motivo, no quien llama.';


--
-- Name: COLUMN motivos_resolucion.nombre_es_ar; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.motivos_resolucion.nombre_es_ar IS 'El motivo escrito en castellano rioplatense. Se muestra tal cual.';


--
-- Name: COLUMN motivos_resolucion.nombre_en; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.motivos_resolucion.nombre_en IS 'El motivo escrito en ingles. Se muestra tal cual.';


--
-- Name: COLUMN motivos_resolucion.nombre_pt_br; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.motivos_resolucion.nombre_pt_br IS 'El motivo escrito en portugues de Brasil. Se muestra tal cual.';


--
-- Name: COLUMN motivos_resolucion.pide_detalle; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.motivos_resolucion.pide_detalle IS 'Elegir este motivo obliga a escribir ademas que paso. La base lo exige, no la pantalla.';


--
-- Name: motivos_sustitucion_guardia; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.motivos_sustitucion_guardia (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    clave text,
    nombre text,
