    activo boolean DEFAULT true NOT NULL,
    orden integer DEFAULT 100 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT motivos_sustitucion_guardia_nombre_segun_nivel CHECK ((((clave IS NOT NULL) AND (nombre IS NULL)) OR ((clave IS NULL) AND (nombre IS NOT NULL))))
);


--
-- Name: TABLE motivos_sustitucion_guardia; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.motivos_sustitucion_guardia IS 'Por qué una guardia la termina haciendo otra persona. Cada Prestadora arma su lista: nace con dos que trae el producto y a partir de ahí agrega y saca las que quiera.';


--
-- Name: COLUMN motivos_sustitucion_guardia.clave; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.motivos_sustitucion_guardia.clave IS 'Causa que trajo el producto. El texto visible sale de las traducciones, buscándolo por esta clave; es también lo que se guarda en la cobertura.';


--
-- Name: COLUMN motivos_sustitucion_guardia.nombre; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.motivos_sustitucion_guardia.nombre IS 'Causa que escribió la Prestadora. Se muestra tal cual, sin traducir, y es lo que se guarda en la cobertura.';


--
-- Name: COLUMN motivos_sustitucion_guardia.pide_detalle; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.motivos_sustitucion_guardia.pide_detalle IS 'Sustituir con esta causa obliga a escribir el detalle.';


--
-- Name: notificaciones_cierre_servicio; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notificaciones_cierre_servicio (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    cierre_id uuid NOT NULL,
    paciente_id uuid NOT NULL,
    asistente_id uuid NOT NULL,
    cerrado_por uuid NOT NULL,
    motivo text NOT NULL,
    motivo_detalle text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    visto_at timestamp with time zone,
    visto_por uuid
);


--
-- Name: notificaciones_cierre_servicio_quien_cerro; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.notificaciones_cierre_servicio_quien_cerro WITH (security_invoker='true') AS
 SELECT id,
    prestadora_id,
    cierre_id,
    paciente_id,
    asistente_id,
    cerrado_por,
    motivo,
    motivo_detalle,
    created_at,
    visto_at,
    visto_por,
    interno.nombre_de_usuario(cerrado_por) AS cerrado_por_nombre
   FROM public.notificaciones_cierre_servicio n;


--
-- Name: VIEW notificaciones_cierre_servicio_quien_cerro; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.notificaciones_cierre_servicio_quien_cerro IS 'Los avisos de cierre de servicio con el nombre de quien cerró ya resuelto. Se evalúa con los permisos de quien consulta, así que muestra exactamente las mismas filas que notificaciones_cierre_servicio: lo único que agrega es el nombre. Para escribir se usa la tabla.';


--
-- Name: COLUMN notificaciones_cierre_servicio_quien_cerro.cerrado_por_nombre; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.notificaciones_cierre_servicio_quien_cerro.cerrado_por_nombre IS 'Nombre de quien cerró el servicio. Vacío si esa persona ya no está en el sistema.';


--
-- Name: ofertas_guardia; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ofertas_guardia (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    guardia_id uuid NOT NULL,
    asistente_id uuid NOT NULL,
    invitado_por uuid,
    invitado_at timestamp with time zone DEFAULT now() NOT NULL,
    respuesta text,
    respuesta_at timestamp with time zone,
    motivo text,
    CONSTRAINT ofertas_guardia_respuesta_check CHECK ((respuesta = ANY (ARRAY['acepta'::text, 'rechaza'::text]))),
    CONSTRAINT ofertas_guardia_respuesta_completa_check CHECK (((respuesta IS NULL) = (respuesta_at IS NULL)))
);


--
-- Name: TABLE ofertas_guardia; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.ofertas_guardia IS 'Invitaciones a tomar una guardia sin cubrir. Una fila por Asistente invitado, con su respuesta individual.';


--
-- Name: COLUMN ofertas_guardia.respuesta; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ofertas_guardia.respuesta IS 'NULL = todavía no contestó. Es distinto de "rechaza", y esa diferencia es la que mira el mostrador.';


--
-- Name: COLUMN ofertas_guardia.motivo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ofertas_guardia.motivo IS 'Lo que el Asistente escribió al rechazar. Opcional.';


--
-- Name: opciones_de_lista; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.opciones_de_lista (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid,
    lista_id uuid NOT NULL,
    clave text NOT NULL,
    i18n jsonb NOT NULL,
    orden integer DEFAULT 0 NOT NULL,
    activa boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    modalidades text[],
    CONSTRAINT el_texto_de_la_opcion_esta_en_los_idiomas_que_le_tocan CHECK (
CASE
    WHEN (prestadora_id IS NOT NULL) THEN interno.i18n_minimo(i18n)
    ELSE interno.i18n_completo(i18n)
END),
    CONSTRAINT la_clave_de_la_opcion_no_esta_vacia CHECK ((length(btrim(clave)) > 0)),
    CONSTRAINT la_opcion_propia_va_detras_del_catalogo_general CHECK (
CASE
    WHEN (prestadora_id IS NOT NULL) THEN (orden > interno.orden_desde_el_que_cuentan_las_opciones_propias())
    ELSE (orden <= interno.orden_desde_el_que_cuentan_las_opciones_propias())
END),
    CONSTRAINT opciones_de_lista_modalidades_check CHECK (((modalidades IS NULL) OR ((array_length(modalidades, 1) >= 1) AND (modalidades <@ ARRAY['directa'::text, 'match'::text, 'subcontratacion'::text]))))
);


--
-- Name: TABLE opciones_de_lista; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.opciones_de_lista IS 'Las opciones de cada lista: las que trae el producto, con los tres idiomas, y las que agrega cada Prestadora, en el idioma en que las escribio.';


--
-- Name: COLUMN opciones_de_lista.clave; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.opciones_de_lista.clave IS 'Lo que queda guardado en la ficha de quien eligio esta opcion. No se renombra.';


--
-- Name: COLUMN opciones_de_lista.orden; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.opciones_de_lista.orden IS 'En que orden se ofrecen. Lo general hasta 100; lo propio de una Prestadora, desde 101.';


--
-- Name: COLUMN opciones_de_lista.activa; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.opciones_de_lista.activa IS 'Una opcion no se borra: se apaga. Apagada deja de ofrecerse y sigue nombrando lo que ya se eligio.';


--
-- Name: COLUMN opciones_de_lista.modalidades; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.opciones_de_lista.modalidades IS 'En que modalidades de trabajo se puede usar esta opcion. Nulo quiere decir que alcanza a todas.';


--
-- Name: opciones_postulacion; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.opciones_postulacion (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    grupo text NOT NULL,
    clave text NOT NULL,
    etiqueta text NOT NULL,
    orden smallint DEFAULT 100 NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT opciones_postulacion_grupo_conocido CHECK ((grupo = ANY (ARRAY['genero'::text, 'nacionalidad'::text, 'tipo_registro_afip'::text, 'especialidad'::text, 'experiencia_clinica_discapacidades'::text, 'experiencia_clinica_patologias'::text, 'experiencia_clinica_cuidado_directo'::text, 'experiencia_clinica_acompanamiento'::text, 'experiencia_clinica_tareas_domesticas'::text])))
);


--
-- Name: pacientes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pacientes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    cliente_id uuid,
    nombre text NOT NULL,
    fecha_nacimiento date,
    patologias text[],
    medicacion_habitual jsonb,
    nivel_complejidad text,
    domicilio text,
    lat double precision,
    lng double precision,
    numero_afiliado text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    deleted_at timestamp with time zone,
    prestadora_id uuid NOT NULL,
    ultimo_analisis_ia_at timestamp with time zone,
    importacion_id uuid,
    pendiente_conformidad boolean DEFAULT false NOT NULL,
    calle text,
    numero text,
    piso text,
    unidad text,
    lugar_id uuid,
    obra_social_legajo_id uuid,
    fecha_fallecimiento date,
    CONSTRAINT pacientes_nivel_complejidad_check CHECK ((nivel_complejidad = ANY (ARRAY['I'::text, 'II'::text, 'III'::text]))),
    CONSTRAINT pacientes_no_fallece_antes_de_nacer CHECK (((fecha_fallecimiento IS NULL) OR (fecha_nacimiento IS NULL) OR (fecha_fallecimiento >= fecha_nacimiento)))
);


--
-- Name: COLUMN pacientes.unidad; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pacientes.unidad IS 'El departamento dentro del piso. Se llama unidad para no confundirlo con el departamento de una provincia.';


--
-- Name: COLUMN pacientes.lugar_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pacientes.lugar_id IS 'La localidad o el barrio donde vive, elegido de la lista de lugares de la Prestadora.';


--
-- Name: COLUMN pacientes.obra_social_legajo_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pacientes.obra_social_legajo_id IS 'Cual Legajo del Padron es la obra social de este Paciente. Vacio quiere decir que no tiene ninguna. El nombre no se copia: sale del Legajo cada vez que se muestra.';


--
-- Name: COLUMN pacientes.fecha_fallecimiento; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.pacientes.fecha_fallecimiento IS 'Llega de afuera y puede faltar. Vacía quiere decir que no se sabe. Mientras falte, un plazo de conservación que corre desde la muerte no tiene vencimiento y ninguna purga corre sobre este Paciente.';


