    como_conocio character varying(100),
    mensaje text,
    estado character varying(30) DEFAULT 'pendiente'::character varying,
    canal character varying(50) DEFAULT 'web'::character varying,
    creado_en timestamp with time zone DEFAULT now(),
    nota_interna text,
    asistente_id uuid,
    dni text,
    idioma text DEFAULT 'es-AR'::text NOT NULL,
    prestadora_id uuid NOT NULL,
    fecha_nacimiento date,
    domicilio text,
    lat double precision,
    lng double precision,
    localidad text,
    nacionalidad text,
    cuil text,
    genero text,
    foto_perfil_url text,
    tipo_registro_afip text,
    obra_social text,
    estudios jsonb DEFAULT '[]'::jsonb NOT NULL,
    experiencia_laboral jsonb DEFAULT '[]'::jsonb NOT NULL,
    referencias_laborales jsonb DEFAULT '[]'::jsonb NOT NULL,
    experiencia_clinica text[] DEFAULT '{}'::text[] NOT NULL,
    distancia_maxima_km numeric(6,2),
    disponible_urgencias boolean DEFAULT false NOT NULL,
    disponible_con_retiro boolean DEFAULT false NOT NULL,
    disponible_sin_retiro boolean DEFAULT false NOT NULL,
    honorario_pretendido numeric(12,2),
    moneda public.moneda_iso NOT NULL,
    CONSTRAINT postulaciones_distancia_positiva CHECK (((distancia_maxima_km IS NULL) OR (distancia_maxima_km > (0)::numeric))),
    CONSTRAINT postulaciones_honorario_positivo CHECK (((honorario_pretendido IS NULL) OR (honorario_pretendido > (0)::numeric))),
    CONSTRAINT postulaciones_listas_son_listas CHECK (((jsonb_typeof(estudios) = 'array'::text) AND (jsonb_typeof(experiencia_laboral) = 'array'::text) AND (jsonb_typeof(referencias_laborales) = 'array'::text)))
);


--
-- Name: COLUMN postulaciones.especialidades; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.postulaciones.especialidades IS 'Claves de opciones_postulacion del grupo especialidad, separadas por coma. Nunca la etiqueta traducida: una postulación en cualquier idioma guarda siempre el mismo valor.';


--
-- Name: COLUMN postulaciones.fecha_nacimiento; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.postulaciones.fecha_nacimiento IS 'La mayoría de edad se comprueba contra la escala legal vigente de la jurisdicción, nunca contra un 18 escrito en el código.';


--
-- Name: COLUMN postulaciones.experiencia_clinica; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.postulaciones.experiencia_clinica IS 'Claves de opciones_postulacion cuyo grupo empieza con experiencia_clinica_.';


--
-- Name: COLUMN postulaciones.honorario_pretendido; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.postulaciones.honorario_pretendido IS 'Lo que la persona pretende cobrar por hora. Opcional: no decirlo no traba la postulación.';


--
-- Name: postulaciones_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.postulaciones ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.postulaciones_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: prestaciones; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.prestaciones (
    id bigint NOT NULL,
    paciente_id uuid NOT NULL,
    tipo_servicio text NOT NULL,
    configuracion jsonb DEFAULT '{}'::jsonb NOT NULL,
    precio_lista_id bigint,
    precio_lista_snapshot numeric(12,2),
    tipo_descuento text,
    valor_descuento numeric(12,2),
    precio_final numeric(12,2) NOT NULL,
    nota text,
    estado text DEFAULT 'vigente'::text NOT NULL,
    requiere_revision boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    prestadora_id uuid NOT NULL,
    servicio_id uuid,
    moneda public.moneda_iso NOT NULL,
    vigente_desde date DEFAULT CURRENT_DATE NOT NULL,
    vigente_hasta date,
    CONSTRAINT prestaciones_estado_check CHECK ((estado = ANY (ARRAY['vigente'::text, 'de_baja'::text]))),
    CONSTRAINT prestaciones_tipo_descuento_check CHECK ((tipo_descuento = ANY (ARRAY['porcentaje'::text, 'monto_fijo'::text]))),
    CONSTRAINT prestaciones_vigencia_coherente CHECK (((vigente_hasta IS NULL) OR (vigente_hasta >= vigente_desde)))
);


--
-- Name: COLUMN prestaciones.vigente_desde; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.prestaciones.vigente_desde IS 'Primer dia en que corre lo pactado. Puede ser posterior al alta: un acuerdo se firma antes de arrancar.';


--
-- Name: COLUMN prestaciones.vigente_hasta; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.prestaciones.vigente_hasta IS 'Ultimo dia en que corre lo pactado, incluido. Vacio quiere decir que sigue abierta.';


--
-- Name: prestaciones_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.prestaciones ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.prestaciones_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: prestadora_modalidades; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.prestadora_modalidades (
