    activada_por uuid,
    activada_en timestamp with time zone DEFAULT now() NOT NULL,
    desactivada_por uuid,
    desactivada_en timestamp with time zone,
    CONSTRAINT prestadora_modalidades_modalidad_check CHECK ((modalidad = ANY (ARRAY['directa'::text, 'match'::text, 'subcontratacion'::text])))
);


--
-- Name: prestadora_pasarela_pago; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.prestadora_pasarela_pago (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    proveedor text NOT NULL,
    estado_conexion text DEFAULT 'pendiente'::text NOT NULL,
    activada_por uuid,
    conectada_en timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT prestadora_pasarela_pago_estado_conexion_check CHECK ((estado_conexion = ANY (ARRAY['pendiente'::text, 'conectada'::text, 'error'::text])))
);


--
-- Name: push_subscriptions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.push_subscriptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    asistente_id uuid,
    endpoint text NOT NULL,
    p256dh text NOT NULL,
    auth text NOT NULL,
    user_agent text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    cliente_id uuid,
    CONSTRAINT push_subscriptions_una_audiencia CHECK (((asistente_id IS NOT NULL) <> (cliente_id IS NOT NULL)))
);


--
-- Name: qr_cobro_efectivo; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.qr_cobro_efectivo (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    acceso_id uuid NOT NULL,
    cliente_id uuid NOT NULL,
    periodo date NOT NULL,
    monto numeric(12,2) NOT NULL,
    token text NOT NULL,
    expira_en timestamp with time zone NOT NULL,
    usado_en timestamp with time zone,
    usado_por uuid,
    cobro_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    moneda public.moneda_iso NOT NULL
);


--
-- Name: rangos_referencia_vitales; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.rangos_referencia_vitales (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    paciente_id uuid,
    signo text NOT NULL,
    valor_min numeric NOT NULL,
    valor_max numeric NOT NULL,
    unidad text NOT NULL,
    fuente text NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    nota_aclaratoria text,
    CONSTRAINT rangos_referencia_vitales_signo_check CHECK ((signo = ANY (ARRAY['presion_sistolica'::text, 'presion_diastolica'::text, 'temperatura'::text, 'saturacion'::text, 'glucemia'::text])))
);


--
-- Name: referencias_laborales_asistente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.referencias_laborales_asistente (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    asistente_id uuid NOT NULL,
    nombre text NOT NULL,
    telefono text NOT NULL,
    vinculo text,
    resultado text DEFAULT 'pendiente'::text NOT NULL,
    notas text,
    verificada_por uuid,
    verificada_en timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT referencias_laborales_asistente_resultado_conocido CHECK ((resultado = ANY (ARRAY['pendiente'::text, 'verificada'::text, 'no_responde'::text, 'rechazada'::text]))),
    CONSTRAINT referencias_laborales_asistente_verificada_tiene_firma CHECK (((resultado = 'pendiente'::text) OR (verificada_en IS NOT NULL)))
);


--
-- Name: TABLE referencias_laborales_asistente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.referencias_laborales_asistente IS 'Las referencias laborales del Asistente, una por fila, con el resultado de haberla llamado. Nacen copiadas de la postulación y se pueden agregar a mano.';


--
-- Name: COLUMN referencias_laborales_asistente.vinculo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.referencias_laborales_asistente.vinculo IS 'Qué relación tuvo con el Asistente. Texto libre: no hay catálogo, y cada Prestadora pregunta lo que quiere.';


--
-- Name: COLUMN referencias_laborales_asistente.resultado; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.referencias_laborales_asistente.resultado IS 'pendiente: todavía no se la llamó. verificada: contestó y confirmó. no_responde: se la llamó y no hubo respuesta. rechazada: contestó y no confirmó.';


--
-- Name: registro_actividad; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.registro_actividad (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    usuario_id uuid NOT NULL,
    accion text NOT NULL,
    tabla_afectada text,
    registro_id uuid,
    campos_cambiados text[],
    detalle jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE registro_actividad; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.registro_actividad IS 'Lo que hace la gente de una Prestadora: quien, cuando, sobre que y que cambio. Append-only: no se edita y no se borra, ni con la llave de servicio.';


--
-- Name: COLUMN registro_actividad.usuario_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.registro_actividad.usuario_id IS 'Quien hizo la accion. Lo pone el motor con la cuenta de la sesion comprobada, nunca con un valor que venga en el pedido.';


--
-- Name: COLUMN registro_actividad.accion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.registro_actividad.accion IS 'Que se hizo, en clave opaca del catalogo de acciones registradas.';


--
-- Name: COLUMN registro_actividad.tabla_afectada; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.registro_actividad.tabla_afectada IS 'Sobre que tabla, cuando la accion recae sobre una.';


--
-- Name: COLUMN registro_actividad.registro_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.registro_actividad.registro_id IS 'Sobre que fila, cuando la accion recae sobre una. Se conserva aunque la fila ya no exista.';


--
-- Name: COLUMN registro_actividad.campos_cambiados; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.registro_actividad.campos_cambiados IS 'Que cambio: los nombres de las columnas que se tocaron, nunca sus valores. Es la forma de contestar «que cambio» sin guardar contenido de nadie.';


--
-- Name: COLUMN registro_actividad.detalle; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.registro_actividad.detalle IS 'Los pocos datos con nombre que el registro admite, que son los del catalogo de datos del registro. Ninguna clave, ningun importe, ninguna remuneracion, ninguna direccion y ningun contenido.';


--
-- Name: reglas_de_conservacion; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.reglas_de_conservacion (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    jurisdiccion text NOT NULL,
    clase_de_registro text NOT NULL,
    tramo smallint DEFAULT 1 NOT NULL,
    hecho_de_inicio text NOT NULL,
    plazo_meses integer,
    al_vencer text NOT NULL,
    fuente text NOT NULL,
    vigencia_desde date NOT NULL,
    vigencia_hasta date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT reglas_de_conservacion_accion_conocida CHECK ((al_vencer = ANY (ARRAY['borrar'::text, 'desasociar'::text, 'avisar'::text, 'conservar'::text, 'seudonimizar'::text]))),
    CONSTRAINT reglas_de_conservacion_cita_su_norma CHECK ((btrim(fuente) <> ''::text)),
    CONSTRAINT reglas_de_conservacion_el_plazo_no_es_negativo CHECK (((plazo_meses IS NULL) OR (plazo_meses >= 0))),
    CONSTRAINT reglas_de_conservacion_el_tramo_empieza_en_uno CHECK ((tramo >= 1)),
    CONSTRAINT reglas_de_conservacion_hecho_conocido CHECK ((hecho_de_inicio = ANY (ARRAY['ultima_atencion'::text, 'ultimo_registro'::text, 'fallecimiento'::text, 'cada_registro'::text, 'fin_del_tratamiento'::text]))),
    CONSTRAINT reglas_de_conservacion_jurisdiccion_es_un_pais CHECK ((jurisdiccion ~ '^[A-Z]{2}$'::text)),
    CONSTRAINT reglas_de_conservacion_la_clase_no_va_vacia CHECK ((btrim(clase_de_registro) <> ''::text)),
    CONSTRAINT reglas_de_conservacion_la_vigencia_no_termina_antes_de_empezar CHECK (((vigencia_hasta IS NULL) OR (vigencia_hasta >= vigencia_desde))),
    CONSTRAINT reglas_de_conservacion_sin_plazo_se_conserva CHECK (((plazo_meses IS NOT NULL) OR (al_vencer = 'conservar'::text)))
);


--
-- Name: TABLE reglas_de_conservacion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.reglas_de_conservacion IS 'Plazos legales de conservación por país y clase de registro. Un renglón por tramo; los tramos de una misma regla se suman en orden. Se carga con migraciones y ningún plazo vive en el código.';


--
-- Name: reglas_de_los_mensajes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.reglas_de_los_mensajes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid,
    clave text NOT NULL,
    patron text NOT NULL,
    banderas text DEFAULT 'g'::text NOT NULL,
    motivo jsonb NOT NULL,
    orden smallint NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT el_motivo_esta_en_los_tres_idiomas CHECK (((btrim(COALESCE((motivo ->> 'es-AR'::text), ''::text)) <> ''::text) AND (btrim(COALESCE((motivo ->> 'en'::text), ''::text)) <> ''::text) AND (btrim(COALESCE((motivo ->> 'pt-BR'::text), ''::text)) <> ''::text))),
    CONSTRAINT el_patron_compila_en_postgres CHECK ((length(regexp_replace(''::text, interno.patron_de_mensaje_en_postgres(patron), ''::text)) = 0)),
    CONSTRAINT el_patron_no_usa_lo_que_no_se_traduce CHECK (((patron !~ '\\[B1-9]'::text) AND (patron !~ '\(\?[=!<]'::text))),
    CONSTRAINT las_banderas_son_conocidas CHECK (((banderas ~ '^[gi]*$'::text) AND (POSITION(('g'::text) IN (banderas)) > 0)))
);


--
-- Name: TABLE reglas_de_los_mensajes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.reglas_de_los_mensajes IS 'Que no puede viajar adentro de un mensaje: el telefono, el correo, el domicilio, el nombre de usuario de otra aplicacion y la invitacion a seguir la charla en otro lado. Es dato y no codigo: se agrega una regla sin publicar ninguna version. La aplica el disparador que tapa el texto antes de guardarlo.';


--
-- Name: COLUMN reglas_de_los_mensajes.prestadora_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reglas_de_los_mensajes.prestadora_id IS 'Nula: regla general, vale para todas las Prestadoras. Ninguna Prestadora escribe acá; que se tapa no es configuracion de ella.';


--
-- Name: COLUMN reglas_de_los_mensajes.clave; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reglas_de_los_mensajes.clave IS 'Nombre guardado de la regla. Queda anotado en el mensaje que tapo, y es lo unico que sale hacia afuera. No se renombra.';


--
-- Name: COLUMN reglas_de_los_mensajes.patron; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reglas_de_los_mensajes.patron IS 'La expresion escrita con la sintaxis corriente. La base la traduce al leerla con interno.patron_de_mensaje_en_postgres.';


--
-- Name: COLUMN reglas_de_los_mensajes.motivo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reglas_de_los_mensajes.motivo IS 'Por que se tapo, en los tres idiomas. Lo muestra la pantalla a quien escribio.';


--
-- Name: COLUMN reglas_de_los_mensajes.orden; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reglas_de_los_mensajes.orden IS 'En que orden corren. Importa: el correo se tapa antes que el nombre de usuario, o se taparia primero la cola del correo.';


--
-- Name: remuneraciones_asistente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.remuneraciones_asistente (
    asistente_id uuid NOT NULL,
    prestadora_id uuid NOT NULL,
    valor_hora numeric(12,2),
    sueldo_basico numeric(12,2),
    categoria_cct text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    moneda public.moneda_iso NOT NULL,
    unidad_medicion text DEFAULT 'hora'::text NOT NULL,
    valor_guardia numeric(12,2),
    valor_semana numeric(12,2),
    valor_hora_extra numeric(12,2),
    frecuencia_pago jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT remuneraciones_asistente_frecuencia_es_objeto CHECK ((jsonb_typeof(frecuencia_pago) = 'object'::text)),
    CONSTRAINT remuneraciones_asistente_unidad_conocida CHECK ((unidad_medicion = ANY (ARRAY['hora'::text, 'guardia'::text, 'semana'::text, 'mes'::text]))),
    CONSTRAINT remuneraciones_asistente_valores_no_negativos CHECK (((COALESCE(valor_hora, (0)::numeric) >= (0)::numeric) AND (COALESCE(sueldo_basico, (0)::numeric) >= (0)::numeric) AND (COALESCE(valor_guardia, (0)::numeric) >= (0)::numeric) AND (COALESCE(valor_semana, (0)::numeric) >= (0)::numeric) AND (COALESCE(valor_hora_extra, (0)::numeric) >= (0)::numeric)))
);


--
-- Name: TABLE remuneraciones_asistente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.remuneraciones_asistente IS 'Lo que cobra cada Asistente. Vive separado de `asistentes` porque las reglas de acceso de la base filtran filas, no columnas: solo en una tabla propia se puede exigir el permiso `ver_pagos_asistente` para leerlo.';


--
-- Name: COLUMN remuneraciones_asistente.unidad_medicion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.remuneraciones_asistente.unidad_medicion IS 'Con que se mide el trabajo de esta persona: hora, guardia, semana o mes. No es cada cuanto se le paga, que es otra cosa y se arregla aparte.';


--
-- Name: COLUMN remuneraciones_asistente.valor_hora_extra; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.remuneraciones_asistente.valor_hora_extra IS 'Cuanto se le paga la hora de mas. Puede ser igual o distinto al valor hora normal. Vacio quiere decir que no esta cargado: la liquidacion avisa y no estima.';


--
-- Name: COLUMN remuneraciones_asistente.frecuencia_pago; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.remuneraciones_asistente.frecuencia_pago IS 'Cada cuánto cobra esta persona. Sólo lo corrido respecto de lo de la Prestadora; vacío es lo de ella.';


--
-- Name: reportes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.reportes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    guardia_id uuid NOT NULL,
    texto_libre text,
    alimentacion jsonb,
    medicacion jsonb,
    signos_vitales jsonb,
    estado_animo text,
    incidentes text,
    observaciones text,
    foto_url text,
    ia_procesado boolean DEFAULT false NOT NULL,
    confirmado_asistente boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    paciente_id uuid NOT NULL
);


--
-- Name: COLUMN reportes.paciente_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.reportes.paciente_id IS 'De qué Paciente habla este reporte. Un turno que cubre a varios tiene un reporte por cada uno.';


--
-- Name: requerimientos_legales_de_hce_por_pais; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.requerimientos_legales_de_hce_por_pais (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    jurisdiccion text NOT NULL,
    requerimiento text NOT NULL,
    fuente text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE requerimientos_legales_de_hce_por_pais; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.requerimientos_legales_de_hce_por_pais IS 'Lo que la ley de cada país obliga a hacer al producto. Un renglón por país y requerimiento; sin renglón, no rige.';


--
-- Name: COLUMN requerimientos_legales_de_hce_por_pais.fuente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.requerimientos_legales_de_hce_por_pais.fuente IS 'La norma de donde sale el requerimiento, para que se pueda ir a leerla.';


--
-- Name: resoluciones_secuencia_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.resoluciones ALTER COLUMN secuencia ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.resoluciones_secuencia_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: resoluciones_vigentes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.resoluciones_vigentes WITH (security_invoker='true') AS
 SELECT DISTINCT ON (prestadora_id, tabla, fila_id) prestadora_id,
    tabla,
    fila_id,
    id AS resolucion_id,
    estado,
    motivo_id,
    detalle,
    resuelto_por,
    created_at
   FROM public.resoluciones r
  ORDER BY prestadora_id, tabla, fila_id, created_at DESC, secuencia DESC;


--
-- Name: VIEW resoluciones_vigentes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.resoluciones_vigentes IS 'La ultima resolucion de cada fila resuelta. De aca sale el estado que se ve.';


--
-- Name: respuestas_preparadas_whatsapp; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.respuestas_preparadas_whatsapp (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    nombre_interno text NOT NULL,
    terminos text[] DEFAULT '{}'::text[] NOT NULL,
    i18n jsonb NOT NULL,
    toca_salud boolean DEFAULT false NOT NULL,
    origen text DEFAULT 'prestadora'::text NOT NULL,
    activa boolean DEFAULT true NOT NULL,
    aprobada_at timestamp with time zone,
    aprobada_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT la_aprobacion_dice_quien_la_firmo CHECK (((aprobada_at IS NULL) = (aprobada_por IS NULL))),
    CONSTRAINT la_respuesta_preparada_sale_del_producto_o_de_la_ia CHECK ((origen = ANY (ARRAY['prestadora'::text, 'ia'::text]))),
    CONSTRAINT la_respuesta_preparada_tiene_nombre CHECK ((btrim(nombre_interno) <> ''::text)),
    CONSTRAINT la_respuesta_preparada_viene_en_los_tres_idiomas CHECK (interno.i18n_completo(i18n)),
    CONSTRAINT lo_que_toca_salud_no_se_aprueba CHECK (((NOT toca_salud) OR (aprobada_at IS NULL)))
);


--
-- Name: TABLE respuestas_preparadas_whatsapp; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.respuestas_preparadas_whatsapp IS 'El banco de respuestas preparadas de cada Prestadora. Es el único texto que la respuesta automática de WhatsApp puede mandar. Nace sin aprobar y no se usa hasta que la Prestadora la aprueba.';


--
-- Name: restricciones_de_cobranza; Type: TABLE; Schema: public; Owner: -
--

