--
-- Name: saldos_cliente; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.saldos_cliente WITH (security_invoker='true') AS
 SELECT f.id AS factura_id,
    f.prestadora_id,
    f.cliente_id,
    f.periodo,
    f.moneda,
    f.monto_total,
    f.monto_facturado,
    f.comprobante_tipo,
    f.comprobante_numero,
    f.facturado_at,
    co.neto AS correcciones_neto,
    co.correcciones_contadas,
    public.monto_a_cobrar_de_factura(f.monto_total, f.monto_facturado, f.id) AS monto_a_cobrar,
    r.cobrado,
    ((public.monto_a_cobrar_de_factura(f.monto_total, f.monto_facturado, f.id) - r.cobrado))::numeric(12,2) AS saldo,
    public.estado_de_factura(public.monto_a_cobrar_de_factura(f.monto_total, f.monto_facturado, f.id), r.cobrado, f.fecha_vencimiento) AS estado,
    f.estado AS estado_guardado,
    f.fecha_emision,
    f.fecha_vencimiento,
    r.cobros_contados,
    r.ultimo_cobro_fecha,
    r.origenes,
    f.updated_at AS actualizado_en,
    f.financiador_tipo,
    f.financiador_nombre
   FROM ((public.facturas_cliente f
     CROSS JOIN LATERAL public.resumen_cobros_de_factura(f.id) r(cobrado, cobros_contados, ultimo_cobro_fecha, origenes))
     CROSS JOIN LATERAL public.correcciones_de_factura(f.id) co(neto, correcciones_contadas));


--
-- Name: VIEW saldos_cliente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.saldos_cliente IS 'El saldo de cada factura de Cliente: lo que se le reclama menos lo cobrado, con el estado calculado, a quien se le reclama, de que origenes salio el dato y cuando se actualizo. Unico punto de verdad de esa resta.';


--
-- Name: series_guardias; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.series_guardias (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    asistente_id uuid,
    paciente_id uuid NOT NULL,
    dias_semana text[] NOT NULL,
    hora_inicio time without time zone NOT NULL,
    hora_fin time without time zone NOT NULL,
    modalidad text NOT NULL,
    vigente_desde date NOT NULL,
    vigente_hasta date,
    estado text DEFAULT 'activa'::text NOT NULL,
    cancelacion_origen text,
    cancelado_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    canal_modalidad text DEFAULT 'directa'::text NOT NULL,
    servicio_id uuid,
    dias_hasta_el_fin smallint DEFAULT 0 NOT NULL,
    CONSTRAINT series_guardias_canal_modalidad_check CHECK ((canal_modalidad = ANY (ARRAY['directa'::text, 'match'::text, 'subcontratacion'::text]))),
    CONSTRAINT series_guardias_cancelacion_check CHECK (((estado = 'cancelada'::text) OR ((cancelacion_origen IS NULL) AND (cancelado_at IS NULL)))),
    CONSTRAINT series_guardias_cancelacion_origen_check CHECK ((cancelacion_origen = ANY (ARRAY['cliente'::text, 'prestadora'::text]))),
    CONSTRAINT series_guardias_dias_hasta_el_fin_valido CHECK (((dias_hasta_el_fin >= 0) AND (dias_hasta_el_fin <= 3))),
    CONSTRAINT series_guardias_estado_check CHECK ((estado = ANY (ARRAY['activa'::text, 'cancelada'::text, 'pausada'::text])))
);


--
-- Name: COLUMN series_guardias.asistente_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.series_guardias.asistente_id IS 'NULL = serie sin Asistente fijo. Las guardias que genera nacen sin cubrir.';


--
-- Name: COLUMN series_guardias.paciente_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.series_guardias.paciente_id IS 'EN RETIRO. Guarda a uno solo de los Pacientes de la serie, el primero. La lista completa vive en series_guardias_pacientes. Sigue acá únicamente para que las pantallas todavía sin actualizar no se rompan.';


--
-- Name: COLUMN series_guardias.servicio_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.series_guardias.servicio_id IS 'De qué Servicio son las guardias de esta serie. Vacío mientras la serie no cuelgue de ninguno: hay trabajo que se hace y se factura sin Servicio armado.';


--
-- Name: COLUMN series_guardias.dias_hasta_el_fin; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.series_guardias.dias_hasta_el_fin IS 'Cuantos dias despues del dia de inicio termina cada turno de la serie.';


