-- Name: COLUMN usuarios.telefono_verificado_en; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.usuarios.telefono_verificado_en IS 'Cuándo se comprobó que este número es de esta persona, escribiendo el código que le llegó a él. Nulo quiere decir sin verificar, y así nacen todos los que ya estaban cargados: esa persona sigue entrando y recuperando por correo, y las vías del teléfono no se le ofrecen.';


--
-- Name: COLUMN usuarios.telefono_es_celular; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.usuarios.telefono_es_celular IS 'Si el telefono de esta cuenta es un celular reconocido. Lo completa un disparador con el catalogo de prefijos; no lo escribe ninguna pantalla.';


--
-- Name: COLUMN usuarios.telefono_comparable; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.usuarios.telefono_comparable IS 'La huella del telefono, para comparar dos numeros sin que ninguno viaje ni quede escrito. La calcula la base.';


--
-- Name: verificaciones_asistente; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.verificaciones_asistente (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    asistente_id uuid NOT NULL,
    etapa text NOT NULL,
    estado text DEFAULT 'pendiente'::text NOT NULL,
    notas text,
    revisado_por uuid,
    documento_url text,
    referencia_externa character varying(200),
    completado_en timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT verificaciones_asistente_estado_check CHECK ((estado = ANY (ARRAY['pendiente'::text, 'aprobada'::text, 'rechazada'::text])))
);


--
-- Name: versiones_registro_clinico; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.versiones_registro_clinico (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prestadora_id uuid NOT NULL,
    paciente_id uuid,
    tabla text NOT NULL,
    registro_id uuid NOT NULL,
    version integer NOT NULL,
    operacion text NOT NULL,
    datos jsonb NOT NULL,
    nota_aclaratoria text,
    autor_id uuid,
    credencial_rol text NOT NULL,
    momento timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT versiones_registro_clinico_operacion_check CHECK ((operacion = ANY (ARRAY['anterior_al_historial'::text, 'alta'::text, 'modificacion'::text, 'baja'::text]))),
    CONSTRAINT versiones_registro_clinico_version_check CHECK ((version > 0))
);


