-- Los permisos, desde cero. Supabase les da de fábrica todos los permisos a `anon`,
-- `authenticated` y `service_role` sobre cada tabla y cada función que se crea en `public`, y lo
-- que sigue sólo concede: sin este paso quedaría abierto lo que la base tenía cerrado.
DO $$
DECLARE
  o record;
BEGIN
  FOR o IN
    SELECT format('%I.%I', n.nspname, c.relname) AS nombre,
           CASE WHEN c.relkind = 'S' THEN 'SEQUENCE' ELSE 'TABLE' END AS clase
      FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE n.nspname IN ('public', 'interno') AND c.relkind IN ('r', 'v', 'm', 'p', 'S', 'f')
  LOOP
    EXECUTE format('REVOKE ALL ON %s %s FROM PUBLIC, anon, authenticated, service_role, trabajo_sin_persona',
                   o.clase, o.nombre);
  END LOOP;
  FOR o IN
    SELECT p.oid::regprocedure::text AS nombre,
           CASE WHEN p.prokind = 'p' THEN 'PROCEDURE' ELSE 'FUNCTION' END AS clase
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname IN ('public', 'interno') AND p.prokind IN ('f', 'p')
  LOOP
    EXECUTE format('REVOKE ALL ON %s %s FROM anon, authenticated, service_role, trabajo_sin_persona',
                   o.clase, o.nombre);
  END LOOP;
END $$;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public REVOKE ALL ON TABLES FROM PUBLIC, anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public REVOKE ALL ON SEQUENCES FROM PUBLIC, anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public REVOKE ALL ON FUNCTIONS FROM PUBLIC, anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA interno REVOKE ALL ON TABLES FROM PUBLIC, anon, authenticated, service_role;
