-- Las filas que el producto trae de fábrica.

INSERT INTO public.advertencias_legales (id, jurisdiccion, funcion_clave, texto_advertencia, created_at, updated_at)
SELECT id, jurisdiccion, funcion_clave, texto_advertencia, created_at, updated_at
  FROM jsonb_populate_recordset(NULL::public.advertencias_legales, $fila$[
{"created_at": "2026-07-18T15:58:22.903545+00:00", "funcion_clave": "horarios_fijos", "id": "3c5cd231-50bd-460b-9bc1-0ed62a6dc95a", "jurisdiccion": "AR", "texto_advertencia": "Imponer horarios fijos (en vez de que el Asistente decida su disponibilidad) es uno de los indicios más fuertes de subordinación bajo el art. 23 de la LCT.", "updated_at": "2026-07-18T15:58:22.903545+00:00"},
{"created_at": "2026-07-18T15:58:22.903545+00:00", "funcion_clave": "limite_oportunidades_rechazos", "id": "abc501cd-7b51-4a24-b38b-2dafb048a91a", "jurisdiccion": "AR", "texto_advertencia": "Limitar a un Asistente autónomo por rechazar Guardias reduce su libertad real de decidir su participación, un elemento central para sostener que la relación es autónoma y no dependiente (art. 23 LCT).", "updated_at": "2026-07-18T15:58:22.903545+00:00"},
{"created_at": "2026-07-18T15:58:22.903545+00:00", "funcion_clave": "niveles_categorias", "id": "7963785c-2dde-42d0-bb73-f6e8419e2514", "jurisdiccion": "AR", "texto_advertencia": "Establecer niveles o categorías jerárquicas puede interpretarse como una estructura organizativa propia de relación de dependencia (art. 23 LCT).", "updated_at": "2026-07-18T15:58:22.903545+00:00"},
{"created_at": "2026-07-18T15:58:22.903545+00:00", "funcion_clave": "penalizacion_inasistencias", "id": "487ee815-9cf1-48b4-9de6-41f6848f0acd", "jurisdiccion": "AR", "texto_advertencia": "Penalizar inasistencias o inconductas de un Asistente autónomo puede interpretarse como ejercicio de poder disciplinario, un indicio de subordinación bajo el art. 23 de la LCT. Conviene evaluar si esta función es coherente con la modalidad de vínculo de los Asistentes.", "updated_at": "2026-08-16T04:27:10.818044+00:00"},
{"created_at": "2026-07-18T15:58:22.903545+00:00", "funcion_clave": "puntuacion_aceptacion_guardia", "id": "5e3e82e8-1abd-4c2c-a55c-22ddeceb9ac0", "jurisdiccion": "AR", "texto_advertencia": "Puntuar la aceptación de Guardias y usarlo para asignar futuras oportunidades puede funcionar como una exigencia de disponibilidad, un indicio de subordinación (art. 23 LCT) más que de autonomía real del Asistente.", "updated_at": "2026-07-18T15:58:22.903545+00:00"},
{"created_at": "2026-07-18T15:58:22.903545+00:00", "funcion_clave": "puntuacion_calificacion_cliente", "id": "8736dc7d-b4f1-4bb8-aba5-30279d0e10b1", "jurisdiccion": "AR", "texto_advertencia": "Condicionar oportunidades futuras a una calificación de terceros puede interpretarse como una forma de evaluación de desempeño propia de una relación laboral (art. 23 LCT).", "updated_at": "2026-07-18T15:58:22.903545+00:00"},
{"created_at": "2026-07-18T15:58:22.903545+00:00", "funcion_clave": "rankings", "id": "be44b65a-5d14-4265-ad73-a65805dc65d9", "jurisdiccion": "AR", "texto_advertencia": "Publicar rankings que condicionan el acceso futuro a Guardias puede interpretarse como una forma de control jerárquico propia de una relación de dependencia (art. 23 LCT).", "updated_at": "2026-07-18T15:58:22.903545+00:00"},
{"created_at": "2026-07-25T14:52:03.895284+00:00", "funcion_clave": "consecuencia_automatica_calificacion", "id": "7f8422aa-f4b6-462d-8b94-958902845ac6", "jurisdiccion": "AR", "texto_advertencia": "Atar una exclusión automática a la calificación agregada convierte la opinión de los Clientes en una decisión algorítmica de la plataforma sobre el Asistente, un indicio de subordinación bajo el art. 23 de la LCT.", "updated_at": "2026-07-25T14:52:03.895284+00:00"},
{"created_at": "2026-07-25T14:52:03.895284+00:00", "funcion_clave": "exclusividad_match", "id": "d6ea92ab-3835-4d99-9961-22f3214155cb", "jurisdiccion": "AR", "texto_advertencia": "Exigir exclusividad reduce la libertad real del Asistente de trabajar para otros, elemento central para sostener autonomía y no dependencia (art. 23 LCT).", "updated_at": "2026-07-25T14:52:03.895284+00:00"},
{"created_at": "2026-07-25T14:52:03.895284+00:00", "funcion_clave": "mediacion_conflictos_match", "id": "b2850179-4cf0-4a53-96f2-91c5c85ee51a", "jurisdiccion": "AR", "texto_advertencia": "Mediar activamente en conflictos entre Cliente y Asistente puede interpretarse como dirección del vínculo, un indicio de subordinación bajo el art. 23 de la LCT.", "updated_at": "2026-07-25T14:52:03.895284+00:00"},
{"created_at": "2026-07-25T14:52:03.895284+00:00", "funcion_clave": "precio_horario_fijado_plataforma", "id": "6fca8f7e-d8f1-4121-b3d4-12b68540c165", "jurisdiccion": "AR", "texto_advertencia": "Fijar precio u horario de forma centralizada, en vez de que cada Cliente lo acuerde con su Asistente, es un indicio fuerte de subordinación bajo el art. 23 de la LCT.", "updated_at": "2026-07-25T14:52:03.895284+00:00"},
{"created_at": "2026-07-25T14:52:03.895284+00:00", "funcion_clave": "ranking_plataforma", "id": "c972d73f-3122-433c-b88c-9fafbd247884", "jurisdiccion": "AR", "texto_advertencia": "Un ranking calculado por la plataforma que condiciona si el Asistente sigue visible para cualquier Cliente puede interpretarse como la plataforma decidiendo su acceso al trabajo en general, un indicio de subordinación bajo el art. 23 de la LCT — mismo hecho que pesó en contra de Uber en el caso Aslam (Reino Unido, 2021).", "updated_at": "2026-07-25T14:52:03.895284+00:00"},
{"created_at": "2026-07-26T02:11:21.227773+00:00", "funcion_clave": "medicacion_via_sin_matricula", "id": "4bd33023-ee81-4b50-bc4e-bae625bf2620", "jurisdiccion": "AR", "texto_advertencia": "Ningún Asistente actualmente asignado a este Paciente cuenta con la habilitación profesional requerida para esta vía de administración (ej. aplicación de inyectables exige enfermero/a matriculado/a). Aceptar esta indicación sin asignar un Asistente habilitado puede generar responsabilidad por mala praxis ante un incidente.", "updated_at": "2026-08-01T20:46:12.310262+00:00"}
]$fila$::jsonb);

