{"activo": true, "admite_texto_propio": false, "clave": "comun.saludo", "created_at": "2026-09-19T18:55:45.335187+00:00", "i18n": {"en": "Hi {{nombre}},", "es-AR": "Hola {{nombre}},", "pt-BR": "Olá {{nombre}},"}, "id": "18f50c16-dae5-498a-b355-916324fbcdc4", "prestadora_id": null},
{"activo": true, "admite_texto_propio": false, "clave": "comun.tendria_que_haber_empezado", "created_at": "2026-09-19T18:55:45.335187+00:00", "i18n": {"en": "It should have started {{horas}} h ago.", "es-AR": "Tendría que haber empezado hace {{horas}} h.", "pt-BR": "Deveria ter começado há {{horas}} h."}, "id": "6c8a13ec-8e2b-4f9d-b35c-a24b89ae3136", "prestadora_id": null},
